window.__ARXIV_DATA__ = {"papers":[{"id":"2609.02886v1","title":"SolarWM: Open Data and Scalable Training for Long-Horizon Video World Models","abstract":"We introduce SolarWM, a fully open foundation for building interactive video world models from data preparation through long-horizon inference. Training across heterogeneous data sources and video backbones is challenging: datasets differ in temporal scale, camera geometry, visual quality, motion, and captioning styles, while video generators use distinct representations and architectures. Naive data mixing and model-specific implementations therefore produce inconsistent supervision and make results difficult to reproduce and compare. SolarWM addresses this coupling with a reconfigurable multi-source data engine and a backbone-native adaptation framework. The engine converts 1.43 million canonical clips from 10 datasets into a unified, frame-aligned contract covering visual observations, metric camera geometry, captions, quality metadata, selection decisions, and provenance, while decoupling source processing from mixture construction. Under shared camera-conditioning, training, and inference interfaces, we instantiate four 5B--33B models based on Wan2.2, LTX-2.5, and MiniMax-H3 while preserving their native representations and objectives. A unified three-stage recipe combines bidirectional adaptation, teacher-forced autoregressive initialization, and distribution matching distillation. The resulting causal models enable real-time interaction over rollouts ranging from minutes to hours after being trained on only 5s sequences. By releasing the resulting data, pipeline, recipes, weights, and framework, SolarWM provides a reproducible and extensible foundation for interactive world-model research.","authors":["Junchao Huang","Guian Fang","Shengju Qian","Xianghao Kong","Zhuoran Zhao","Wei Huang","Yihua Du","Zixin Zhang","Justin Cui","Yuchao Gu","Yukang Chen","Xinting Hu","Tianyu He","Shaoshuai Shi","Zhuotao Tian","Xin Wang","Mike Zheng Shou","Li Jiang"],"published":"2026-09-02T17:59:41Z","updated":"2026-09-02T17:59:41Z","abstract_url":"https://arxiv.org/abs/2609.02886v1","html_url":"https://arxiv.org/html/2609.02886v1","pdf_url":"https://arxiv.org/pdf/2609.02886v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":82541,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：We introduce SolarWM, a fully open foundation for building interactive video world models from data preparation through long-horizon inference. Training across heterogeneous data sources and video backbones is challenging: datasets differ in temporal scale, c...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02864v1","title":"Thinking in Pictures: A Systematic Benchmark for Reasoning-driven Image Generation","abstract":"Recent advancements in unified generative models (UGMs) and world simulators have achieved unprecedented results in visual perception and synthesis. However, these models primarily rely on surface-level event alignment, leaving the capacity for high-level visual reasoning underexplored. True visual generative intelligence demands \"Reasoning-to-Generation\", an ability to infer latent rules from visual inputs and manifest solutions through precise, logically constrained visual outcomes. We introduce RIG-BENCH, a novel comprehensive benchmark that systematically evaluates Reasoning-driven Image Generation (RIG) across four cognitively demanding domains: Concept-based, Transformation-based, Pattern & Structure, and Scenario-based. Featuring 2000 curated samples, RIG-BENCH serves as a rigorous stress test for RIG. Our extensive evaluations of state-of-the-art UGMs and image/video generation models reveal a significant reasoning-generation gap, wherein models frequently produce locally plausible but globally illogical outputs. RIG-BENCH provides a vital diagnostic framework to guide the development of next-generation, logically grounded UGMs and world simulators.","authors":["Yutong Liu","Nan Huang","Xu Cao","James M. Rehg"],"published":"2026-09-02T17:48:02Z","updated":"2026-09-02T17:48:02Z","abstract_url":"https://arxiv.org/abs/2609.02864v1","html_url":"https://arxiv.org/html/2609.02864v1","pdf_url":"https://arxiv.org/pdf/2609.02864v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":84686,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Recent advancements in unified generative models (UGMs) and world simulators have achieved unprecedented results in visual perception and synthesis. However, these models primarily rely on surface-level event alignment, leaving the capacity for high-level vis...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02860v1","title":"PlantC2USeg: Cross-Scale Consistent Pre-Training for Few-Shot Unified Plant Point Cloud Segmentation","abstract":"Modern crop breeding demands precise organ-level analysis for trait quantification, making plant point cloud segmentation (PPCS) increasingly important. However, conventional deep learning approaches rely heavily on densely annotated datasets that are labor-intensive to acquire. Unified PPCS adaptation from distribution-shifted examples with minimal additional training remains challenging. To address this, we propose PlantC2USeg, a deep transfer learning framework featuring cross-scale consistency learning to explicitly align features across spatial scales and an information-restricted decoding strategy that prevents reconstruction shortcuts and promotes robust adaptation. The resulting pre-training enables stable few-shot generalization across species and sensing conditions, while unified fine-tuning with inherited thresholds further reduces adaptation overhead. Under full supervision on Soybean3D, PlantC2USeg achieves the highest semantic IoU and instance mWCov among compared methods, at 91.91% and 94.62%. With 20 labeled samples, it leads both metrics at 89.78% and 90.27%; with only 10 samples, it retains the highest mWCov of 83.23% while achieving 83.19% IoU. Across HR3D, 10-shot transfer to tobacco, tomato, and sorghum averages 78.41% IoU and 79.42% mWCov, while 22-shot transfer to SYAU-Maize achieves the highest IoU and mRec at 92.75% and 93.51%. Furthermore, a leading category-averaged mIoU of 85.0% on ShapeNet Part demonstrates the framework's capability to handle diverse shape variations beyond agricultural domains. These results demonstrate that PlantC2USeg reduces overall adaptation effort under distribution shifts, enabling scalable plant phenotyping and transferable 3D representation learning beyond agriculture.","authors":["Yu Tian","Xintong Jiang","Jan Franklin Adamowski","Shiv O. Prasher","Shangpeng Sun"],"published":"2026-09-02T17:43:56Z","updated":"2026-09-02T17:43:56Z","abstract_url":"https://arxiv.org/abs/2609.02860v1","html_url":"https://arxiv.org/html/2609.02860v1","pdf_url":"https://arxiv.org/pdf/2609.02860v1.pdf","matched_keywords":["3d","representation","instance"],"source_used":"html","source_text_chars":118584,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, instance 相关；摘要显示其主要贡献为：Modern crop breeding demands precise organ-level analysis for trait quantification, making plant point cloud segmentation (PPCS) increasingly important. However, conventional deep learning approaches rely heavily on densely annotated datasets that are labor-i...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02854v1","title":"MuyBridge: Mobile Human Center-of-Mass Estimation from Monocular Video via Sparse Fusion","abstract":"The 3D center of mass (CoM) is a primary quantity in the biomechanical analysis of sport, rehabilitation, and clinical movement, yet existing 3D pose tracking, mesh recovery, and multi-view triangulation methods either optimize 3D keypoint accuracy without anatomical constraints or carry compute and capture infrastructure too heavy to deploy where CoM tracking is most useful. As a result, the metric CoM remains difficult for coaches and movement analysts to measure from a single camera where athletes train and compete. In this work, we introduce MuyBridge, an on-device system that estimates the athlete's segmental center of mass trajectory from a single phone camera video stream. MuyBridge couples a compact 2D pose network and a distilled single-step monocular depth network through an analytic metric fusion that uses anatomical and physical priors to anchor the metric CoM, requiring no 3D or task-specific supervision. Evaluated on the athletic movements of AthletePose3D (running, track and field, and figure skating), MuyBridge achieves 33-41 mm vertical CoM error and 2.3-6.6% absolute-relative range error (AbsRel) under a one-time calibration, and produces CoM estimates at the 63 FPS pose-estimation rate using asynchronous 2.86 Hz depth updates on iPhone 15. Code is available at: https://github.com/Abradshaw1/Muybridge","authors":["Aidan Bradshaw","Marco Giordano","David Rode","Andreas Habersack","Elif Basokur","Annika Kruse","Markus Tilp","Michele Magno","Peter Wolf","Luca Benini","Christoph Leitner"],"published":"2026-09-02T17:38:36Z","updated":"2026-09-02T17:38:36Z","abstract_url":"https://arxiv.org/abs/2609.02854v1","html_url":"https://arxiv.org/html/2609.02854v1","pdf_url":"https://arxiv.org/pdf/2609.02854v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":60104,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：The 3D center of mass (CoM) is a primary quantity in the biomechanical analysis of sport, rehabilitation, and clinical movement, yet existing 3D pose tracking, mesh recovery, and multi-view triangulation methods either optimize 3D keypoint accuracy without an...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02847v1","title":"RoGe: Novel View Synthesis via End-to-End Implicit Reconstruction and Generation","abstract":"Novel view synthesis from sparse inputs requires both geometric grounding from the observed views and generative priors of unobserved regions, motivating recent hybrid methods that combine reconstruction and generation. However, existing methods bridge the two with rendered images or explicit 3D representations such as point maps or 3D Gaussians. Generation is thus conditioned on a lossy and imperfect projection of the scene, inheriting its errors, and reconstruction receives no signal from generation to correct them. We present RoGe, an end-to-end unified reconstruction and generation framework that removes this explicit bridge. It targets roaming within a scene anchored by sparse views: given a few posed images and a camera trajectory, it synthesizes a temporally coherent video along that trajectory. From the sparse input views, RoGe builds an implicit scene representation with a feed-forward reconstruction model, and queries it with target camera rays to obtain per-view geometric features. These features are injected into a video diffusion model as conditioning, without any 3D intermediate. Both modules are trained jointly, so the generation objective directly shapes its own geometric conditioning. We conduct experiments on DL3DV, where RoGe outperforms reconstruction-based, generation-based, and hybrid baselines on image-level metrics and video-level temporal consistency. Ablations confirm that ray-queried implicit features outperform both raw reconstruction tokens and rendered RGB as conditioning, and that joint training brings further gains.","authors":["Xiaolei Lang","Ze Kang","Zehao Huang","Naiyan Wang"],"published":"2026-09-02T17:32:35Z","updated":"2026-09-02T17:32:35Z","abstract_url":"https://arxiv.org/abs/2609.02847v1","html_url":"https://arxiv.org/html/2609.02847v1","pdf_url":"https://arxiv.org/pdf/2609.02847v1.pdf","matched_keywords":["video","3d","representation","diffusion"],"source_used":"html","source_text_chars":53246,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d, representation, diffusion 相关；摘要显示其主要贡献为：Novel view synthesis from sparse inputs requires both geometric grounding from the observed views and generative priors of unobserved regions, motivating recent hybrid methods that combine reconstruction and generation. However, existing methods bridge the tw...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02839v1","title":"Efficient All-in-One Weather Restoration using Spectral Harmonization","abstract":"Adverse weather conditions such as rain, haze, and snow significantly degrade image quality, posing challenges for both human perception and physical AI. Existing restoration methods require large computational budgets, struggling to process high-resolution images and handle different degradations. In this paper, we present Frequency Reconstruction via Spectral Harmonization, a novel lightweight all-in-one restoration method that explicitly decomposes feature representations into high- and low-frequency components at each scale of a hierarchical encoder-decoder architecture. By combining spectral decomposition with spatial processing through Fourier-based skip connections, FReSH-IR captures complementary frequency information without sacrificing spatial detail. Our approach achieves similar restoration quality with 80% fewer parameters and operations than transformer-based models. Extensive experiments demonstrate that our method offers a great efficiency-performance trade-off, highlighting its practical applications in constrained-resource systems.","authors":["Paula Garrido-Mellado","Daniel Feijoo","Yuning Cui","Alvaro Garcia","Marcos V. Conde"],"published":"2026-09-02T17:21:06Z","updated":"2026-09-02T17:21:06Z","abstract_url":"https://arxiv.org/abs/2609.02839v1","html_url":"https://arxiv.org/html/2609.02839v1","pdf_url":"https://arxiv.org/pdf/2609.02839v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":54550,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Adverse weather conditions such as rain, haze, and snow significantly degrade image quality, posing challenges for both human perception and physical AI. Existing restoration methods require large computational budgets, struggling to process high-resolution i...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02813v1","title":"GDB-Reward: From Evaluation Metrics to Training Rewards for Graphic Design","abstract":"Text-to-image models excel at natural image synthesis but struggle with graphic design, where success depends on satisfying precise constraints on typography, layout, color, and visual communication. While prompt optimization offers an attractive alternative to expensive diffusion model fine-tuning, learning prompts for frozen image generators requires informative reward functions despite the entirely non-differentiable generation process. Reinforcement learning does not require differentiable objectives; it requires only scalar rewards capable of ranking candidate outputs. This raises a simple question: can design evaluation metrics themselves become reinforcement learning rewards? Our central contribution is GDB-Reward, a framework that systematically transforms heterogeneous graphic design evaluation metrics into a unified reinforcement learning reward. Experiments demonstrate that GDB-Reward provides an effective optimization objective, substantially improving adherence to the design specification in perceptual quality, rendering fidelity, and spatial accuracy while keeping the image generator entirely frozen. More broadly, our results demonstrate that heterogeneous, non-differentiable evaluation metrics can move beyond passive benchmarking to become effective optimization objectives for reinforcement learning in domains where differentiable supervision is unavailable.","authors":["Adrienne Deganutti","Purvanshi Mehta","Simon Hadfield","Andrew Gilbert"],"published":"2026-09-02T16:54:31Z","updated":"2026-09-02T16:54:31Z","abstract_url":"https://arxiv.org/abs/2609.02813v1","html_url":"https://arxiv.org/html/2609.02813v1","pdf_url":"https://arxiv.org/pdf/2609.02813v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":57167,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Text-to-image models excel at natural image synthesis but struggle with graphic design, where success depends on satisfying precise constraints on typography, layout, color, and visual communication. While prompt optimization offers an attractive alternative...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02780v1","title":"ShallowStream: Index Shallow then Answer Deep for Streaming Video Understanding","abstract":"Streaming video understanding is a critical capability for real-world applications, including embodied intelligence, autonomous driving, industrial monitoring, surveillance and early warning, and wearable assistants. However, processing continuous video streams with multimodal large language models (MLLMs) is computationally expensive. Existing efforts have explored reducing streaming overhead through visual token pruning, token merging, quantization, on-demand frame retrieval, and context offloading. However, most existing methods overlook the dimension of model depth. Repeatedly executing full-depth MLLM prefill over incoming frames is prohibitively expensive, incurring substantial computational overhead and causing the KV cache to grow at a rate directly proportional to the prefill depth. To address these challenges, we propose ShallowStream, a novel framework that leverages the shallow layers of an MLLM to simultaneously perform frame encoding and retrieval index building. During stream processing, ShallowStream maintains an always-on lightweight index using the KV cache of shallow layers. During query-time answering, we leverage the attention scores generated by the shallow layers to score context frames and employ a diversity-aware selection strategy to retrieve precise and comprehensive evidence. ShallowStream achieves performance on par with the strongest existing streaming methods, while reducing per-frame prefill latency and 10-second end-to-end latency by up to 52.1x and 11.9x, respectively. Our code is available at https://github.com/CURRENTF/ShallowStream.","authors":["Jitai Hao","Ke Yang","Qiang Huang","Jun Yu"],"published":"2026-09-02T16:14:48Z","updated":"2026-09-02T16:14:48Z","abstract_url":"https://arxiv.org/abs/2609.02780v1","html_url":"https://arxiv.org/html/2609.02780v1","pdf_url":"https://arxiv.org/pdf/2609.02780v1.pdf","matched_keywords":["video","retrieval","multimodal"],"source_used":"html","source_text_chars":76741,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, multimodal 相关；摘要显示其主要贡献为：Streaming video understanding is a critical capability for real-world applications, including embodied intelligence, autonomous driving, industrial monitoring, surveillance and early warning, and wearable assistants. However, processing continuous video strea...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02776v1","title":"Video-Based Palm-Vein Authentication under Challenging Conditions","abstract":"Palm-vein biometrics are increasingly used for secure, contactless authentication. Yet real-world deployment exposes them to surface noise (sweat, dirt), illumination and motion variation, and temperature-driven changes in vascular visibility, which remain underexplored for lack of data captured under such conditions. To study these effects, we introduce the Columbia University Palm-vein (CUP) dataset, to our knowledge the first public video-based palm-vein dataset. CUP records every palm under four surface conditions (a clean baseline, warm, wet, and dirty) and pairs each subject with physiological and demographic metadata. On it we benchmark twenty-one recognizers spanning static, video, and multi-frame aggregation architectures. Models that verify reliably on clean palms lose most of their accuracy on dirty ones, and the mean equal error rate (EER) roughly quadruples. We recover much of that robustness along both axes of the capture. Temporally, a consensus over the few frames the sensor already returns cancels transient corruption; spatially, a test-time matcher that adds no learned parameters fuses the global cosine with a saliency-steered region-level optimal transport that routes the comparison around corrupted regions. The full design leads on every surface of CUP in EER, TAR@FAR=0.01, and Rank-1, at 4.3M parameters and 3.1 GFLOPs, a fraction of the video models' cost. Attached to four frozen state-of-the-art backbones it cuts their mean EER by 29-37% without retraining, and on four public single-image datasets the regional matching alone still helps. A preliminary audit across ten demographic and physiological traits finds two warm-condition gaps, along body water and gender, that survive multiple-comparison correction. CUP will be released for non-commercial research use at https://github.com/MobileX-CU/CUP_v1 upon publication.","authors":["Xiaofeng Yan","Kechen Liu","Abhilash Venkatesh","Cathy Zhang","Xia Zhou","Salvatore Stolfo"],"published":"2026-09-02T16:12:27Z","updated":"2026-09-02T16:12:27Z","abstract_url":"https://arxiv.org/abs/2609.02776v1","html_url":"https://arxiv.org/html/2609.02776v1","pdf_url":"https://arxiv.org/pdf/2609.02776v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":85454,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Palm-vein biometrics are increasingly used for secure, contactless authentication. Yet real-world deployment exposes them to surface noise (sweat, dirt), illumination and motion variation, and temperature-driven changes in vascular visibility, which remain un...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02747v1","title":"InceptionGS: Generative Bootstrapping for Large-Scale Gaussian Splatting under Unstructured View Sampling","abstract":"Achieving truly immersive large-scale scene digitization necessitates consistent and visually pleasing rendering across all possible viewing perspectives. However, collecting multi-view images covering every fine detail of a large-scale scene is prohibitive due to scene complexity, capture cost, negligence, or accessibility constraints. As a result, the sampled views tend to be highly unstructured -- the majority of the scene is well covered yet certain regions inevitably lack sufficient observations. Existing reconstruction based methods are vulnerable to view scarcity while generation based approaches suffer from generalization, controllability, and 3D consistency issues. To address this challenge, we propose InceptionGS, which bootstraps Gaussian splatting by subtly balancing reconstruction and generation. Starting from an initial Gaussian splatting, InceptionGS reasonably rethinks and repairs problematic regions caused by view scarcity while preserving the quality elsewhere, by softly incorporating scene- and view-adaptive generative priors. Extensive experiments on real-world large-scale scenes demonstrate the superiority and broad applicability of our approach in handling unstructured imagery and boosting high-fidelity Gaussian splatting. Please refer to the supplementary video for better visual demonstrations.","authors":["Tianheng Lu","Guangyu Wang","Ruqi Huang","Lu Fang"],"published":"2026-09-02T15:48:15Z","updated":"2026-09-02T15:48:15Z","abstract_url":"https://arxiv.org/abs/2609.02747v1","html_url":"https://arxiv.org/html/2609.02747v1","pdf_url":"https://arxiv.org/pdf/2609.02747v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":60930,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Achieving truly immersive large-scale scene digitization necessitates consistent and visually pleasing rendering across all possible viewing perspectives. However, collecting multi-view images covering every fine detail of a large-scale scene is prohibitive d...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02731v1","title":"RVSD: Retrieval Vision Sparse Decoding for Mitigating Visual Hallucinations in Large Vision-Language Models","abstract":"Large vision-language models have achieved remarkable success in vision-language tasks. However, they remain prone to Visual Hallucinations (VHs), undermining their reliability in real-world applications. Existing solutions typically require curated datasets, additional training, or multi-round decoding, resulting in considerable computational overhead. In this paper, we propose \\textbf{RVSD} (\\underline{R}etrieval \\underline{V}ision \\underline{S}parse \\underline{D}ecoding), a training-free and plug-and-play decoding framework that, for the first time, unifies token sparsification and \\textbf{Semantic-Space Visual Retrieval} (SSVR) within a single decoding pass. Within RVSD, we introduce a \\textbf{semantics-directed token selection} strategy that selectively sparsifies redundant tokens while preserving critical visual information. We further propose the SSVR mechanism, which reformulates visual compensation as an on-demand cross-modal retrieval process within a shared semantic space. Extensive experiments demonstrate that RVSD achieves state-of-the-art performance in mitigating VHs while maintaining robust suppression capabilities under long-context generation settings. Our code is available here.\\footnote{https://github.com/canjie-liu/RVSD}","authors":["Canjie Liu","Jiawen Kang","Jinbo Wen","Zishao Zhong"],"published":"2026-09-02T15:40:40Z","updated":"2026-09-02T15:40:40Z","abstract_url":"https://arxiv.org/abs/2609.02731v1","html_url":"https://arxiv.org/html/2609.02731v1","pdf_url":"https://arxiv.org/pdf/2609.02731v1.pdf","matched_keywords":["retrieval"],"source_used":"html","source_text_chars":82346,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval 相关；摘要显示其主要贡献为：Large vision-language models have achieved remarkable success in vision-language tasks. However, they remain prone to Visual Hallucinations (VHs), undermining their reliability in real-world applications. Existing solutions typically require curated datasets,...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02717v1","title":"MV-dVRK: A Multi-Viewpoint Benchmark for Spatial Surgical Perception","abstract":"Large-scale training and refined optimization techniques have greatly improved sparse multi-view 3D reconstruction. Despite their relevance to surgery, such methods have never before been rigorously evaluated on real endoscopic images. Current clinical telerobots deploy a single stereo camera inside the patient, making multi-viewpoint data extremely rare. This paper presents MV-dVRK, the first ex-vivo surgical dataset to combine multiple exposure-synchronized stereo viewpoints with accurate surface geometry and camera poses. The static subset of the benchmark provides dense SfM reference geometry, validated against an industrial 3D scanner, together with ground-truth camera poses and sparse-view test sets. We use MV-dVRK to systematically compare zero-shot monocular, stereo, multi-stereo, and multi-view 3D reconstruction methods as the number of viewpoints increases. With two endoscopes, multi-stereo reconstruction achieves the highest coverage. With a third viewpoint, optimization-based multi-view methods perform best, covering 67% of ground-truth surface points within a 1 mm tolerance and recovering highly accurate relative camera poses. By contrast, feed-forward foundation models cover only 43% of the ground-truth surface in the same setting. MV-dVRK also includes ten dynamic sequences spanning multiple surgical tasks, with increasing kinematic complexity and tissue deformation, providing a basis for future research in multi-viewpoint surgical perception. The project is available at: https://mv-dvrk.is.mpg.de.","authors":["Guido Caccianiga","Sergey Prokudin","Yutong Chen","Bernard Javot","Rachael L'Orsa","Omer Burak Aladağ","Yarden Sharon","Jens Rolinger","Ivan Capobianco","Anton Deguet","Siyu Tang","Katherine J. Kuchenbecker"],"published":"2026-09-02T15:25:28Z","updated":"2026-09-02T15:25:28Z","abstract_url":"https://arxiv.org/abs/2609.02717v1","html_url":"https://arxiv.org/html/2609.02717v1","pdf_url":"https://arxiv.org/pdf/2609.02717v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":52855,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Large-scale training and refined optimization techniques have greatly improved sparse multi-view 3D reconstruction. Despite their relevance to surgery, such methods have never before been rigorously evaluated on real endoscopic images. Current clinical telero...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02697v1","title":"Generating Medical Image Counterfactuals using Causal Explanations","abstract":"Deep learning models have achieved impressive performance in medical image diagnosis, yet their deployment in clinical settings remains constrained by limited explainability. Counterfactual images provide one means of auditing model behavior by showing how an image would need to change for a classifier to produce a different prediction. Existing approaches typically generate such explanations using auxiliary models, including generative adversarial networks and diffusion models. While often capable of producing visually realistic images, these methods explain one black-box model using another, making it difficult to separate the classifier's decision-making process from the inductive biases of the generator. We propose a novel counterfactual-generation framework that requires no generative model. Instead, counterfactuals are constructed directly from causal evidence extracted from the classifier. The resulting approach is deterministic, requires no additional model training, and enables controllable edits within user-specified regions of interest. Experiments on real-world medical imaging datasets demonstrate that the proposed method successfully changes classifier predictions while remaining closer to the original image than generative baselines, providing a more direct and transparent view of the classifier's decision boundary.","authors":["David A. Kelly","Tom Yaacov","Nathan Blake","Sander Beckers","Hana Chockler"],"published":"2026-09-02T15:03:42Z","updated":"2026-09-02T15:03:42Z","abstract_url":"https://arxiv.org/abs/2609.02697v1","html_url":"https://arxiv.org/html/2609.02697v1","pdf_url":"https://arxiv.org/pdf/2609.02697v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":48857,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Deep learning models have achieved impressive performance in medical image diagnosis, yet their deployment in clinical settings remains constrained by limited explainability. Counterfactual images provide one means of auditing model behavior by showing how an...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02689v1","title":"GaLe: memory-efficient Global Approximate and Local Exact features","abstract":"Embedded devices typically lack the resources of GPU-equipped machines, and existing inference methods suffer from either high computational overhead (patch-based) or accuracy loss (approximation-based). We propose GaLe, a memory-efficient technique that enables the deployment of pretrained networks on constrained devices without retraining. GaLe partitions feature maps into two components: a local exact (Le) representation that preserves fine details and a global approximate (Ga) representation that retains long-range dependencies. Unlike standard tiling, GaLe supports global operations and attention mechanisms found in hybrid CNN-transformer models. Validated on ImageNet, our method matches exact-inference performance while achieving up to 65% speedup and 90% RAM reduction on a Cortex-M33 compared to patch-based inference. We further demonstrate GaLe's versatility across classification, detection, and generation tasks, highlighting its potential as a foundation for resource-efficient architecture design.","authors":["Alberto Ancilotto","Elisabetta Farella"],"published":"2026-09-02T14:56:18Z","updated":"2026-09-02T14:56:18Z","abstract_url":"https://arxiv.org/abs/2609.02689v1","html_url":"https://arxiv.org/html/2609.02689v1","pdf_url":"https://arxiv.org/pdf/2609.02689v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":41215,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Embedded devices typically lack the resources of GPU-equipped machines, and existing inference methods suffer from either high computational overhead (patch-based) or accuracy loss (approximation-based). We propose GaLe, a memory-efficient technique that enab...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02664v1","title":"Query Rewriting for Complex Object Segmentation in 4D Gaussian Representations","abstract":"Recent 4D Gaussian representation frameworks have demonstrated strong performance in language-guided dynamic scene understanding. However, these methods remain highly sensitive to verbose and narrative-style queries that contain noisy contextual information. In this paper, we investigate the impact of query rewriting for complex object segmentation in 4D Gaussian representations. Inspired by recent findings in retrieval-augmented language models and keyword-guided query reformulation, we propose a training-free reinterpretation strategy that transforms long descriptive queries into concise keyword-grounded forms. Our approach progressively reduces linguistic noise while preserving semantic anchors relevant to object-centric representations. Experiments on HyperNeRF and Neu3D demonstrate that concise rewritten queries significantly improve both temporal localization and spatial segmentation performance. In particular, our method improves average temporal accuracy from 60.92% to 92.21% and average vIoU from 20.08% to 76.94% without any additional fine-tuning. Extensive ablation studies further reveal that shorter, keyword-focused queries consistently yield stable video-feature similarity distributions and better alignment with object-centric Gaussian representations","authors":["Thanh-Khoi Nguyen","Thien-Phuc Tran","Minh-Triet Tran"],"published":"2026-09-02T14:40:22Z","updated":"2026-09-02T14:40:22Z","abstract_url":"https://arxiv.org/abs/2609.02664v1","html_url":"https://arxiv.org/html/2609.02664v1","pdf_url":"https://arxiv.org/pdf/2609.02664v1.pdf","matched_keywords":["video","retrieval","3d","representation"],"source_used":"html","source_text_chars":43080,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, 3d, representation 相关；摘要显示其主要贡献为：Recent 4D Gaussian representation frameworks have demonstrated strong performance in language-guided dynamic scene understanding. However, these methods remain highly sensitive to verbose and narrative-style queries that contain noisy contextual information....","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02663v1","title":"Characterizing Text Branch Sensitivity in Medical Vision-Language Segmentation via Evidence Decoupling","abstract":"Pretrained vision-language models (VLMs) have shown promising performance in medical image segmentation by incorporating clinical text. However, it remains unclear how much textual information actually contributes to pixel-level predictions. In this work, we systematically investigate the role of text in multimodal medical image segmentation. We first analyze several commonly used fusion strategies and find that segmentation performance is largely insensitive to the choice of fusion module. To further understand modality interactions, we propose an Evidence Decoupling Decoder (EDD) based on evidential deep learning and deep supervision. EDD serves as an internal representation analysis tool that decomposes image evidence and text-modulated evidence throughout the decoding process while maintaining competitive segmentation performance. Experimental results show that the sensitivity to text perturbation varies substantially across datasets. On BUSI and BTMRI, removing text causes catastrophic performance drops, indicating strong model reliance on textual input. On ISIC and Kvasir-SEG, text exerts relatively marginal influence. We further find that text affects predictions mainly through global semantic modulation rather than independent spatial localization, and that the specific semantic components driving text sensitivity differ across datasets. These findings provide a deeper understanding of modality interaction in multimodal medical image segmentation and offer practical insights for future model design.","authors":["Ziquan Liu","Zhewei Zhu","Xuyang Shi"],"published":"2026-09-02T14:38:52Z","updated":"2026-09-02T14:38:52Z","abstract_url":"https://arxiv.org/abs/2609.02663v1","html_url":"https://arxiv.org/html/2609.02663v1","pdf_url":"https://arxiv.org/pdf/2609.02663v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":45094,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：Pretrained vision-language models (VLMs) have shown promising performance in medical image segmentation by incorporating clinical text. However, it remains unclear how much textual information actually contributes to pixel-level predictions. In this work, we...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02644v1","title":"Learning to Attract and Repel: Dual Quality Margin Learning for Face Recognition (DQM-Face)","abstract":"Face recognition in unconstrained environments remains highly challenging due to diverse and extreme variations encountered in real-world scenarios. To mitigate these effects, existing margin-based approaches model sample quality through feature magnitude. However, magnitude-based modeling alone is susceptible to identity-agnostic noise, which can degrade the reliability and discriminative power of learned representations. In this paper, we propose Dual Quality Margin Learning for Face Recognition (DQM-Face), a novel framework that enables refined attraction and repulsion dynamics during representation learning. Our approach unifies conventional magnitude-based quality estimation with a newly introduced semantic quality learning mechanism, realized via squeeze-and-excitation semantic attention. By jointly leveraging magnitude and semantic cues, we construct enhanced quality-aware margins that adaptively strengthen intra-class compactness through improved attraction during learning. To further enhance inter-class discrimination, we introduce a repulsion margin formulation that explicitly enlarges inter-class separation. The unified integration of semantic quality modeling with dual attraction-repulsion margin optimization results in a more structured and discriminative feature geometry. Extensive experiments on multiple challenging benchmarks demonstrate that DQM-Face consistently outperforms state-of-the-art face recognition methods. Moreover, we show that the quality learned for margin optimization is highly effective for face image quality assessment within the proposed framework, demonstrating that the learned quality signal is intrinsically aligned with the recognition objective. The code is publicly available: https://github.com/RAIB-group/DQM-Face","authors":["El Ouanas Belabbaci","Bhavesh Wani","Philipp Terhörst"],"published":"2026-09-02T14:19:43Z","updated":"2026-09-02T14:19:43Z","abstract_url":"https://arxiv.org/abs/2609.02644v1","html_url":"https://arxiv.org/html/2609.02644v1","pdf_url":"https://arxiv.org/pdf/2609.02644v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":56398,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Face recognition in unconstrained environments remains highly challenging due to diverse and extreme variations encountered in real-world scenarios. To mitigate these effects, existing margin-based approaches model sample quality through feature magnitude. Ho...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02616v1","title":"AffectDelta: Beyond Emotion Labels for Image Editing","abstract":"Emotion-driven image editing aims to evoke a specified target emotion by modifying emotion-relevant visual cues in a source image, while preserving the overall composition and semantic-structural coherence of the original scene. Existing scene-level editors typically specify the target with a single emotion category and often learn visual transformations from operation-level text instructions. A category collapses a mixed affective endpoint into one dominant label, while language cannot precisely quantify how coexisting emotions should increase, decrease, or remain stable. We introduce AffectDelta, a source-aware editor that treats editing as a transition between eight-dimensional emotion distributions. A frozen Emotion Distribution Predictor estimates the source state, and the signed source-to-target difference encodes the direction and magnitude of the requested transition. Within AffectDelta, an internal transition encoder and a source-aware diffusion backbone jointly translate this signal into context-dependent semantic and appearance changes. To train this formulation, we construct AffectPair-249K, comprising 248,841 source-target pairs with predicted eight-dimensional distributions and spanning both cross-category and within-category transitions. Experiments against six baselines, combining quantitative evaluation with qualitative comparisons, demonstrate improved affective alignment and content preservation, while ablations validate our design choices. Code and dataset will be made publicly available upon acceptance.","authors":["Xingzu Zhan","Lin Gu","Ruogu Fang"],"published":"2026-09-02T13:56:59Z","updated":"2026-09-02T13:56:59Z","abstract_url":"https://arxiv.org/abs/2609.02616v1","html_url":"https://arxiv.org/html/2609.02616v1","pdf_url":"https://arxiv.org/pdf/2609.02616v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":60907,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Emotion-driven image editing aims to evoke a specified target emotion by modifying emotion-relevant visual cues in a source image, while preserving the overall composition and semantic-structural coherence of the original scene. Existing scene-level editors t...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02573v1","title":"Deeply Interleaved Text-Image Contexts for Multimodal LLMs Assessment","abstract":"Current evaluations and training of multimodal models predominantly focus on multi-image tasks, largely overlooking interleaved text-image scenarios. In such multi-image tasks, text typically serves merely as task instructions, lacking deep semantic interaction with the visual content. In contrast, realworld applications like text-image co-creation, character tracking, and spatial reconstruction require constant interaction between text and images. Consequently, models must possess a deep understanding of these interleaved contexts. To bridge this gap, we introduce a novel benchmark, TIC-Bench (deeply interleaved Text-Image Contexts), designed to evaluate the capability of models to integrate text-image clues and recover the ground truth facts within deeply interleaved contexts. This benchmark encompasses three core domains: Logical, Temporal, and Spatial Association, which are further categorized into eight specific types, comprising a total of 2,280 questions. We evaluated 10 state-of-the-art MLLMs and observed a substantial performance gap compared to human experts, together with persistent difficulties in integrating evidence distributed across interleaved visual and textual inputs. Ultimately, this benchmark provides a valuable analytical tool for assessing and advancing the ability of multimodal models to effectively integrate text and image information in deeply interleaved contexts. TIC-Bench is publicly available at https://huggingface.co/datasets/pino10010/TIC-Bench","authors":["Zihao Wang","Xi Xiang","Yuwen Sun","Yingyu Li","Yabo Zhang","Yihan Zeng","Fan Li","Wangmeng Zuo"],"published":"2026-09-02T13:19:51Z","updated":"2026-09-02T13:19:51Z","abstract_url":"https://arxiv.org/abs/2609.02573v1","html_url":"https://arxiv.org/html/2609.02573v1","pdf_url":"https://arxiv.org/pdf/2609.02573v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":73893,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Current evaluations and training of multimodal models predominantly focus on multi-image tasks, largely overlooking interleaved text-image scenarios. In such multi-image tasks, text typically serves merely as task instructions, lacking deep semantic interacti...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02565v1","title":"MARS: What Retrieval Signals Are Hidden in Multimodal Large Language Models for Text-Video Retrieval?","abstract":"Text-video retrieval requires representations that can distinguish videos with similar scenes, actions, and temporal patterns. Recent multimodal large language models have been adapted as embedding models, but they often represent each input using a single token from the final layer. This can compress diverse video-text cues into a single vector and limit fine-grained retrieval. To address this limitation, we propose MARS, a multi-layer and multi-slot embedding framework for text-video retrieval. MARS constructs multiple adaptive representation slots by combining hidden states from different decoder layers, compares corresponding text and video slots, and aggregates their similarities for retrieval. To better handle confusing candidates, we further introduce a hard-negative-aware slot specialization objective that encourages the slots to capture discriminative matching cues. Experiments on four text-video retrieval benchmarks show that MARS achieves state-of-the-art results in both direct similarity-based retrieval and reranking settings. Ablation studies and analyses demonstrate that multi-layer fusion, multiple slots, and hard-negative-aware slot specialization provide complementary gains. Code is available at https://github.com/sejong-rcv/MARS.","authors":["Uicheol Jung","Juyoung Hong","Geuntaek Lim","Yukyung Choi"],"published":"2026-09-02T13:16:06Z","updated":"2026-09-02T13:16:06Z","abstract_url":"https://arxiv.org/abs/2609.02565v1","html_url":"https://arxiv.org/html/2609.02565v1","pdf_url":"https://arxiv.org/pdf/2609.02565v1.pdf","matched_keywords":["video","retrieval","representation","multimodal"],"source_used":"html","source_text_chars":62583,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, representation, multimodal 相关；摘要显示其主要贡献为：Text-video retrieval requires representations that can distinguish videos with similar scenes, actions, and temporal patterns. Recent multimodal large language models have been adapted as embedding models, but they often represent each input using a single to...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02560v1","title":"Stereo 4D Radar for 3D Object Detection: Integrating Geometric Alignment and Absolute Velocity Estimation","abstract":"Four-dimensional (4D) Radar is a powerful sensing modality capable of detecting surrounding three-dimensional (3D) objects under diverse weather conditions and providing Doppler-based motion information. However, raw 4D Radar signals contain significant clutter from road surfaces, guardrails, and surrounding vehicles, along with multipath-induced ghost reflections and the receiver's inherent noise floor. Consequently, preprocessing algorithms designed to remove such invalid measurements often make the Radar data excessively sparse. Moreover, the Doppler measurements provided by 4D Radar describe only the radial component of an object's velocity, limiting their ability to recover the full motion state. In this paper, we introduce a stereo 4D Radar-based 3D object detection framework that exploits the geometric disparity between left and right Radars to estimate the absolute velocity of objects and achieve more robust perception through the fusion of their complementary features. The effectiveness of the proposed framework is validated on our in-house stereo 4D Radar dataset, demonstrating performance gains of 8.82 points in AP 3D and 9.0 points in AP BEV over state-of-the-art mono 4D Radar baselines. These results demonstrate that absolute velocity estimation combined with stereo geometry-aware feature fusion leads to substantial improvements in 3D object detection.","authors":["Seung-Hyun Song","Dong-Hee Paek","Woong-Chan Byun","Seung-Hyun Kong"],"published":"2026-09-02T13:13:08Z","updated":"2026-09-02T13:13:08Z","abstract_url":"https://arxiv.org/abs/2609.02560v1","html_url":"https://arxiv.org/html/2609.02560v1","pdf_url":"https://arxiv.org/pdf/2609.02560v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02556v1","title":"RGB-to-IR image translation for infrared vehicle detection in unseen UAV domains","abstract":"Synthetic training data is crucial for developing vision AI when real-world data is scarce, as in thermal infrared (IR) aerial vehicle detection. While abundant UAV RGB imagery motivates RGB-to-IR translation for data augmentation, unobservable thermal traits (e.g., engine heat) make learning transferable mappings challenging. This work investigates whether modern generative translators can overcome this cross-modal gap to improve infrared vehicle detection on unseen UAV target domains. Translators are trained on paired RGB-IR source datasets and applied to RGB training images from held-out target datasets to generate synthetic IR data. Evaluated methods include supervised GANs, ControlNet-based diffusion models, and foundation-model editing via LoRA. The resulting synthetic IR imagery is used to train RF-DETR vehicle detectors, which are evaluated on unseen IR target test splits across five aerial datasets, with Kust4K and VTUAV serving as target domains. Synthetic IR consistently outperforms RGB and grayscale baselines. Stable Diffusion 3.5 with ControlNet yields the best results, improving mAP from 50.8 to 60.1 on Kust4K and from 25.6 to 38.4 on VTUAV compared to models trained only on source-domain IR data. Increasing output diversity via multiple seeds (+1.1 mAP) and prompt variations (+3.3 mAP) provides additional gains on VTUAV. Although a performance gap to real target IR data remains, generative RGB-to-IR translation effectively mitigates IR data scarcity and improves cross-domain aerial vehicle detection.","authors":["Thijs A. Eker","Ella P. Fokkinga","Jan Erik van Woerden","Elfi I. S. Hofmeijer","Sebastiaan P. Snel","Klamer Schutte","Friso G. Heslinga"],"published":"2026-09-02T13:06:58Z","updated":"2026-09-02T13:06:58Z","abstract_url":"https://arxiv.org/abs/2609.02556v1","html_url":"https://arxiv.org/html/2609.02556v1","pdf_url":"https://arxiv.org/pdf/2609.02556v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02531v1","title":"Spatially Aware World Action Model via Geometric Latent Diffusion","abstract":"World Action Models (WAMs) leverage the capabilities of large-scale pretrained video diffusion models to jointly predict future observations and actions, inheriting rich visual and physical priors from internet-scale video. This has made them a promising paradigm for robot policy learning, yet the prevailing models operate exclusively on RGB observations and do not leverage 3D information. To bridge this gap, we introduce a Spatially Aware World Action Model (SA-WAM), which repurposes a pretrained video model for joint action, RGB, and depth prediction, enabling 3D-aware world modeling and action prediction within a single diffusion backbone. We use a nonlinear encoding that maps the unbounded depth signal into the bounded input domain expected by the frozen VAE tokenizer. This allows us to reuse the tokenizer without 3D-specific fine-tuning, incorporating geometric information without sacrificing the pretrained priors. SA-WAM achieves state-of-the-art results on the RoboCasa and LIBERO-Plus benchmarks, while simultaneously improving future-state predictions. Furthermore, SA-WAM outperforms strong baselines in real-world evaluation using a UR5 robotic arm, with strong gains in randomized environments. We analyze the correlation between world model prediction quality and rollout success, providing insights into WAM performance and avenues for its improvement.","authors":["Javier Alejandro Lopetegui Gonzalez","Paul Pacaud","Cordelia Schmid"],"published":"2026-09-02T12:42:37Z","updated":"2026-09-02T12:42:37Z","abstract_url":"https://arxiv.org/abs/2609.02531v1","html_url":"https://arxiv.org/html/2609.02531v1","pdf_url":"https://arxiv.org/pdf/2609.02531v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02529v1","title":"Fine-Grained Anomaly Perception in Wild UGC-Enhanced Images: A Comprehensive Dataset and Difference-Fusion Framework","abstract":"Image enhancement and restoration have become standard back-end operations on short-video and social media platforms to boost UGC visual experience. Yet these processes inevitably introduce visual anomalies--especially in faces, texts, and textures--that directly undermine perceptual fidelity and viewer trust. While existing IQA methods perform well on classic distortions, they target holistic quality assessment and fail to capture the specific, localized anomalies caused by enhancement algorithms in real-world UGC. To bridge this gap, we formally define a new task-quality Anomaly Perception for UGC image Enhancement (UEAP), and contribute the first UEAP benchmark dataset, named UEAP-4k, curated from the real business scenarios. It provides fine-grained annotations for anomaly categories, localization and severity levels. Furthermore, we propose a Difference-Fusion Anomaly Perception Method (DFAP-UGC) for wild UGC-enhanced images, which leverages explicit problem-reference difference fusion with dense spatial querying, regional verification, and quality-aware ranking, enabling robust anomaly identification in challenging scenarios. To handle the inherent coupling of subtasks in this new task, we propose a Locality-Aware Dynamic Task Prioritization (LADTP) training strategy that enables effective end-to-end learning and eliminates multi-stage overhead. Extensive experiments show that our method outperforms baselines adapted from classical approaches for this task, validating the value of this dataset and the superior of DFAP-UGC for robust UGC-enhanced image anomaly perception. Code and data will be public.","authors":["Yan Zhong","Gefei Chen","Qiufang Ma","Zhen Wang","Zhiwei Fan","Lei Shi","Tingting Jiang"],"published":"2026-09-02T12:37:56Z","updated":"2026-09-02T12:37:56Z","abstract_url":"https://arxiv.org/abs/2609.02529v1","html_url":"https://arxiv.org/html/2609.02529v1","pdf_url":"https://arxiv.org/pdf/2609.02529v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02528v1","title":"Doppio: A Dataset for Contactless Weight Estimation of Falling Particles","abstract":"Measuring the mass of powder, including falling particles, is a common task in industrial applications. While scales are effective for static measurements, many applications require contactless sensing, where existing solutions are often costly, application-specific, and technically complex. In this work, we investigate computer vision as a practical alternative for contactless mass estimation. As an accessible real-world case study, we focus on coffee grinding and introduce \\emph{Doppio}, a novel video dataset capturing videos of falling ground coffee, paired with precise, per-frame ground-truth weight measurements. To demonstrate contactless measuring, we evaluate deep learning-based approaches ranging from purely spatial feed-forward networks to recurrent spatio-temporal models. These models are analyzed with respect to their predictive accuracy and computational trade-offs. We demonstrate that deep learning-based computer vision models accurately estimate the cumulative weight of falling particles, establishing a solid foundation for future vision-based contactless measurement solutions.","authors":["Simon Kiefhaber","Jan-Martin O. Steitz","Julia Grabinski","Christoph Reich","Paul Wagner","Max Zimmermann","Simone Schaub-Meyer","Stefan Roth"],"published":"2026-09-02T12:35:33Z","updated":"2026-09-02T12:35:33Z","abstract_url":"https://arxiv.org/abs/2609.02528v1","html_url":"https://arxiv.org/html/2609.02528v1","pdf_url":"https://arxiv.org/pdf/2609.02528v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02512v1","title":"Beauty is in the AI of the beholder: MLLMs systematically overrate facial attractiveness","abstract":"Beauty assessments from Multimodal Large Language Models (MLLMs) are increasingly popular amongst users, companies, and aestheticians. This raises the question of whether these AI models can accurately reflect human judgments of attractiveness. In a pre- registered exploratory study, we compared the attractiveness ratings of 2,513 human participants to four widely used commercial AI models: Claude, Gemini, GPT, and Grok. Results showed that MLLMs systematically rate faces more favourably and within a narrower range than humans and, at the time of study, do not reproduce human ratings in absolute terms. However, MLLMs exhibit strong correlations with human attractiveness judgments, accurately tracking the rank-ordering of faces. MLLMs may judge faces by different cues than humans; only face age was a predictor of facial attractiveness in both humans and MLLMs, with inconsistent patterns across models for ethnicity and gender. AI models strongly agree with one another, except for Grok, which also showed the lowest agreement with humans. Our findings suggest that while they may be able to approximate rank-orderings of human attractiveness, current off-the-shelf commercial MLLMs systematically overrate the beauty of human faces.","authors":["Santiago Grandas","Juan Sebastian Cely-Acosta","Mohit Mendiratta","Shafee Hassan","Macken Murphy"],"published":"2026-09-02T12:16:22Z","updated":"2026-09-02T12:16:22Z","abstract_url":"https://arxiv.org/abs/2609.02512v1","html_url":"https://arxiv.org/html/2609.02512v1","pdf_url":"https://arxiv.org/pdf/2609.02512v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02486v1","title":"ViSAR: Training-Free Adaptive-$k$ Retrieval for Visual Document Question Answering","abstract":"Document Visual Question Answering (DocVQA) often leverages Retrieval-Augmented Generation (RAG), where late-interaction encoders are commonly used to identify document pages relevant to a user query, before answer generation by a Large Vision-Language Model (LVLM). Existing approaches typically retrieve a fixed top-$k$ number of pages regardless of query complexity, which increases LVLM latency and may degrade answer accuracy. We introduce ViSAR (Visual Semantic Activation Retrieval), a training-free adaptive-$k$ retrieval method for late-interaction visual document retrieval. ViSAR operates directly in the embedding space to construct a query-conditioned page-level similarity matrix that highlights query-relevant semantics and dynamically determines the number of pages to retrieve. Across multiple encoders and LVLMs, ViSAR retrieves compact, query-adapted page sets that reduce RAG latency by up to 58.7\\%, while maintaining or improving answer accuracy compared with fixed top-$k$ and adaptive retrieval heuristics. Furthermore, we show that the similarity matrix structure correlates with answer accuracy, suggesting future directions for retrieval quality-aware document understanding.","authors":["Adrien Mialland","Marc Plantevit","Julien Gallois","Céline Robardet"],"published":"2026-09-02T11:54:58Z","updated":"2026-09-02T11:54:58Z","abstract_url":"https://arxiv.org/abs/2609.02486v1","html_url":"https://arxiv.org/html/2609.02486v1","pdf_url":"https://arxiv.org/pdf/2609.02486v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02476v1","title":"UnCapsTSR: An Unsupervised Transformer-based Image Super-Resolution Approach for Capsule Endoscopy Images","abstract":"Wireless Capsule Endoscopy (WCE) captures and streams video while passing through a patient's Gastrointestinal (GI) tract and is used to examine its irregularities. Although advantageous over conventional endoscopy, WCE suffers from limitations related to capsule size and wireless transmission, resulting in images with coarser resolution. This work presents UnCapsTSR, an unsupervised transformer-based Generative Adversarial Network (GAN) framework for improving the spatial resolution of Low-Resolution (LR) WCE images. The proposed method accomplishes SR without explicit degradation estimation of real-world LR data and eliminates the need for true LR-HR pairs. UnCapsTSR employs a Bilateral Total Variation (BTV) loss to ensure spatial continuity in SR images. A newly curated dataset from the Kvasir Capsule dataset is also presented for training WCE SR models. Generalizability is validated on KID and GIANA datasets that are not used during training. A new non-reference metric, Endoscopy Quality Metric (EndoQM), is introduced for quantitative evaluation of domain-specific WCE data. Experiments demonstrate consistent improvement over state-of-the-art unsupervised SR approaches using NIQE, BRISQUE, PIQE, and EndoQM. Statistical evaluation shows 40 to 80 percent improvement in EndoQM from LR to SR across the evaluated datasets.","authors":["Anjali Sarvaiya","Shubh Kawa","Lalit Agrawal","Jagrit Joshi","Kishor Upla","Kiran Raja"],"published":"2026-09-02T11:48:17Z","updated":"2026-09-02T11:48:17Z","abstract_url":"https://arxiv.org/abs/2609.02476v1","html_url":"https://arxiv.org/html/2609.02476v1","pdf_url":"https://arxiv.org/pdf/2609.02476v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02471v1","title":"Learning to Track from Privileged Target Appearances","abstract":"Target templates define what a visual tracker searches for, yet the templates available at inference trade off localization certainty with appearance freshness: the initial ground-truth template is exact but becomes stale, whereas recent templates better reflect the current appearance but are cropped from uncertain predictions. We quantify this bottleneck with a non-deployable oracle that supplies an exact current-frame target crop, improving AUC on LaSOT by 15.2 percentage points. This gap reveals a training-only opportunity: frame-level ground truths provide exact current- and future-frame target crops, although such crops are unavailable at deployment. We introduce Privileged Appearance Transfer for Tracking (PATT), a teacher-student training framework that transfers these privileged appearances to a deployable tracker through multi-level representation prediction. The privileged teacher observes exact target crops from past, current, and future frames, whereas the student receives only past-frame templates and learns to predict the teacher's search representations. To avoid transferring unreliable teacher signals, PATT weights this transfer by the teacher's relative localization advantage over the student and its absolute localization accuracy. After training, the teacher, latent predictor, reliability weights, and privileged crops are removed, leaving standard student-only inference. Across seven benchmarks at two model scales, PATT achieves consistent gains under both long- and short-term tracking protocols.","authors":["Xin Chen","Jiao Xu","Dong Wang","Huchuan Lu","Kede Ma"],"published":"2026-09-02T11:43:43Z","updated":"2026-09-02T11:43:43Z","abstract_url":"https://arxiv.org/abs/2609.02471v1","html_url":"https://arxiv.org/html/2609.02471v1","pdf_url":"https://arxiv.org/pdf/2609.02471v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02462v1","title":"VIPS: Vehicle-Infrastructure Cooperative Planning Benchmark via Pseudo-Simulation","abstract":"End-to-end autonomous driving in urban environments requires robust decision-making under partial observability and complex multi-agent interactions. Severe occlusions and dense traffic at intersections limit the perception capability of single-agent systems, motivating recent efforts on Vehicle-to-Infrastructure (V2I) cooperation for perception and planning. However, existing evaluation protocols face a fundamental trade-off: open-loop evaluation fails to capture error accumulation and recovery from deviations, while closed-loop evaluation is costly, difficult to scale, and often relies on simulated environments that may suffer from domain gaps. To bridge this gap, we propose VIPS, a benchmark for cooperative autonomous driving in V2I settings based on pseudo-simulation. VIPS extends pseudo-simulation by integrating vehicle and infrastructure observations. This enables scalable yet realistic evaluation of robustness and error propagation without full simulation. We further present CoS-V2X, a cooperative planning framework based on sparse representations. CoS-V2X models vehicle-infrastructure interactions using compact features for efficient communication and robust decision-making under heterogeneous observations. Code and dataset are available at https://vips2026.github.io.","authors":["Hoonhee Cho","Jae-Young Kang","Giwon Lee","Hyemin Yang","Heejun Park","Kuk-Jin Yoon"],"published":"2026-09-02T11:32:52Z","updated":"2026-09-02T11:32:52Z","abstract_url":"https://arxiv.org/abs/2609.02462v1","html_url":"https://arxiv.org/html/2609.02462v1","pdf_url":"https://arxiv.org/pdf/2609.02462v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02390v1","title":"Seeing Beyond the Lesion: Disease Recognition from Reactive CNS Tissue","abstract":"Sampling error yields exclusively reactive, non-lesional brain parenchyma in a significant proportion of intracranial biopsies, leaving the underlying disease undiagnosed. We benchmark four pathology foundation models (UNI2-h, Virchow2, Prov-GigaPath, H-optimus-0) as frozen patch encoders within a shared attention-based multiple-instance learning framework using 245 whole-slide images from 186 patients with confirmed downstream diagnoses. We first show that coarse disease-category prediction can be reproduced largely from slide size alone. After restricting classification to three finer diagnostic distinctions within common tissue categories, this confound no longer explains performance, yet disease labels remain predictable above chance under permutation testing (p $\\le 10^{-4}$ throughout). Surprisingly, performance is statistically indistinguishable across all foundation-model encoders, suggesting that recovering these weak morphological signatures is not limited by current patch representations. Signed instance-contribution maps and expert review further test whether predictive evidence localizes to reactive parenchyma rather than sampling-induced bias like blood introduced during tissue sampling. These results position acquisition-shortcut auditing via a provenance-only baseline as a necessary control in computational-pathology benchmarks, and show, once that confound is removed, that weakly supervised models still recover disease signal from tissue conventionally regarded as non-diagnostic.","authors":["Jan Schnorrenberg","Jan Ernsting","Enrico Küllenberg","Tim Hahn","Benjamin Risse","Christian Thomas"],"published":"2026-09-02T10:02:43Z","updated":"2026-09-02T10:02:43Z","abstract_url":"https://arxiv.org/abs/2609.02390v1","html_url":"https://arxiv.org/html/2609.02390v1","pdf_url":"https://arxiv.org/pdf/2609.02390v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02377v1","title":"ProSR: Semantic-Prototype-Guided Discrete Modeling for Physically Consistent SAR Super-Resolution","abstract":"High-resolution Synthetic Aperture Radar (SAR) imagery is critical for precision analysis such as automatic target recognition, yet its acquisition is costly. Although generative image super-resolution (ISR) models offer a promising alternative, current smooth-approximation based diffusion frameworks often struggle to preserve the coherent scattering statistics, causing stochastic structural distortions that are less consistent with real SAR physics. To address this, we propose Semantic Prototype-Guided Super-Resolution (ProSR), reformulating SAR ISR as a semantically-guided discrete token prediction task within a quantized latent space. By mapping signal features to discrete scattering primitives, ProSR preserves the impulsive nature of SAR without over-smoothing. Furthermore, we integrate a Self-Supervised Learning backbone into SAR ISR to extract label-free semantic priors, overcoming label scarcity. Guided by these priors, we introduce Semantic-Aligned Detail Encoding to decouple high-frequency signals into discrete scattering primitives. In parallel, the Semantic Prototype Map Generator explicitly constructs semantic prototype maps, allowing Prototype-Map-Guided Attention to route the information flows within identical categories and mitigate inter-class interference. To validate our approach, we present a large-scale 0.25m resolution benchmark from the Umbra Open Dataset. Experimental results show ProSR achieves superior visual quality while preserving essential scattering characteristics required for practical SAR applications.","authors":["Byoungwoo Kim","Munchurl Kim"],"published":"2026-09-02T09:50:06Z","updated":"2026-09-02T09:50:06Z","abstract_url":"https://arxiv.org/abs/2609.02377v1","html_url":"https://arxiv.org/html/2609.02377v1","pdf_url":"https://arxiv.org/pdf/2609.02377v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02369v1","title":"Information Density Imbalance in Visual Object Detection","abstract":"In object detection, the number of instances is typically used to determine whether a dataset exhibits a long-tailed distribution, implicitly assuming that the model will perform poorly on categories with fewer instances. This assumption has led to extensive research on category bias in datasets with imbalanced instance numbers. However, even in datasets where instance numbers are relatively balanced, models still exhibit category bias, indicating that instance count alone cannot explain this phenomenon. In this work, we first introduce the concept and measurement of information density. We then observe a significant negative correlation between a category's information density and its accuracy, and we investigate how the training process impacts this relationship. Empirical studies suggest that information density imbalance may be a potential source of category bias. To preliminarily validate the potential of information density, we made simple improvements to three advanced object detection loss functions using this concept. Experiments on the Pascal VOC, COCO-LT, and LVIS datasets demonstrate that information density can significantly reduce model bias while effectively enhancing the overall performance of existing loss functions. This study provides a new perspective for understanding the generalized bias phenomenon in object detection models and offers new tools for designing fairer loss functions and training strategies.","authors":["Ziwei Zhao","Yanxi Lu","Yuwei Hu","Shiyang Su","Mingxuan Wang","Chenyue Zhou","Jiayi Chen","Hehan Li","Xiaoshuai Hao","Andi Zhang","Yanbiao Ma"],"published":"2026-09-02T09:40:49Z","updated":"2026-09-02T09:40:49Z","abstract_url":"https://arxiv.org/abs/2609.02369v1","html_url":"https://arxiv.org/html/2609.02369v1","pdf_url":"https://arxiv.org/pdf/2609.02369v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02367v1","title":"The Missing Temporal Link: Temporal Context Routing for Script-Driven Audio-Video Generation","abstract":"Joint audio-video generation models have made substantial progress in visual quality and audio-visual synchronization. However, they still provide limited control over when shot transitions occur and dialogue is spoken. This limitation constrains their application in script-driven content creation, where timing errors can undermine narrative coherence and the viewing experience. Current joint generators align video and audio representations on a shared temporal axis, yet the precise timing of shots and dialogue specified in a structured prompt is encoded only in the prompt's text representation and remains unaligned with the temporal coordinates of either modality. Consequently, video and audio may remain synchronized with each other while both fail to follow the script timeline. This mismatch motivates us to extend temporal alignment beyond video and audio to include the structured script. We therefore introduce Temporal Context Routing (TCR), which maps the script timing onto the shared temporal axis of video and audio generation and routes each prompt's guidance to the corresponding positions in both modalities. Compared with the baseline on 200 test scripts, TCR reduces Shot Boundary MAE by 96%, from 1.11 s to 0.042 s, and raises Dialogue Acc@0.5 s from 28.3% to 84.1%. TCR achieves these improvements while maintaining visual quality and audio-visual synchronization comparable to those of the baselines. A user study further shows that participants prefer TCR on all five evaluated dimensions.","authors":["Yichen Liu","Quanwei Zhang","Haozhe Wang","Donghao Zhou","Xiaojie Li","Yang Shi","Jiaming Liu","Ruihua Huang","Yingtian Zou","Daquan Zhou"],"published":"2026-09-02T09:39:50Z","updated":"2026-09-02T09:39:50Z","abstract_url":"https://arxiv.org/abs/2609.02367v1","html_url":"https://arxiv.org/html/2609.02367v1","pdf_url":"https://arxiv.org/pdf/2609.02367v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02359v1","title":"TempoGround: State-Aware Streaming Visual Grounding with Vision-Language Models","abstract":"Visual grounding maps language referents to spatial targets and is central to open-vocabulary perception with vision-language models. Existing methods have made substantial progress on single-frame and video-based visual grounding, yet under streaming inputs they still suffer from identity drift, cross-frame inconsistency, and fragile localization under partial occlusion. To address these issues, we present TempoGround, a VLM-native framework that detects cross-frame object correspondence and explicitly models object presence states, thereby enabling accurate and consistent visual grounding under streaming inputs. The key is a curriculum prediction mechanism guided by state-aware cross-frame correspondence: TempoGround resolves 2D instance association, predicts whether each object newly enters, continues in, or leaves the view, decodes the 2D box, and then lifts it to a camera-frame 3D box. As token-level supervision alone cannot capture the geometric objectives of streaming grounding, we further introduce Streaming Grounding Reinforcement (SGR), which optimizes TempoGround with verifiable Grounding, Identity, and Consistency rewards, jointly reinforcing persistent localization and temporally consistent predictions. We carefully design a three-stage training strategy and train TempoGround on large-scale data. We evaluate visual grounding under causally streaming inputs on multiple challenging benchmarks: TempoGround improves F1_2D@0.5 and F1_2D@0.95 by 4.4 and 0.5 on average, and F1_3D@0.25 and AP_3D by 6.2 and 7.5, respectively. These results demonstrate that TempoGround provides a practical foundation for visual grounding under streaming inputs.","authors":["Leqian Ding","Junning Qiu","Manwen Yang","Yu Guo","Fei Wang"],"published":"2026-09-02T09:30:08Z","updated":"2026-09-02T09:30:08Z","abstract_url":"https://arxiv.org/abs/2609.02359v1","html_url":"https://arxiv.org/html/2609.02359v1","pdf_url":"https://arxiv.org/pdf/2609.02359v1.pdf","matched_keywords":["video","3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02350v1","title":"LookStep: Efficient Vision-Language Navigation with Linguistic Foresight and Event Driven Memory","abstract":"Vision-Language Navigation (VLN) requires an embodied agent to follow natural-language instructions in unseen environments. Recent progress has been largely driven by Multimodal Large Language Models (MLLMs). Existing methods follow a next-step action prediction paradigm, supervising only the expert action, which requires a high quantity of data for training. They also rely on cognitive maps, accumulated historical frames, or external 3D tools to maintain states, leading to high computational and memory overhead. To realize resource efficiency VLN, we propose LookStep, a unified end-to-end framework that combines Language Centric Future State Modeling and Event Driven Rolling Memory that uses language labels to generate coarse-grained navigation progress and future states for each candidate action, while autonomously deciding whether to write each observation into a bounded rolling memory with a semantic role. We validate LookStep empirically. On VLN-CE tasks, LookStep outperforms existing methods under the same training settings, achieving a 49.7\\% success rate on R2R-CE Val-Unseen with better memory efficiency and less data usage. Code and model is available at https://github.com/kunyang-YU/LookStep.","authors":["Kun-Yang Yu","Yingzhe Li","Hongyu Xu","Shi-Yu Tian","Zhi Zhou","Yang Chen","Ming Yang","Sheng Wang","Qing Yu","Lan-Zhe Guo","Yu-Feng Li"],"published":"2026-09-02T09:24:08Z","updated":"2026-09-02T09:24:08Z","abstract_url":"https://arxiv.org/abs/2609.02350v1","html_url":"https://arxiv.org/html/2609.02350v1","pdf_url":"https://arxiv.org/pdf/2609.02350v1.pdf","matched_keywords":["3d","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02349v1","title":"GlyphAnchor: Enhancing Visual Text Rendering via Position-Anchored Glyph Priors","abstract":"Rendering accurate text remains difficult for image generation and editing models, especially when the target contains long, complex, and densely arranged text or rare characters. Existing approaches either improve native text rendering through stronger backbones and data-centric training without explicit glyph priors, or incorporate glyph priors through specialized designs that remain insufficiently accurate and robust under challenging scenarios. We introduce GlyphAnchor, a novel text-rendering enhancement method for both text-to-image and image-editing diffusion transformer models. GlyphAnchor enhances the backbone with lightweight glyph patch conditions whose positions are anchored to the target image through the model's native positional encoding. We train this capability with staged supervised finetuning and further refine it with text-aware post-training to improve robustness. We also introduce InfoTextBench, a benchmark for evaluating text-rich visual text rendering in both generation and editing settings. Experiments across multiple backbones and benchmarks, including long, complex, and densely arranged text and rare character scenarios, show that GlyphAnchor consistently improves text fidelity while preserving overall image quality.","authors":["Qiang Xiang","Shuang Sun","Binglei Li","Yibo Chen","Xu Tang","Yao Hu","Junping Zhang"],"published":"2026-09-02T09:23:23Z","updated":"2026-09-02T09:23:23Z","abstract_url":"https://arxiv.org/abs/2609.02349v1","html_url":"https://arxiv.org/html/2609.02349v1","pdf_url":"https://arxiv.org/pdf/2609.02349v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02348v1","title":"Structured-Prior-Guided Diffusion Inpainting with Physical Consistency for Traffic Sign Augmentation","abstract":"Traffic sign detection faces a long-tailed data distribution. Many rare signs matter as much as common ones from a regulatory standpoint, yet they have very few samples. Generative data augmentation is one way out. General-purpose inpainting models, however, distort digits, deform geometry and perspective, and shift colours when applied directly to sign regions. We trace this to a single gap: the conditioning signal is too abstract for the physical composition of a sign. We propose a structured-prior-guided diffusion inpainting framework with physical consistency. It injects the semantic, appearance and geometric priors of a sign through three orthogonal pathways: a JSON-formatted text prompt, a front-view vector template rendered with measured dominant colours (via IP-Adapter), and an affine-aligned vector template (via ControlNet). Two physical consistency losses constrain colour with a CIELAB chromaticity $L_1$ term and edge structure with a Sobel gradient term. We train by self-supervised reconstruction on a large set of images collected in-house at AMAP, then evaluate zero-shot on the public TT100K-2021 dataset, a different source. Our method uses a Stable Diffusion 1.5 backbone of about 1.4B parameters. It beats seven representative competitors on every metric of reconstruction fidelity, physical consistency and semantic controllability. Its OCR exact-match rate reaches 91.1\\%, against 44.2\\% for the 12B industrial model FLUX.1 Fill [dev], and it needs only $1/14$ of that model's inference time. Leave-one-out ablations confirm that each of the three prior pathways and both loss terms contribute on their own. In downstream detection, the synthetic data raises the group-pooled AP50 of rare classes by $1.23\\times$ to $7.40\\times$ over a real-data-only baseline. Code and pre-trained models are available at https://github.com/52hz-whale/TrafficSignInpaint.","authors":["Luo Li","Chongchong Huang","Jun Jia","Qiang Gao","Xinlong Liu","Gui Yang","Liang Cao"],"published":"2026-09-02T09:22:23Z","updated":"2026-09-02T09:22:23Z","abstract_url":"https://arxiv.org/abs/2609.02348v1","html_url":"https://arxiv.org/html/2609.02348v1","pdf_url":"https://arxiv.org/pdf/2609.02348v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02341v1","title":"Towards Zero-Shot Transfer Across Embodiments For Driving VLAs","abstract":"Vision-Language-Action models (VLAs) have shown strong potential in autonomous driving by leveraging multimodal pretraining for instruction following, visual reasoning, and scene-level generalization. In robotic manipulation, scaling VLA fine-tuning across multiple robot setups--especially when unifying representations across embodiments--has been shown to improve in-dataset performance and cross-embodiment generalization; in autonomous driving, however, VLAs remain largely trained on individual datasets and are rarely evaluated for zero-shot transfer to unseen datasets and camera rigs; furthermore naively adding more datasets to the training data does not necessarily lead to better performance within seen embodiments. To address these problems, we study multi-dataset training for the driving task and BEV-Forcing, an auxiliary objective that transfers ground-plane object-layout information from a specialized Bird's-Eye-View model into the VLA backbone. By encouraging the model to represent object position through a shared BEV spatial interface, we show that an auxiliary task such as BEV-Forcing can improve both in-distribution and out-of-distribution performance when training on a small number of camera rigs. As the number of training embodiments increases, however, the benefits of the auxiliary task are reduced; we present this as evidence that new techniques in the literature may see their benefits diminish when simply scaling up training diversity, which motivates presenting results taking into account data scaling.","authors":["Caio Azevedo","Stefano Sabatini","Sascha Hornauer","Fabien Moutarde"],"published":"2026-09-02T09:17:54Z","updated":"2026-09-02T09:17:54Z","abstract_url":"https://arxiv.org/abs/2609.02341v1","html_url":"https://arxiv.org/html/2609.02341v1","pdf_url":"https://arxiv.org/pdf/2609.02341v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02333v1","title":"ORB-SVM : An Innovative Hybrid Framework for Efficient Brain Tumor Detection from MRI Scans","abstract":"Brain cancer remains one of the most significant challenges in modern medicine, where the accuracy of early stage diagnosis is a decisive factor in patient survival and treatment efficacy. Although Magnetic Resonance Imaging (MRI) is the established gold standard for visualizing neurological structures, the interpretation of these high dimensional scans is often complicated by subjective variability among practitioners and the inherent noise present in complex medical images. While contemporary approaches frequently rely on high parameter deep learning architectures, such models often involve significant computational costs and require extensive data for effective training. This study introduces a hybrid framework that utilizes the Oriented FAST and Rotated BRIEF (ORB) algorithm for precise feature extraction and a Support Vector Machine (SVM) for classification [1], [2]. The proposed approach achieves a sub- stantial data reduction of approximately 99.5%, which effectively minimizes the influence of non informative background data while preserving critical diagnostic patterns essential for tumor identification. By balancing feature sparsity with a robust kernel based classifier, this methodology addresses the limitations of over parameterized systems while maintaining high diagnostic integrity. Experimental evaluations conducted on the Br35H dataset demonstrate that the framework attains a classification accuracy of 97.5%. The findings suggest that the integration of localized feature representation and optimized classification provides a reliable and resource efficient alternative for medical image analysis, offering a structured solution that maintains per- formance without the need for extensive computational overhead.","authors":["Amirhosein Azarpour"],"published":"2026-09-02T09:09:14Z","updated":"2026-09-02T09:09:14Z","abstract_url":"https://arxiv.org/abs/2609.02333v1","html_url":"https://arxiv.org/html/2609.02333v1","pdf_url":"https://arxiv.org/pdf/2609.02333v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02318v1","title":"YesTrack: Referring Multi-Object Tracking via MLLM-based Yes/No Verification","abstract":"Referring multi-object tracking (RMOT) aims to track every instance in a video that matches a given language expression. Despite the recent integration of multimodal large language models (MLLMs) to enhance generalization, existing methods predominantly relegate them to the role of caption generators, necessitating external modules for final decision-making. This paradigm not only introduces extra latency but also severely underutilizes the inherent vision-language alignment capabilities of MLLMs. To address these limitations, we propose YesTrack, a novel two-stage RMOT method that reformulates referring as a discriminative task, directly leveraging MLLMs for Yes/No verification without explicit text generation. To further enhance the reliability and efficiency of this MLLM-based verification, we introduce two lightweight temporal consistency constraints: Temporal Confidence Prior (TCP) and Temporal Reference Propagation (TRP). We further validate the generality of this discriminative paradigm by proposing YesTrack-MOT, a straightforward yet highly effective instantiation for generic multi-object tracking (MOT). Experiments on Refer-KITTI and Refer-KITTI-V2 show that YesTrack significantly outperforms existing state-of-the-art methods while maintaining high efficiency, even when implemented with the smallest variant of Qwen3-VL. Code is released at https://github.com/ggbondrighthere24/YesTrack.","authors":["Quansheng Hu","Qin Sun","Qiansen Dai","Jin Ding","Wan Zhang","Xue Zhou","Jianxiao Zou"],"published":"2026-09-02T09:04:43Z","updated":"2026-09-02T09:04:43Z","abstract_url":"https://arxiv.org/abs/2609.02318v1","html_url":"https://arxiv.org/html/2609.02318v1","pdf_url":"https://arxiv.org/pdf/2609.02318v1.pdf","matched_keywords":["video","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02299v1","title":"Domain shift-robust object detection with GenAI image editing","abstract":"Object detectors often degrade under domain shifts such as changes in lighting, weather, or occlusion. These shifts alter object appearance and expose a reliance on visual shortcuts learned from the training distribution that do not generalize across domains. Acquiring sufficient real-world samples to capture such domain variation is particularly difficult in specialized, low-data settings. Recent advances in diffusion-based generative image editing have shown promise for improving the in-domain performance of object detectors through synthetic data augmentation. However, their potential to improve out-of-domain robustness remains largely unexplored. We hypothesize that generative image editing can simulate a controlled domain shift in training data, effectively bridging the gap between source and target domains. To test this, we studied camouflaged military vehicle detection as a challenging domain shift scenario. Detectors trained on uncamouflaged data demonstrate substantial degradation on real test imagery containing foliage, netting, and multi-spectral camouflage across 15 vehicle classes in close-up, ground-level imagery. We used two diffusion-based editing models, Qwen Image Edit 2509 and Flux.2 Dev, to synthetically add camouflage to the training data, alongside a LoRA fine-tuned version of Qwen. A non-generative black-bar occlusion baseline served as a lower bound on augmentation quality. Using a GroundingDINO detector trained on real and synthetic data, generative camouflage augmentation yielded substantial mAP improvements for foliage (+20.1) and netting (+14.4) camouflage. Generating multi-spectral camouflage proved more challenging, but LoRA fine-tuning improved performance by 4.4 mAP over the uncamouflaged baseline.","authors":["Isabel D. Stein","Thijs A. Eker","Sebastiaan P. Snel","Ella P. Fokkinga","Klamer Schutte","Luca Ambrogioni","Friso G. Heslinga"],"published":"2026-09-02T08:44:27Z","updated":"2026-09-02T08:44:27Z","abstract_url":"https://arxiv.org/abs/2609.02299v1","html_url":"https://arxiv.org/html/2609.02299v1","pdf_url":"https://arxiv.org/pdf/2609.02299v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02291v1","title":"VoRTeC: Taming Foundation Flow for One-step Real time Video Compression","abstract":"Ultra-low bitrate video compression still faces critical challenges: traditional neural video compression inevitably introduces blurring artifacts, while diffusion-based generative video compression suffers from excessive decoding latency and poor temporal consistency. To address these issues, we propose $\\mathtt{VoRTeC}$, a Video Compression framework built upon a foundational flow model (Wan2.1). By compactly encoding latent video representations, predicting the positions of compressed representations along flow trajectories, and integrating multi-scale priors, $\\mathtt{VoRTeC}$ enables the compressor to harness generative video flow priors effectively. Without accessing the parameters or gradients of flow matching networks, our framework achieves one-step decoding and reconstructions with high perceptual fidelity. Meanwhile, we maintain consistency across frame groups via tail-frame reuse and prior caching. Extensive experiments demonstrate that our method reduces bit consumption by 58\\% compared to prior diffusion-based approaches, with decoding speed boosted by 3 to 197 times: $\\mathtt{VoRTeC}$ achieves a decoding speed of 13 FPS at 720p and 32 FPS at 480p.","authors":["Yichong Xia","Qinhong Wu","Qinhong Wu","Jinpeng Wang","Zeyuan Chen","Haoqian Wang"],"published":"2026-09-02T08:39:23Z","updated":"2026-09-02T08:39:23Z","abstract_url":"https://arxiv.org/abs/2609.02291v1","html_url":"https://arxiv.org/html/2609.02291v1","pdf_url":"https://arxiv.org/pdf/2609.02291v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02289v1","title":"If It Moves, Radar Knows: A Physics-Aware Radar Transformer for Class-Agnostic Moving-Object Detection","abstract":"Detectors trained on closed-set annotations can miss rare moving objects outside the training taxonomy. Automotive radar provides category-independent Doppler motion cues and is less affected by adverse illumination and weather, but sparse, noisy returns hinder class-aware 3D box detection. Surface location and velocity remain useful for motion reasoning and collision avoidance when full box geometry is difficult to recover. We present the Physics-Aware Radar Transformer (PART), a fully sparse radar-only detector that predicts existence confidence, a representative surface point, and 2D ground-plane velocity for each moving-object hypothesis. Doppler-Aware Query Initialization (DAQI) replaces scene-independent learned queries with input-dependent proposals by clustering radar returns in position and velocity, easing query-object assignment in sparse scenes. Physics-Guided Cross-Attention (PGCA) incorporates radial-Doppler consistency and radar cross section (RCS) into query-point association. Uncertainty-aware supervision randomly masks ground-truth objects and assigns soft existence targets to ambiguous radar-supported queries, reducing reliance on exhaustive annotations. With only 1.1 million parameters, PART achieves a class-agnostic average precision (CA-AP) of 0.8827, a mean average surface translation error (mASTE) of 0.3188 m, and a mean average velocity error (mAVE) of 0.8084 m/s on nuScenes. It attains 0.9203 recall on rare and safety-relevant categories excluded from the standard evaluation and remains effective at night, in rain, and under severe occlusion. Inspection of apparent false positives shows that some predictions correspond to moving objects absent from the nuScenes annotations. Code and pretrained model weights will be publicly available at https://github.com/sunyinghao-uestc/PART.","authors":["Yinghao Sun","Shuguang Li","Jinliang Shao","Tieshan Li"],"published":"2026-09-02T08:39:02Z","updated":"2026-09-02T08:39:02Z","abstract_url":"https://arxiv.org/abs/2609.02289v1","html_url":"https://arxiv.org/html/2609.02289v1","pdf_url":"https://arxiv.org/pdf/2609.02289v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02288v1","title":"Diffusion-Encoding Gaussian Field for Joint k-q dMRI Reconstruction","abstract":"Diffusion MRI requires repeated k-space acquisitions over multiple diffusion-encoding directions, making acquisition time dependent on both spatial and angular sampling. Existing joint k-q methods either associate directional parameters with fixed voxels or separate spatial reconstruction from angular completion. However, diffusion-weighted images acquired under different directions share the same anatomical organization, while their local signal intensities vary with diffusion encoding. Existing formulations do not fully exploit the complementarity between shared anatomy and direction-dependent signal variation. Consequently, residual spatial errors may be misinterpreted as genuine angular variation and propagated to unobserved directions. We propose a subject-specific spatial-angular Gaussian field for self-supervised joint k-q dMRI reconstruction. Shared 3D Gaussian primitives provide local spatial support, with each primitive carrying a continuous q-conditioned tensor-residual response. The signal at each location is synthesized from multiple overlapping primitive responses, coupling neighboring spatial regions and diffusion directions. The field is progressively optimized from undersampled k-space measurements of observed directions, without fully sampled targets or held-out-direction supervision. Experiments on three HCP diffusion shells under multiple acceleration settings demonstrated consistent improvements in missing-direction DWI reconstruction, tensor-derived metrics, and principal diffusion orientation estimation.","authors":["Zhibo Chen","Yajuan Huang","Yu Guan","Qiuyun Fan","Dong Liang","Qiegen Liu"],"published":"2026-09-02T08:39:00Z","updated":"2026-09-02T08:39:00Z","abstract_url":"https://arxiv.org/abs/2609.02288v1","html_url":"https://arxiv.org/html/2609.02288v1","pdf_url":"https://arxiv.org/pdf/2609.02288v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02266v1","title":"MAOL: Morphology-Aware Ordinal Learning for Fine-Grained Industrial Defect Severity Grading","abstract":"Fine-grained defect severity grading is essential for industrial inspection, yet remains challenging due to the ordinal nature of severity labels, the strong dependence on morphology-related cues, and the train-test discrepancy between clean annotated instances and noisy predicted instances in two-stage pipelines. We propose MAOL, a Morphology-Aware Ordinal Learning framework for fine-grained industrial defect severity grading. MAOL formulates severity grading as an instance-level ordinal learning task, incorporates explicit morphological features to enhance representation learning, introduces class-conditional adaptive ordinal thresholds to model defect-specific grading boundaries, and employs prediction-aware training via localization perturbation to improve robustness to imperfect predicted instances. Extensive experiments under both clean-ROI and predicted-instance settings demonstrate that MAOL consistently outperforms rule-based methods, nominal classification models, and existing ordinal baselines, especially in the predicted-instance setting. The proposed approach ranked third in the IDA 2026 Challenge on Fine-Grained Severity Grading for High-Precision Manufacturing.","authors":["Zhaoyang Wang","Haiyong Chen","Binyi Su","Kun Liu","Kun Wang","Xianen Zhou","Atik Shahariar"],"published":"2026-09-02T08:11:16Z","updated":"2026-09-02T08:11:16Z","abstract_url":"https://arxiv.org/abs/2609.02266v1","html_url":"https://arxiv.org/html/2609.02266v1","pdf_url":"https://arxiv.org/pdf/2609.02266v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02251v1","title":"Handwriting Trajectory Recovery via Autoregressive Ordered Stroke Instance Prediction","abstract":"Handwriting trajectory recovery aims to infer the dynamic writing process hidden behind a static handwritten image. Since offline handwriting preserves only the final spatial ink pattern, temporal information such as stroke order, writing direction, and pen-tip motion is lost, making recovery inherently ambiguous. Existing learning-based methods often directly predict the complete character trajectory without explicitly exploiting the stroke-level organization of handwriting. We argue that recovering the writing process should follow the writing process itself. Accordingly, we propose a two-stage framework that first recovers ordered stroke instances and then reconstructs continuous within-stroke motion. The first stage integrates stroke extraction and stroke-order recovery through autoregressive ordered stroke prediction, while direction-related structural cues further support within-stroke trajectory generation. Experiments on Chinese handwriting show that the proposed ordered prediction is more effective than post-hoc stroke ordering. Even without trajectory simplification, our full-point model achieves numerically better results than those reported by all compared baselines, while a controlled analysis shows that trajectory sampling density substantially affects measured recovery performance. Additional experiments demonstrate generalization to unseen Chinese character categories and cross-language extensibility to English and Tamil handwriting.","authors":["En-Guang Wang","Yan-Ming Zhang","Fei Yin","Cheng-Lin Liu"],"published":"2026-09-02T07:57:28Z","updated":"2026-09-02T07:57:28Z","abstract_url":"https://arxiv.org/abs/2609.02251v1","html_url":"https://arxiv.org/html/2609.02251v1","pdf_url":"https://arxiv.org/pdf/2609.02251v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02247v1","title":"SAUF-Net: Structure--Appearance Representation Learning with Uncertainty Feedback for Semi-Supervised Medical Image Segmentation","abstract":"Semi-supervised learning has shown great potential for reducing annotation costs in medical image segmentation. However, most existing methods mainly exploit unlabeled data through prediction-level consistency, while the reliability of internal feature representations is often overlooked. In medical images, target-related structural cues are easily entangled with unstable appearance variations, which may lead to unreliable pseudo labels and error accumulation during training. To address these issues, we propose SAUF-Net, a Structure--Appearance Representation Learning with Uncertainty Feedback Network for semi-supervised medical image segmentation. SAUF-Net uses the Structure--Appearance Decomposition Module (SADM) to separate bottleneck features into structural and appearance representations. The Disentangled Guidance Module (DGM) injects these representations into the decoding process to enhance structure-aware segmentation. Meanwhile, the Auxiliary Decoder produces branch-specific predictions for reliability estimation and a fused prediction for appearance-swapped consistency. Furthermore, we introduce an Appearance-Swapped Consistency branch to encourage structural representations to remain stable under appearance variations. We also introduce a reliability-map-guided dual-head discriminator with a Validity Head and an Uncertainty Head to provide feature-level uncertainty feedback. Extensive experiments on ISIC-2016 and Kvasir-SEG demonstrate that SAUF-Net outperforms state-of-the-art semi-supervised methods, especially under low-label settings.","authors":["Qin Lu","Zheyang Jing","Yujie Yang","Jianwang Li","Chen Yi","Shaofeng Jiang"],"published":"2026-09-02T07:54:49Z","updated":"2026-09-02T07:54:49Z","abstract_url":"https://arxiv.org/abs/2609.02247v1","html_url":"https://arxiv.org/html/2609.02247v1","pdf_url":"https://arxiv.org/pdf/2609.02247v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02233v1","title":"InfraPatch: Cross-Task Targeted Grayscale Patch Attacks on Infrared-Adapted Vision-Language Models","abstract":"Infrared vision-language models (IR-VLMs) have emerged as a promising paradigm for multimodal perception under low-visibility conditions, yet their robustness to targeted adversarial attacks remains poorly understood. Existing adversarial patch methods mainly study RGB-based models or a single downstream task and do not characterize whether localized perturbations can induce an intended semantic target in IR-VLMs. We propose InfraPatch, a white-box, per-instance framework for targeted digital grayscale patch attacks against IR-VLMs. InfraPatch optimizes a compact single-channel patch within an approximately 5% local-area budget, combines proxy-guided placement with task-adaptive semantic objectives, and induces target behaviors in image classification, image captioning, and binary visual question answering. We evaluate ten infrared-adapted model variants on 300 synthetic infrared-style images generated by applying DiffV2IR to a fixed 30-category COCO subset, using clean-conditioned targeted success criteria. InfraPatch achieves targeted attack success rates from 86.00% to 100% across the ten variants. On CLIP and BLIP-2, proxy location search improves success by 6.67 and 10.33 percentage points over optimized random placement, respectively; LLaVA-1.5 remains saturated near 100% under both settings. Patch-area and objective ablations further expose substantial differences in vulnerability across architectures and task formats. These results show that small grayscale patches can inject chosen target semantics across IR-VLM families under a controlled digital threat model, motivating stronger robustness evaluation for infrared multimodal systems.","authors":["Chengyin Hu","Dingyi Lu","Jiaju Han","Xiang Chen","Weiwen Shi","Jiahuan Long","Yiwei Wei","Jiujiang Guo"],"published":"2026-09-02T07:42:27Z","updated":"2026-09-02T07:42:27Z","abstract_url":"https://arxiv.org/abs/2609.02233v1","html_url":"https://arxiv.org/html/2609.02233v1","pdf_url":"https://arxiv.org/pdf/2609.02233v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02219v1","title":"Hardware-Accelerated Instance Segmentation for Resource-Constrained Space Robotics with Criticality Analysis","abstract":"Autonomous lunar missions require real-time per- ception under three coupled constraints: extreme low-light conditions, limited onboard compute, and radiation-induced hardware faults that can silently corrupt inference. We present a deployment-oriented instance segmentation framework for resource-constrained lunar robotics that jointly addresses quan- tization calibration and system-level fault exposure under strict compute constraints. First, we introduce Activation Variance Informative Sampling (AVIS), a label-free calibration strategy that deterministically selects calibration samples based on activation variance statistics. Second, we deploy a YOLO-based segmentation model on a Deep Learning Processor Unit (DPU) with architectural modifications that reduce CPU fallback paths and enable statically compiled execution with bounded latency in low-lighting conditions. We further introduce a software-level criticality analysis to estimate fault exposure and guide mitigation under radiation-constrained operation. On a lunar micro-rover platform, AVIS with bias correction recovers 69.8% of quantization-induced accuracy loss while achieving 309 ms inference latency and 5.7 W power consumption. Targeted mitigation reduces global criticality by 31.7%. The results demonstrate an integrated approach and a blueprint for a reliable and safe AI perception framework under space deployment constraints.","authors":["Siddhant Shete","Hilmi Dogu Kücüker","Udo Frese","Frank Kirchner"],"published":"2026-09-02T07:33:27Z","updated":"2026-09-02T07:33:27Z","abstract_url":"https://arxiv.org/abs/2609.02219v1","html_url":"https://arxiv.org/html/2609.02219v1","pdf_url":"https://arxiv.org/pdf/2609.02219v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02204v1","title":"TAME: Temporal-Aware Mixture-of-Experts for Text-Video Retrieval","abstract":"Text-Video Retrieval (TVR) retrieves videos that match a natural-language query, but extending image-text models such as CLIP to videos is fundamentally limited by the lack of temporal modeling. Videos exhibit frame-wise heterogeneity in appearance and motion, and compressing all frames into a single representation often obscures temporal structure and semantic transitions. To address this, we propose Temporal-Aware Mixture-of-Experts for Text-Video Retrieval (TAME), a CLIP-based framework that jointly models frame-level structure and temporal relations. First, we integrate sparse Mixture-of-Experts (MoE) layers into both CLIP encoders and apply frame-consistent routing on the vision branch so that experts specialize according to frame-level visual patterns while preserving the original vision-language alignment. Second, we introduce Frame-Temporal (FT) tokens that aggregate global cross-frame information and feed it back to each frame, enabling the visual encoder to capture long-range temporal dependencies without harming local details. Third, we design a Cross-Temporal Interaction and Aggregation (CTIA) module that refines frame-wise sentence-video similarities through staged temporal filtering and fusion. Experiments on standard TVR benchmarks show that TAME consistently improves over CLIP-based baselines. On MSR-VTT, it improves R@1 by 4.0 over CLIP4Clip, and also achieves consistent gains on DiDeMo, MSVD, LSMDC, and ActivityNet. The code is available at https://github.com/sejong-rcv/TAME.","authors":["Uicheol Jung","Juyoung Hong","Hojung Kwon","Yukyung Choi"],"published":"2026-09-02T07:12:50Z","updated":"2026-09-02T07:12:50Z","abstract_url":"https://arxiv.org/abs/2609.02204v1","html_url":"https://arxiv.org/html/2609.02204v1","pdf_url":"https://arxiv.org/pdf/2609.02204v1.pdf","matched_keywords":["video","retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02184v1","title":"CC-4DGS: Computational Deformation and Point-Cloud Compression for Storage-Efficient Dynamic Gaussian Splatting","abstract":"Dynamic four-dimensional (4D) Gaussian Splatting has emerged as a powerful explicit representation for high-quality view synthesis, yet existing methods still require tens to hundreds of megabytes per scene due to their heavy reliance on large multi-resolution hash tables and high-dimensional Gaussian attributes. This paper presents CC-4DGS, a storage-efficient and scalable framework that rethinks both deformation modeling and canonical attribute storage. First, we introduce a computational deformation field (CDF) that replaces large multi-resolution learnable hash tables with deterministic dense hash encoding and compact neural decoders, enabling on-the-fly synthesis of deformation features while reducing deformation storage to only 1--3 MB per scene. Second, we propose a compression of canonical point-cloud attributes (CCA) pipeline that compresses high-dimensional spherical harmonic appearance terms and auxiliary Gaussian attributes via conditional autoencoding, selective quantization, and residual codebooks, achieving 3--5$\\times$ point-cloud reduction with negligible quality loss. Together, these components yield a unified representation that preserves real-time rendering performance while reducing total storage to 20--30 MB. Extensive experiments across the N3DV and Technicolor Light Field datasets demonstrate that CC-4DGS achieves reconstruction accuracy comparable to state-of-the-art methods such as Swift4D, while offering significantly improved storage efficiency and favorable runtime-memory trade-offs.","authors":["Kyungdae Park","Chae Eun Rhee"],"published":"2026-09-02T06:47:19Z","updated":"2026-09-02T06:47:19Z","abstract_url":"https://arxiv.org/abs/2609.02184v1","html_url":"https://arxiv.org/html/2609.02184v1","pdf_url":"https://arxiv.org/pdf/2609.02184v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02159v1","title":"World-Coherent Decoding: Self-Verifying Test-Time Planning for World Action Models","abstract":"World Action Models (WAMs) aim to control robots by stochastically generating visual futures and then decoding actions, but empirical observations indicate that the results can strongly depend on which future is selected. We propose World-Coherent-Decoding (WCD), a self-verifying test-time planning framework that treats WAM rollouts as falsifiable future--action hypotheses. At each decision step, WCD samples multiple candidates from a frozen WAM and ranks them using internal generative signals: flow-based video surprisal for visual plausibility and action path effort for action-generation stability. After execution, the realized observation audits the selected imagination, yielding an imagination--reality mismatch that trains a lightweight online predictor for future candidate selection. Thus, WCD converts delayed self-verification into pre-execution reliability estimation without updating the backbone model. On RoboTwin 2.0, WCD improves Hard success under limited randomized-scene supervision from $55.80\\%$ to $60.90\\%$, with a $+16.43$ gains on Horizon-3 tasks, and shows qualitative robustness on real Franka visual-shift tests. These results highlight a simple principle: test-time scaling for WAMs depends less on sampling more futures than on selecting reliable ones.","authors":["Chuhan Zhang","Seiji Ito","Kenta Hoshino","Satoshi Ikehata","Ikuro Sato"],"published":"2026-09-02T06:21:36Z","updated":"2026-09-02T06:21:36Z","abstract_url":"https://arxiv.org/abs/2609.02159v1","html_url":"https://arxiv.org/html/2609.02159v1","pdf_url":"https://arxiv.org/pdf/2609.02159v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02118v1","title":"Synergistic Information Disentanglement for Omni-modal Slide Representation Learning in Computational Pathology","abstract":"In computational pathology (CPath), developing omni-modal self-supervised learning (SSL) models that integrate histology, genomics, and clinical reports enables transferable representation learning for whole slide images (WSIs). Existing approaches implicitly force heterogeneous modalities into a uniform latent space by contrastive alignment, causing modality collapse where unique, synergistic diagnostic signals (termed as $\\mathrmΦ$) are discarded in favor of trivial redundancy. We hypothesize that the strongest task-agnostic SSL training signal stems from distilling the synergistic interactions over merely aligning shared redundancy. To this end, we introduce \\textsc{$\\mathrmΦ$-Omni}, a synergistic information disentanglement framework grounded in Partial Information Decomposition (PID) theory for slide representation learning. Unlike standard contrastive approaches, \\textsc{$\\mathrmΦ$-Omni} employs a Synergistic Information Bottleneck (SIB) regulated by the proposed $\\mathrmΦ\\text{ID}$ objective, which explicitly suppresses marginal redundancy while maximizing irreducible synergy, thereby distilling high-order cross-modal interactions. Following pretraining on breast ($n$=1031) and lung ($n$=919) cohorts, \\textsc{$\\mathrmΦ$-Omni} demonstrates superior few-shot performance across five independent external datasets spanning eight tasks compared to supervised and SSL baselines. Source code is available here.","authors":["Mingxin Liu","Chengfei Cai","Anwen Lu","Pengbo Xu","Jun Li","Jinze Li","Depin Chen","Jun Xu"],"published":"2026-09-02T05:16:44Z","updated":"2026-09-02T05:16:44Z","abstract_url":"https://arxiv.org/abs/2609.02118v1","html_url":"https://arxiv.org/html/2609.02118v1","pdf_url":"https://arxiv.org/pdf/2609.02118v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02111v1","title":"Disease Burden over Skin Tone: Decomposing the Dermatology-AI Generalization Gap","abstract":"Dermatology artificial intelligence (AI) models are predominantly trained on light-skinned, cancer-focused image collections, yet they are increasingly proposed for deployment in resource-constrained settings where patients differ from training populations along two confounded axes: skin tone and disease distribution. We investigate whether poor generalization is primarily caused by skin-tone underrepresentation or disease-distribution shift. We evaluate a cancer-trained baseline (ResNet-50 fine-tuned on HAM10000 and ISIC 2019), two dermatology foundation models (DermLIP and MONET), and a general-purpose vision model (DINOv3) as frozen feature extractors. Models are evaluated on a tone-stratified disease-matched dataset (Diverse Dermatology Images, DDI) and a disease-shifted tone-diverse dataset (Skin Condition Image Network, SCIN). Our results show that disease-distribution shift contributes more than skin tone in the evaluated settings. The cancer baseline decreases from 0.62 to 0.21 balanced accuracy when transferred to unfamiliar clinical conditions, while the within-disease skin-tone gap is smaller (0.10-0.18) and inconsistent. Label-free representation analysis shows that this failure reflects a representational limitation rather than only missing output labels: cancer-specialized features poorly cluster unfamiliar conditions (kNN purity lift +0.06 over chance), whereas dermatology-pretrained features retain stronger transferable structure (+0.23). Finally, we show that representation quality predicts recoverable performance under lightweight adaptation. Starting from dermatology foundation models, approximately ten labeled examples per clinical category recover most attainable performance. We release the evaluation protocol and code to support reproducible auditing of dermatology AI generalization.","authors":["Nirajan Kunwor","Sanjaya Poudel","Quoc-Huy Trinh","Jahidul Arafat","Sunil Kumar Gaire"],"published":"2026-09-02T04:55:23Z","updated":"2026-09-02T04:55:23Z","abstract_url":"https://arxiv.org/abs/2609.02111v1","html_url":"https://arxiv.org/html/2609.02111v1","pdf_url":"https://arxiv.org/pdf/2609.02111v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02101v1","title":"Federated LoRA Adaptation of BiomedCLIP Across Four International Chest X-Ray Cohorts","abstract":"Federated learning (FL) lets institutions train a shared model without exchanging data, and Low-Rank Adaptation (LoRA) makes this practical at scale by communicating only compact low-rank updates. Biomedical imaging is a compelling setting for this combination: patient data are archived behind privacy regulations, and institutions differ widely in scanners, protocols, and compute. Such heterogeneity raises the question of how federated LoRA updates should be aggregated, increasingly pressing as multimodal vision-language models become central to medical image analysis. We benchmark federated Parameter-efficient fine-tuning (PEFT) of BiomedCLIP for chest radiograph classification across four public cohorts on three continents (USA, Vietnam, Spain). Federated LoRA adaptation improves shared-class AUC on all four cohorts over the unadapted BiomedCLIP backbone (mean 0.687 to 0.802), showing that the gains come from federated adaptation rather than from the pretrained model's zero-shot ability. Relative to isolated single-cohort training, federation improves the weaker cohorts while largely preserving the strongest and approaches a centralized reference (0.812) that pools all data. The singular value decomposition (SVD)-based product-space aggregation introduced by FlexLoRA is essential to this gain (naive factor averaging drops mean AUC by 0.097), whereas a drift-correcting optimizer (FedProx) shows no benefit over FedAvg in our single-seed runs, consistent with LoRA's low-rank updates already limiting client drift. Biomedical vision-language models can thus be adapted collaboratively across heterogeneous, geographically distributed institutions without centralizing data.","authors":["Sanjaya Poudel","Nirajan Kunwor","Manish Dhakal","Debesh Jha","Sunil Kumar Gaire"],"published":"2026-09-02T04:40:05Z","updated":"2026-09-02T04:40:05Z","abstract_url":"https://arxiv.org/abs/2609.02101v1","html_url":"https://arxiv.org/html/2609.02101v1","pdf_url":"https://arxiv.org/pdf/2609.02101v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02088v1","title":"Rendering-in-the-Loop: An Execution-Driven Agent for Interactive Web Development","abstract":"Multimodal large language models have achieved remarkable progress in front-end web development, generating interactive webpages from multimodal references such as screenshots and interaction videos. However, existing work largely emphasizes visual metrics such as aesthetics and layout similarity, while overlooking the more critical validation of interactive functionality. We present RILA, an execution-driven agent that puts browser rendering in the loop, iteratively editing generated code from runtime interaction feedback. RILA introduces an Action Interaction Verification (AIV) module that replays the reference interaction trajectory on the generated webpage to collect grounded execution-aware observations, and an Execution-aware Rendering Score (ERS) that jointly measures interaction correctness and visual fidelity to guide iterative optimization. We further build an execution-verified data synthesis pipeline that produces diverse, high-quality training data, offering gains complementary to inference-time optimization. On IWR-Bench, RILA consistently improves both interaction and visual fidelity across foundation models. Notably, with our training pipeline, RILA lifts the compact Qwen3.5-9B backbone from 40.40% to 57.52%, surpassing far larger one-shot generators, including the 1T-parameter Kimi-K2.6 (55.61%) and the proprietary GPT-5.5 (55.74%).","authors":["Yilong Guo","Hanqi Chen","Zixiao Ye","Guanzhong Wang","Chen Yu","Zeyu Chen"],"published":"2026-09-02T04:27:45Z","updated":"2026-09-02T04:27:45Z","abstract_url":"https://arxiv.org/abs/2609.02088v1","html_url":"https://arxiv.org/html/2609.02088v1","pdf_url":"https://arxiv.org/pdf/2609.02088v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02085v1","title":"TC-Next: Zero-Shot Multimodal Cyclone Forecasting","abstract":"We present TropicalCycloneNext (TC-Next), a multimodal deep learning model that forecasts tropical cyclone track and intensity at $6$-$24$ h leads by leveraging a foundation model's forecast fields of atmospheric kinematic and thermodynamic fields and GridSat infrared satellite imagery. Trained only on GraphCast forecasts over the Western Pacific (WP), yet reliant only on generic atmospheric variables, TC-Next on GraphCast lowers track error by $15$-$44\\%$ and intensity error by a factor of $3$-$6$ relative to a conventional, rule-based tracker, TempestExtremes; applied without retraining to the forecast fields of Pangu-Weather and IFS HRES, it stays ahead of TempestExtremes on both. Applied zero-shot to the generic weather fields of WeatherNext Cyclones on the 2025 WP season, TC-Next attains lower intensity error at every lead time, and lower or comparable track error, compared to that model's specialized direct tracker in a deterministic comparison. Our ablation studies show that our multimodal model is able to utilize the additional modality to improve performance in tracking errors at every lead time and in intensity prediction at longer lead times.","authors":["Zhe Wang","Sijie Chen","Yiming Luo","Daehyun Kim","Chien-Yi Chang"],"published":"2026-09-02T04:17:22Z","updated":"2026-09-02T04:17:22Z","abstract_url":"https://arxiv.org/abs/2609.02085v1","html_url":"https://arxiv.org/html/2609.02085v1","pdf_url":"https://arxiv.org/pdf/2609.02085v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02077v1","title":"KSG-Net: Key-Sparse and Global-Context Learning for Maritime 3D Ship Detection","abstract":"Accurate 3D ship detection in maritime environments is critical for autonomous navigation, yet remains challenging due to large-scale vessel variations, sparse point clouds of small vessels, and severe sea-clutter interference. Existing methods, primarily based on 2D features or dense representations, struggle to balance detection accuracy and computational efficiency, while sparse 3D detectors designed for road scenes generalize poorly to maritime scenarios. This paper focuses on two key challenges in maritime LiDAR perception: weak feature representation for small and sparse vessels, and insufficient global structural modeling for large vessels due to the limited receptive field of local sparse convolutions. To address these issues, we propose KSG-Net, a Key-Sparse and Global-Context learning network for maritime 3D ship detection. The core idea is to jointly enhance local discriminative features and global structural awareness within a unified fully sparse detection framework. Specifically, a Key Sparse Multi-scale Aggregation (KSMA) module is designed to enhance the representation of small and sparse vessels by selecting informative key voxels and aggregating cross-scale neighborhood features. Furthermore, a Global Context Aggregation (GCA) module is introduced to capture long-range geometric dependencies through scene-level context modeling with gated residual interactions, thereby improving the representation of large vessels. Extensive experiments on the Thames River vessel dataset and simulated datasets demonstrate that KSG-Net consistently outperforms existing methods in multi-scale vessel detection and exhibits strong robustness in complex maritime environments.","authors":["Zhouyuan Huai","Meiqi Wan","Yan Yang","Minshi Chen","Xin Yuan","Wei Wang","Xiao Wang"],"published":"2026-09-02T04:06:40Z","updated":"2026-09-02T04:06:40Z","abstract_url":"https://arxiv.org/abs/2609.02077v1","html_url":"https://arxiv.org/html/2609.02077v1","pdf_url":"https://arxiv.org/pdf/2609.02077v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02075v1","title":"DPA: Decoupling Product-Agnostic Anomaly Representations for Zero-shot Anomaly Generation","abstract":"Industrial anomaly detection benefits from anomaly samples, yet newly deployed products typically provide only normal images, making anomaly samples difficult to collect. Zero-shot anomaly generation offers a promising solution which avoids collection of target-product anomalies. However, existing methods mainly rely on texture images or text descriptions as anomaly sources, which often produce unrealistic anomalies. Observing that similar anomalies can recur across different products, we propose anomaly transfer-based zero-shot generation, which reuses real anomalies from existing source products, making target-product anomalies no longer necessary to generate realistic anomalious samples for unseen target products. Since not every anomaly type suits the target product, an anomaly type filtering mechanism first selects plausible source types. To transfer selected anomaly, we propose DPA, a diffusion-based framework that decouples product-agnostic anomaly representations. Instead of directly extracting anomaly representations, DPA learns product-irrelevant anomaly embeddings through training with the mismatched data pair, enabling transferable anomaly concept learning across products. Furthermore, we design an adaptive mask-guided pipeline that leverages adaptive masks to control the positional and geometric plausibility of generated anomalies during generation. A training-free anomaly labeling module is further introduced to produce pixel-level annotations aligned with generated anomalies. Extensive experiments on MVTec-AD, VisA, and a dedicated anomaly-transfer benchmark demonstrate that the proposed setting and DPA generate more realistic anomalies and significantly improve downstream anomaly detection performance under both zero-shot and few-shot settings. Source code and models will be released.","authors":["Hang Yao","Yansheng Fu","Ming Liu","Zifei Yan","Yanli Ji","Hongzhi Zhang","Wangmeng Zuo"],"published":"2026-09-02T04:03:05Z","updated":"2026-09-02T04:03:05Z","abstract_url":"https://arxiv.org/abs/2609.02075v1","html_url":"https://arxiv.org/html/2609.02075v1","pdf_url":"https://arxiv.org/pdf/2609.02075v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02063v1","title":"LaST-SR: Laplace-Inspired Steady-Transient Complex-Frequency Decomposition for Single Image Super-Resolution","abstract":"Single-image super-resolution (SISR) requires global context modeling for structurally consistent reconstruction. Fourier operators are increasingly adopted for global feature modeling. However, their periodic spectral bases constrain the representation of localized aperiodic variations, limiting the recovery of irregular structures and fine details. In dynamical systems, the Laplace neural operator extends Fourier modes to complex frequencies and decomposes the output signal into complementary steady-state and transient responses to jointly model periodic and aperiodic information. We derive, for the first time, an approximate steady-transient decomposition for two-dimensional feature maps, providing an analytical basis for the proposed complex-frequency decomposition. Accordingly, we propose LaST-SR, centered on a Complex-Frequency Decomposition module that couples a global full-spectrum Fourier branch for image-wide dependencies and long-range structural consistency with a window-conditioned local complex-frequency branch for localized, content-dependent aperiodic variations. To fuse the resulting features, we further design a Steady-Transient Collaborative Aggregation module for cross-branch interaction and joint aggregation. Experiments on five benchmarks show that LaST-SR achieves the best PSNR/SSIM among the compared methods for $\\times2$ and $\\times4$ SISR. Ablation studies further validate the effectiveness of the proposed architecture and its key modeling mechanisms.","authors":["Linhao Li","Zhaojie Pan","Langkun Chen"],"published":"2026-09-02T03:43:43Z","updated":"2026-09-02T03:43:43Z","abstract_url":"https://arxiv.org/abs/2609.02063v1","html_url":"https://arxiv.org/html/2609.02063v1","pdf_url":"https://arxiv.org/pdf/2609.02063v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02059v1","title":"DocHop: Benchmarking Out-of-domain Multi-hop Reasoning in Information-Dense Documents","abstract":"Multimodal Large Language Models (MLLMs) have achieved strong performance on structured visual understanding tasks such as chart and document question answering. However, existing benchmarks typically evaluate these domains in isolation, leaving underexplored a key capability: whether models can use textual context to determine how chart evidence should be selected, interpreted, and aggregated. We introduce DocHop, a benchmark for integrated chart--context reasoning in document-style images. In DocHop, the document narrative specifies multi-step compositional constraints, while charts provide the corresponding data values. Questions are grounded on a semantic reference label defined in the narrative, requiring models to resolve target entities from context before aggregating evidence across multiple charts. To enable systematic evaluation, we construct DocHop via a stochastic logic-first generation pipeline with controllable reasoning depth and visual density, covering 2,074 examples across six task categories. Experiments on a wide range of proprietary and open-source MLLMs show a substantial gap to human performance: annotators achieve over 90% accuracy, while the best model reaches only 62.83%. Reasoning-enhanced models consistently show improved results, but performance degrades as reasoning complexity increases. Overall, DocHop provides a controlled testbed for challenging multi-hop document reasoning.","authors":["Zhuoran Yu","Le Thien Phuc Nguyen","Jaden Park","Xinyi Gu","Zexue He","Soochahn Lee","Rogerio Feris","Yong Jae Lee"],"published":"2026-09-02T03:35:12Z","updated":"2026-09-02T03:35:12Z","abstract_url":"https://arxiv.org/abs/2609.02059v1","html_url":"https://arxiv.org/html/2609.02059v1","pdf_url":"https://arxiv.org/pdf/2609.02059v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02036v1","title":"SelfLift: Accelerating Few-Step Diffusion via Self-Recovering Resolution Transition","abstract":"Few-step diffusion models substantially compress temporal computation, making the spatial cost of each model evaluation an increasingly dominant source of inference latency. Progressive-resolution inference reduces this cost by performing early denoising at low resolution and reserving high-resolution computation for refinement. However, existing methods typically lift intermediate latents directly and rely on subsequent steps to absorb the induced distribution mismatch. In the few-step regime, the limited recovery budget leaves these errors as visible artifacts, constraining how late the transition can occur and, consequently, how efficiently it can be performed. We introduce SelfLift, a self-recovering progressive-resolution framework that derives both transition-repair signals and trajectory-aligned supervision from the generative model itself. SelfLift-zero proposes a training-free Artifact-Aware Consistency Lift, using disagreement between direct latent lifting and pixel-VAE re-encoding as both a localized artifact-risk signal and a model-native correction direction. It enables reliable late transitions without external super-resolution, extra denoiser evaluations, or sampling-schedule modifications. Building on this robust transition, SelfLift-rich performs On-Policy Self Recovery on student-visited states, transferring dense high-resolution guidance from an internal self-teacher while remaining aligned with the altered progressive-resolution dynamics. Across FLUX.2-Klein and Z-Image-Turbo, SelfLift reduces end-to-end latency by 41.5% and 44.1%, respectively. Combined with timestep distillation, it delivers overall speedups of 29.61x and 19.21x over the corresponding 50-step models while preserving competitive generation quality, establishing a stronger speed-quality frontier for few-step diffusion.","authors":["Tingyan Wen","Chenqian Yan","Xurui Peng","Xiazhang Fang","Shuai Wang","Xueqian Wang","Songwei Liu"],"published":"2026-09-02T03:07:42Z","updated":"2026-09-02T03:07:42Z","abstract_url":"https://arxiv.org/abs/2609.02036v1","html_url":"https://arxiv.org/html/2609.02036v1","pdf_url":"https://arxiv.org/pdf/2609.02036v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02018v1","title":"Source-Free Class Relearning: Diagnosing Forgetting in Class Unlearning","abstract":"Class unlearning aims to remove a model's ability to recognize designated forget classes while preserving performance on retain classes. However, low forget accuracy after unlearning does not necessarily mean the class structure has been erased. Approximate unlearning methods can alter classifier decision boundaries while leaving recoverable structure in the representation. Prior work has shown that forget classes can be recovered, but existing approaches require real forget or retain samples, auxiliary data, or reference checkpoints. We study class relearning in a strictly source-free setting, asking whether a forget class can be recovered through a classifier-head update using only the unlearned model. Our approach rests on a theoretical analysis establishing a sufficient alignment condition under which a single gradient step on a synthetic probe set increases the expected logit margin of the forget class. Building on this, we propose a white-box Source-Free Relearning Audit (SFRA), which generates candidate embeddings in representation space and uses model-guided confidence filtering to construct high-confidence retain probes and low-confidence boundary-adjacent probes that are relabelled as the forget class. Gaussian sampling and Softmax confidence are used by default, while ablations with alternative proposal distributions and uncertainty criteria show that recoverability is not specific to these choices. To quantify recoverability, we introduce the Relearning Score (RS), which jointly measures forget-class recovery and retain-accuracy preservation, and report class-matched $Δ$RS relative to a retrained reference. Experiments on CIFAR-10, CIFAR-100, and TinyImageNet with ResNet-18, ViT-B/16, and Swin-T show that several unlearning methods exhibit substantial source-free recoverability, and that for a subset of methods this recoverability exceeds the matched retrained reference.","authors":["Zahra Dehghani","Pablo Piantanida","Mohammadhadi Shateri"],"published":"2026-09-02T02:45:56Z","updated":"2026-09-02T02:45:56Z","abstract_url":"https://arxiv.org/abs/2609.02018v1","html_url":"https://arxiv.org/html/2609.02018v1","pdf_url":"https://arxiv.org/pdf/2609.02018v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02016v1","title":"Perceptually Regularized Diffusion Model for Image Super-Resolution","abstract":"Image super-resolution, which aims to reconstruct high-resolution images from their low-resolution observations, is fundamental to medical imaging, remote sensing, surveillance, microscopy, and scientific visualization. Traditional model-based methods formulate super-resolution as an inverse problem with hand-crafted regularization priors. While interpretable and theoretically grounded, they rely on fixed assumptions and require computationally intensive iterative solvers. Deep learning methods offer data-driven flexibility by learning nonlinear mappings from low- to high-resolution images, among which diffusion models have achieved particularly impressive perceptual quality. However, the standard diffusion training objective is a pixel-domain noise-prediction loss that does not explicitly enforce perceptual fidelity, which can lead to oversmoothing and loss of fine image structure. To address these limitations, we propose a perceptually regularized diffusion framework that incorporates prior knowledge through perceptual-loss-based regularization, improving training convergence and encouraging the recovery of meaningful image features. Experiments on benchmark datasets demonstrate improved perceptual quality and competitive distortion metrics, highlighting the effectiveness of regularization for diffusion-based super resolution.","authors":["Chuxiangbo Wang","Pavithra Venkatachalapathy","Ying Liang","Min Wang","Jing Qin","Yifei Lou","Weihong Guo"],"published":"2026-09-02T02:43:12Z","updated":"2026-09-02T02:43:12Z","abstract_url":"https://arxiv.org/abs/2609.02016v1","html_url":"https://arxiv.org/html/2609.02016v1","pdf_url":"https://arxiv.org/pdf/2609.02016v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02012v1","title":"GeoStore: Finding Small Storefronts in Large Scenes -- A Fine-Grained POI Localization Benchmark with Global-to-Local Asymmetric Matching","abstract":"Point-of-interest (POI) localization -- matching a user's close-up storefront photograph against large-scale geo-tagged street-view imagery -- underpins map construction, POI verification, and location-based services. Its closest existing paradigm, visual place recognition (VPR), assumes symmetric, whole-image matching of the same scene at a comparable scale; POI localization instead must match a close-up query, in which the target fills the frame, against wide references in which the same POI occupies only a small, off-center region among visually similar shops, under a substantial capture-domain gap. We introduce GeoStore, to our knowledge the first benchmark dedicated to this asymmetric, fine-grained, open-set formulation, and show that global-descriptor methods tuned for symmetric VPR are systematically limited on it, since a single global vector dilutes the small target. We further propose GLAM (Global-to-Local Asymmetric Matching), which couples a retrieval-anchoring global descriptor with an asymmetric local pathway: each reference is kept as a compact set of pooled region tokens and matched against a single query probe through a learnable soft late interaction; at inference, the same tokens enable a lightweight mutual-nearest-neighbor re-ranking. GLAM surpasses strong global and two-stage baselines on Recall@1/5/10 and mAP, with ~5x smaller re-ranking features and ~two orders of magnitude lower per-pair matching cost than prior local re-ranking. The benchmark and code will be publicly released.","authors":["Lu Han","Xiting Sun","Hao Wang","Zhiqiang Cao","Ruihuan Du","Ziquan Zeng","Chunlong Lv"],"published":"2026-09-02T02:39:21Z","updated":"2026-09-02T02:39:21Z","abstract_url":"https://arxiv.org/abs/2609.02012v1","html_url":"https://arxiv.org/html/2609.02012v1","pdf_url":"https://arxiv.org/pdf/2609.02012v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02004v1","title":"InstEditSeg: Instruction-Driven Image Editing for Polyp and Skin Lesion Segmentation","abstract":"Accurate segmentation of polyps and skin lesions is pivotal for clinical diagnosis, yet existing methods struggle with low contrast, ambiguous boundaries, and cross-domain distribution discrepancies. Discriminative networks and most diffusion-based segmentation approaches predict standalone binary masks, leaving the visual priors of large-scale pretrained generative models largely unexploited. We propose InstEditSeg, a unified generative framework that reformulates medical segmentation as an instruction-driven image editing problem. Instead of emitting a mask, the model renders a color-coded overlay on the original image, conditioned on a textual instruction, so that the edited output aligns with the natural image distribution learned by latent diffusion models and mitigates the domain gap between natural and medical imagery. To recover fine anatomical structures, we introduce DINOv3 as an auxiliary visual encoder and a DINO Feature Guidance Block that builds a multi-scale feature pyramid. The pyramid is fused into the diffusion U-Net by channel concatenation and zero-initialized convolution so that hierarchical discriminative priors can be injected without perturbing the pretrained weights. A dual-branch classifier-free guidance strategy requiring only two forward passes per denoising step reduces inference cost. On polyp and skin lesion benchmarks the framework achieves accuracy competitive with strong discriminative baselines, and it further demonstrates concrete advantages of the generative formulation: notably better cross-domain generalization on unseen data, more complete multi-lesion segmentation, instruction-conditioned task control, and sampling flexibility. We also analyze the strengths and limitations of the paradigm, including its color sensitivity and unsupported attribute-conditioned selection. Code is available at: https://github.com/wincharm001/InstEditSeg.","authors":["Ziquan Liu","Zhewei Zhu","Xuyang Shi"],"published":"2026-09-02T02:28:29Z","updated":"2026-09-02T02:28:29Z","abstract_url":"https://arxiv.org/abs/2609.02004v1","html_url":"https://arxiv.org/html/2609.02004v1","pdf_url":"https://arxiv.org/pdf/2609.02004v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02002v1","title":"InsightSeg: Reusing Correction Insights for Guideline-Consistent Segmentation","abstract":"Guideline-consistent semantic segmentation requires more than category recognition, as real-world labeling policies demand fine-grained, task-specific decisions. Recent multi-agent refinement systems improve compliance with such textual guidelines by detecting and correcting errors. However, they are stateless: feedback from the critiquing agent is discarded, causing the same guideline-specific mistakes to be repeatedly rediscovered and corrected across the dataset at the cost of additional refinement. We introduce InsightSeg, an episodic memory mechanism that converts successful correction episodes into reusable, visually grounded insights. A meta-analyzer distills each qualifying episode into directive natural-language insights and anchors them to the local image regions that caused the error using patch-level visual concept vectors. On subsequent images, these concepts are matched against dense patch embeddings to retrieve relevant insights, which condition the segmenting agent before making its first prediction. This shifts the system from correcting recurring errors to preventing them, improving segmentation quality before any refinement occurs. Across Waymo and Cityscapes, InsightSeg improves both first-pass and final guideline-consistent segmentation performance while requiring fewer refinement steps, demonstrating that multi-agent refinement can become more accurate and efficient by drawing on past correction experience.","authors":["Vanshika Vats","Ashwani Rathee","James Davis"],"published":"2026-09-02T02:22:35Z","updated":"2026-09-02T02:22:35Z","abstract_url":"https://arxiv.org/abs/2609.02002v1","html_url":"https://arxiv.org/html/2609.02002v1","pdf_url":"https://arxiv.org/pdf/2609.02002v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02000v1","title":"Who Drives the Probability Game of VLMs? A Temporal Causal Drive Evaluation Framework","abstract":"Vision-language models (VLMs) are increasingly evaluated on complex image and video understanding tasks, yet conventional metrics primarily assess final-answer quality and reveal little about how different information sources shape the generation process. We propose a causal and temporal evaluation framework that traces the evolving roles of visual input, question text, and generated prefixes during autoregressive decoding. Grounded in a Structural Causal Model, we use interventions and backdoor adjustment to derive three step-indexed causal-drive metrics---Visual Causal Drive (VCD), Question Causal Drive (QCD), and Prefix Causal Drive (PCD)---for characterizing source-specific generation patterns without requiring reference answers. Experiments on Qwen3-VL-8B-Instruct across MAVIS, LLaVA-Video-178K, and MiraData, together with cross-model validation on InternVL2-8B, reveal a consistent transition from stronger early question and visual guidance toward increasing reliance on generated prefixes. Randomized-intervention validation shows that QCD and PCD reduce recovery error over observational PMI baselines by 34.8\\% and 47.1\\%, respectively. On VLMBias, the prefix--visual imbalance score achieves 0.767 AUROC and 0.873 AUPRC for distinguishing prior-driven from visually grounded generations. These results show that causal-drive trajectories provide complementary source-level diagnostics for multimodal generation.","authors":["Shuyao Xiao","Shengling Wang","Haoyu Niu","Ke Chao","Changwei Xu","Xinran Duan","Chaoyong Jiang"],"published":"2026-09-02T02:19:36Z","updated":"2026-09-02T02:19:36Z","abstract_url":"https://arxiv.org/abs/2609.02000v1","html_url":"https://arxiv.org/html/2609.02000v1","pdf_url":"https://arxiv.org/pdf/2609.02000v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.01997v1","title":"Linear Fusion MultiDiffusion for Fast Training-Free Spherical Panorama Generation","abstract":"We propose LF-MultiDiffusion, a training-free panorama generation method that extends MultiDiffusion to support linear projections between target and reference image spaces. Our key idea is to reformulate latent aggregation as a regularized least-squares problem and solve it efficiently with a Krylov-based iterative solver inside the denoising loop. This formulation enables denser and more natural mappings than prior training-free methods, yielding more stable generation with far fewer perspective views. As a result, LF-MultiDiffusion reduces the number of image generator evaluations during denoising and significantly improves inference efficiency. Experiments show that LF-MultiDiffusion achieves better visual quality, text alignment, and panoramic consistency than the strongest training-free baseline, while providing a 15.36$\\times$ speedup. Our project page is available at: https://ahykw.github.io/lfmd.","authors":["Akio Hayakawa","Yusuke Mukuta","Tatsuya Harada"],"published":"2026-09-02T02:13:26Z","updated":"2026-09-02T02:13:26Z","abstract_url":"https://arxiv.org/abs/2609.01997v1","html_url":"https://arxiv.org/html/2609.01997v1","pdf_url":"https://arxiv.org/pdf/2609.01997v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-09-03T05:25:18+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":70,"new_or_recent_papers":[{"id":"2609.02886v1","title":"SolarWM: Open Data and Scalable Training for Long-Horizon Video World Models","abstract":"We introduce SolarWM, a fully open foundation for building interactive video world models from data preparation through long-horizon inference. Training across heterogeneous data sources and video backbones is challenging: datasets differ in temporal scale, camera geometry, visual quality, motion, and captioning styles, while video generators use distinct representations and architectures. Naive data mixing and model-specific implementations therefore produce inconsistent supervision and make results difficult to reproduce and compare. SolarWM addresses this coupling with a reconfigurable multi-source data engine and a backbone-native adaptation framework. The engine converts 1.43 million canonical clips from 10 datasets into a unified, frame-aligned contract covering visual observations, metric camera geometry, captions, quality metadata, selection decisions, and provenance, while decoupling source processing from mixture construction. Under shared camera-conditioning, training, and inference interfaces, we instantiate four 5B--33B models based on Wan2.2, LTX-2.5, and MiniMax-H3 while preserving their native representations and objectives. A unified three-stage recipe combines bidirectional adaptation, teacher-forced autoregressive initialization, and distribution matching distillation. The resulting causal models enable real-time interaction over rollouts ranging from minutes to hours after being trained on only 5s sequences. By releasing the resulting data, pipeline, recipes, weights, and framework, SolarWM provides a reproducible and extensible foundation for interactive world-model research.","authors":["Junchao Huang","Guian Fang","Shengju Qian","Xianghao Kong","Zhuoran Zhao","Wei Huang","Yihua Du","Zixin Zhang","Justin Cui","Yuchao Gu","Yukang Chen","Xinting Hu","Tianyu He","Shaoshuai Shi","Zhuotao Tian","Xin Wang","Mike Zheng Shou","Li Jiang"],"published":"2026-09-02T17:59:41Z","updated":"2026-09-02T17:59:41Z","abstract_url":"https://arxiv.org/abs/2609.02886v1","html_url":"https://arxiv.org/html/2609.02886v1","pdf_url":"https://arxiv.org/pdf/2609.02886v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":82541,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：We introduce SolarWM, a fully open foundation for building interactive video world models from data preparation through long-horizon inference. Training across heterogeneous data sources and video backbones is challenging: datasets differ in temporal scale, c...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02864v1","title":"Thinking in Pictures: A Systematic Benchmark for Reasoning-driven Image Generation","abstract":"Recent advancements in unified generative models (UGMs) and world simulators have achieved unprecedented results in visual perception and synthesis. However, these models primarily rely on surface-level event alignment, leaving the capacity for high-level visual reasoning underexplored. True visual generative intelligence demands \"Reasoning-to-Generation\", an ability to infer latent rules from visual inputs and manifest solutions through precise, logically constrained visual outcomes. We introduce RIG-BENCH, a novel comprehensive benchmark that systematically evaluates Reasoning-driven Image Generation (RIG) across four cognitively demanding domains: Concept-based, Transformation-based, Pattern & Structure, and Scenario-based. Featuring 2000 curated samples, RIG-BENCH serves as a rigorous stress test for RIG. Our extensive evaluations of state-of-the-art UGMs and image/video generation models reveal a significant reasoning-generation gap, wherein models frequently produce locally plausible but globally illogical outputs. RIG-BENCH provides a vital diagnostic framework to guide the development of next-generation, logically grounded UGMs and world simulators.","authors":["Yutong Liu","Nan Huang","Xu Cao","James M. Rehg"],"published":"2026-09-02T17:48:02Z","updated":"2026-09-02T17:48:02Z","abstract_url":"https://arxiv.org/abs/2609.02864v1","html_url":"https://arxiv.org/html/2609.02864v1","pdf_url":"https://arxiv.org/pdf/2609.02864v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":84686,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Recent advancements in unified generative models (UGMs) and world simulators have achieved unprecedented results in visual perception and synthesis. However, these models primarily rely on surface-level event alignment, leaving the capacity for high-level vis...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02860v1","title":"PlantC2USeg: Cross-Scale Consistent Pre-Training for Few-Shot Unified Plant Point Cloud Segmentation","abstract":"Modern crop breeding demands precise organ-level analysis for trait quantification, making plant point cloud segmentation (PPCS) increasingly important. However, conventional deep learning approaches rely heavily on densely annotated datasets that are labor-intensive to acquire. Unified PPCS adaptation from distribution-shifted examples with minimal additional training remains challenging. To address this, we propose PlantC2USeg, a deep transfer learning framework featuring cross-scale consistency learning to explicitly align features across spatial scales and an information-restricted decoding strategy that prevents reconstruction shortcuts and promotes robust adaptation. The resulting pre-training enables stable few-shot generalization across species and sensing conditions, while unified fine-tuning with inherited thresholds further reduces adaptation overhead. Under full supervision on Soybean3D, PlantC2USeg achieves the highest semantic IoU and instance mWCov among compared methods, at 91.91% and 94.62%. With 20 labeled samples, it leads both metrics at 89.78% and 90.27%; with only 10 samples, it retains the highest mWCov of 83.23% while achieving 83.19% IoU. Across HR3D, 10-shot transfer to tobacco, tomato, and sorghum averages 78.41% IoU and 79.42% mWCov, while 22-shot transfer to SYAU-Maize achieves the highest IoU and mRec at 92.75% and 93.51%. Furthermore, a leading category-averaged mIoU of 85.0% on ShapeNet Part demonstrates the framework's capability to handle diverse shape variations beyond agricultural domains. These results demonstrate that PlantC2USeg reduces overall adaptation effort under distribution shifts, enabling scalable plant phenotyping and transferable 3D representation learning beyond agriculture.","authors":["Yu Tian","Xintong Jiang","Jan Franklin Adamowski","Shiv O. Prasher","Shangpeng Sun"],"published":"2026-09-02T17:43:56Z","updated":"2026-09-02T17:43:56Z","abstract_url":"https://arxiv.org/abs/2609.02860v1","html_url":"https://arxiv.org/html/2609.02860v1","pdf_url":"https://arxiv.org/pdf/2609.02860v1.pdf","matched_keywords":["3d","representation","instance"],"source_used":"html","source_text_chars":118584,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, instance 相关；摘要显示其主要贡献为：Modern crop breeding demands precise organ-level analysis for trait quantification, making plant point cloud segmentation (PPCS) increasingly important. However, conventional deep learning approaches rely heavily on densely annotated datasets that are labor-i...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02854v1","title":"MuyBridge: Mobile Human Center-of-Mass Estimation from Monocular Video via Sparse Fusion","abstract":"The 3D center of mass (CoM) is a primary quantity in the biomechanical analysis of sport, rehabilitation, and clinical movement, yet existing 3D pose tracking, mesh recovery, and multi-view triangulation methods either optimize 3D keypoint accuracy without anatomical constraints or carry compute and capture infrastructure too heavy to deploy where CoM tracking is most useful. As a result, the metric CoM remains difficult for coaches and movement analysts to measure from a single camera where athletes train and compete. In this work, we introduce MuyBridge, an on-device system that estimates the athlete's segmental center of mass trajectory from a single phone camera video stream. MuyBridge couples a compact 2D pose network and a distilled single-step monocular depth network through an analytic metric fusion that uses anatomical and physical priors to anchor the metric CoM, requiring no 3D or task-specific supervision. Evaluated on the athletic movements of AthletePose3D (running, track and field, and figure skating), MuyBridge achieves 33-41 mm vertical CoM error and 2.3-6.6% absolute-relative range error (AbsRel) under a one-time calibration, and produces CoM estimates at the 63 FPS pose-estimation rate using asynchronous 2.86 Hz depth updates on iPhone 15. Code is available at: https://github.com/Abradshaw1/Muybridge","authors":["Aidan Bradshaw","Marco Giordano","David Rode","Andreas Habersack","Elif Basokur","Annika Kruse","Markus Tilp","Michele Magno","Peter Wolf","Luca Benini","Christoph Leitner"],"published":"2026-09-02T17:38:36Z","updated":"2026-09-02T17:38:36Z","abstract_url":"https://arxiv.org/abs/2609.02854v1","html_url":"https://arxiv.org/html/2609.02854v1","pdf_url":"https://arxiv.org/pdf/2609.02854v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":60104,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：The 3D center of mass (CoM) is a primary quantity in the biomechanical analysis of sport, rehabilitation, and clinical movement, yet existing 3D pose tracking, mesh recovery, and multi-view triangulation methods either optimize 3D keypoint accuracy without an...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:18+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02847v1","title":"RoGe: Novel View Synthesis via End-to-End Implicit Reconstruction and Generation","abstract":"Novel view synthesis from sparse inputs requires both geometric grounding from the observed views and generative priors of unobserved regions, motivating recent hybrid methods that combine reconstruction and generation. However, existing methods bridge the two with rendered images or explicit 3D representations such as point maps or 3D Gaussians. Generation is thus conditioned on a lossy and imperfect projection of the scene, inheriting its errors, and reconstruction receives no signal from generation to correct them. We present RoGe, an end-to-end unified reconstruction and generation framework that removes this explicit bridge. It targets roaming within a scene anchored by sparse views: given a few posed images and a camera trajectory, it synthesizes a temporally coherent video along that trajectory. From the sparse input views, RoGe builds an implicit scene representation with a feed-forward reconstruction model, and queries it with target camera rays to obtain per-view geometric features. These features are injected into a video diffusion model as conditioning, without any 3D intermediate. Both modules are trained jointly, so the generation objective directly shapes its own geometric conditioning. We conduct experiments on DL3DV, where RoGe outperforms reconstruction-based, generation-based, and hybrid baselines on image-level metrics and video-level temporal consistency. Ablations confirm that ray-queried implicit features outperform both raw reconstruction tokens and rendered RGB as conditioning, and that joint training brings further gains.","authors":["Xiaolei Lang","Ze Kang","Zehao Huang","Naiyan Wang"],"published":"2026-09-02T17:32:35Z","updated":"2026-09-02T17:32:35Z","abstract_url":"https://arxiv.org/abs/2609.02847v1","html_url":"https://arxiv.org/html/2609.02847v1","pdf_url":"https://arxiv.org/pdf/2609.02847v1.pdf","matched_keywords":["video","3d","representation","diffusion"],"source_used":"html","source_text_chars":53246,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d, representation, diffusion 相关；摘要显示其主要贡献为：Novel view synthesis from sparse inputs requires both geometric grounding from the observed views and generative priors of unobserved regions, motivating recent hybrid methods that combine reconstruction and generation. However, existing methods bridge the tw...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02839v1","title":"Efficient All-in-One Weather Restoration using Spectral Harmonization","abstract":"Adverse weather conditions such as rain, haze, and snow significantly degrade image quality, posing challenges for both human perception and physical AI. Existing restoration methods require large computational budgets, struggling to process high-resolution images and handle different degradations. In this paper, we present Frequency Reconstruction via Spectral Harmonization, a novel lightweight all-in-one restoration method that explicitly decomposes feature representations into high- and low-frequency components at each scale of a hierarchical encoder-decoder architecture. By combining spectral decomposition with spatial processing through Fourier-based skip connections, FReSH-IR captures complementary frequency information without sacrificing spatial detail. Our approach achieves similar restoration quality with 80% fewer parameters and operations than transformer-based models. Extensive experiments demonstrate that our method offers a great efficiency-performance trade-off, highlighting its practical applications in constrained-resource systems.","authors":["Paula Garrido-Mellado","Daniel Feijoo","Yuning Cui","Alvaro Garcia","Marcos V. Conde"],"published":"2026-09-02T17:21:06Z","updated":"2026-09-02T17:21:06Z","abstract_url":"https://arxiv.org/abs/2609.02839v1","html_url":"https://arxiv.org/html/2609.02839v1","pdf_url":"https://arxiv.org/pdf/2609.02839v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":54550,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Adverse weather conditions such as rain, haze, and snow significantly degrade image quality, posing challenges for both human perception and physical AI. Existing restoration methods require large computational budgets, struggling to process high-resolution i...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02813v1","title":"GDB-Reward: From Evaluation Metrics to Training Rewards for Graphic Design","abstract":"Text-to-image models excel at natural image synthesis but struggle with graphic design, where success depends on satisfying precise constraints on typography, layout, color, and visual communication. While prompt optimization offers an attractive alternative to expensive diffusion model fine-tuning, learning prompts for frozen image generators requires informative reward functions despite the entirely non-differentiable generation process. Reinforcement learning does not require differentiable objectives; it requires only scalar rewards capable of ranking candidate outputs. This raises a simple question: can design evaluation metrics themselves become reinforcement learning rewards? Our central contribution is GDB-Reward, a framework that systematically transforms heterogeneous graphic design evaluation metrics into a unified reinforcement learning reward. Experiments demonstrate that GDB-Reward provides an effective optimization objective, substantially improving adherence to the design specification in perceptual quality, rendering fidelity, and spatial accuracy while keeping the image generator entirely frozen. More broadly, our results demonstrate that heterogeneous, non-differentiable evaluation metrics can move beyond passive benchmarking to become effective optimization objectives for reinforcement learning in domains where differentiable supervision is unavailable.","authors":["Adrienne Deganutti","Purvanshi Mehta","Simon Hadfield","Andrew Gilbert"],"published":"2026-09-02T16:54:31Z","updated":"2026-09-02T16:54:31Z","abstract_url":"https://arxiv.org/abs/2609.02813v1","html_url":"https://arxiv.org/html/2609.02813v1","pdf_url":"https://arxiv.org/pdf/2609.02813v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":57167,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Text-to-image models excel at natural image synthesis but struggle with graphic design, where success depends on satisfying precise constraints on typography, layout, color, and visual communication. While prompt optimization offers an attractive alternative...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02780v1","title":"ShallowStream: Index Shallow then Answer Deep for Streaming Video Understanding","abstract":"Streaming video understanding is a critical capability for real-world applications, including embodied intelligence, autonomous driving, industrial monitoring, surveillance and early warning, and wearable assistants. However, processing continuous video streams with multimodal large language models (MLLMs) is computationally expensive. Existing efforts have explored reducing streaming overhead through visual token pruning, token merging, quantization, on-demand frame retrieval, and context offloading. However, most existing methods overlook the dimension of model depth. Repeatedly executing full-depth MLLM prefill over incoming frames is prohibitively expensive, incurring substantial computational overhead and causing the KV cache to grow at a rate directly proportional to the prefill depth. To address these challenges, we propose ShallowStream, a novel framework that leverages the shallow layers of an MLLM to simultaneously perform frame encoding and retrieval index building. During stream processing, ShallowStream maintains an always-on lightweight index using the KV cache of shallow layers. During query-time answering, we leverage the attention scores generated by the shallow layers to score context frames and employ a diversity-aware selection strategy to retrieve precise and comprehensive evidence. ShallowStream achieves performance on par with the strongest existing streaming methods, while reducing per-frame prefill latency and 10-second end-to-end latency by up to 52.1x and 11.9x, respectively. Our code is available at https://github.com/CURRENTF/ShallowStream.","authors":["Jitai Hao","Ke Yang","Qiang Huang","Jun Yu"],"published":"2026-09-02T16:14:48Z","updated":"2026-09-02T16:14:48Z","abstract_url":"https://arxiv.org/abs/2609.02780v1","html_url":"https://arxiv.org/html/2609.02780v1","pdf_url":"https://arxiv.org/pdf/2609.02780v1.pdf","matched_keywords":["video","retrieval","multimodal"],"source_used":"html","source_text_chars":76741,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, multimodal 相关；摘要显示其主要贡献为：Streaming video understanding is a critical capability for real-world applications, including embodied intelligence, autonomous driving, industrial monitoring, surveillance and early warning, and wearable assistants. However, processing continuous video strea...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02776v1","title":"Video-Based Palm-Vein Authentication under Challenging Conditions","abstract":"Palm-vein biometrics are increasingly used for secure, contactless authentication. Yet real-world deployment exposes them to surface noise (sweat, dirt), illumination and motion variation, and temperature-driven changes in vascular visibility, which remain underexplored for lack of data captured under such conditions. To study these effects, we introduce the Columbia University Palm-vein (CUP) dataset, to our knowledge the first public video-based palm-vein dataset. CUP records every palm under four surface conditions (a clean baseline, warm, wet, and dirty) and pairs each subject with physiological and demographic metadata. On it we benchmark twenty-one recognizers spanning static, video, and multi-frame aggregation architectures. Models that verify reliably on clean palms lose most of their accuracy on dirty ones, and the mean equal error rate (EER) roughly quadruples. We recover much of that robustness along both axes of the capture. Temporally, a consensus over the few frames the sensor already returns cancels transient corruption; spatially, a test-time matcher that adds no learned parameters fuses the global cosine with a saliency-steered region-level optimal transport that routes the comparison around corrupted regions. The full design leads on every surface of CUP in EER, TAR@FAR=0.01, and Rank-1, at 4.3M parameters and 3.1 GFLOPs, a fraction of the video models' cost. Attached to four frozen state-of-the-art backbones it cuts their mean EER by 29-37% without retraining, and on four public single-image datasets the regional matching alone still helps. A preliminary audit across ten demographic and physiological traits finds two warm-condition gaps, along body water and gender, that survive multiple-comparison correction. CUP will be released for non-commercial research use at https://github.com/MobileX-CU/CUP_v1 upon publication.","authors":["Xiaofeng Yan","Kechen Liu","Abhilash Venkatesh","Cathy Zhang","Xia Zhou","Salvatore Stolfo"],"published":"2026-09-02T16:12:27Z","updated":"2026-09-02T16:12:27Z","abstract_url":"https://arxiv.org/abs/2609.02776v1","html_url":"https://arxiv.org/html/2609.02776v1","pdf_url":"https://arxiv.org/pdf/2609.02776v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":85454,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Palm-vein biometrics are increasingly used for secure, contactless authentication. Yet real-world deployment exposes them to surface noise (sweat, dirt), illumination and motion variation, and temperature-driven changes in vascular visibility, which remain un...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02747v1","title":"InceptionGS: Generative Bootstrapping for Large-Scale Gaussian Splatting under Unstructured View Sampling","abstract":"Achieving truly immersive large-scale scene digitization necessitates consistent and visually pleasing rendering across all possible viewing perspectives. However, collecting multi-view images covering every fine detail of a large-scale scene is prohibitive due to scene complexity, capture cost, negligence, or accessibility constraints. As a result, the sampled views tend to be highly unstructured -- the majority of the scene is well covered yet certain regions inevitably lack sufficient observations. Existing reconstruction based methods are vulnerable to view scarcity while generation based approaches suffer from generalization, controllability, and 3D consistency issues. To address this challenge, we propose InceptionGS, which bootstraps Gaussian splatting by subtly balancing reconstruction and generation. Starting from an initial Gaussian splatting, InceptionGS reasonably rethinks and repairs problematic regions caused by view scarcity while preserving the quality elsewhere, by softly incorporating scene- and view-adaptive generative priors. Extensive experiments on real-world large-scale scenes demonstrate the superiority and broad applicability of our approach in handling unstructured imagery and boosting high-fidelity Gaussian splatting. Please refer to the supplementary video for better visual demonstrations.","authors":["Tianheng Lu","Guangyu Wang","Ruqi Huang","Lu Fang"],"published":"2026-09-02T15:48:15Z","updated":"2026-09-02T15:48:15Z","abstract_url":"https://arxiv.org/abs/2609.02747v1","html_url":"https://arxiv.org/html/2609.02747v1","pdf_url":"https://arxiv.org/pdf/2609.02747v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":60930,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Achieving truly immersive large-scale scene digitization necessitates consistent and visually pleasing rendering across all possible viewing perspectives. However, collecting multi-view images covering every fine detail of a large-scale scene is prohibitive d...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02731v1","title":"RVSD: Retrieval Vision Sparse Decoding for Mitigating Visual Hallucinations in Large Vision-Language Models","abstract":"Large vision-language models have achieved remarkable success in vision-language tasks. However, they remain prone to Visual Hallucinations (VHs), undermining their reliability in real-world applications. Existing solutions typically require curated datasets, additional training, or multi-round decoding, resulting in considerable computational overhead. In this paper, we propose \\textbf{RVSD} (\\underline{R}etrieval \\underline{V}ision \\underline{S}parse \\underline{D}ecoding), a training-free and plug-and-play decoding framework that, for the first time, unifies token sparsification and \\textbf{Semantic-Space Visual Retrieval} (SSVR) within a single decoding pass. Within RVSD, we introduce a \\textbf{semantics-directed token selection} strategy that selectively sparsifies redundant tokens while preserving critical visual information. We further propose the SSVR mechanism, which reformulates visual compensation as an on-demand cross-modal retrieval process within a shared semantic space. Extensive experiments demonstrate that RVSD achieves state-of-the-art performance in mitigating VHs while maintaining robust suppression capabilities under long-context generation settings. Our code is available here.\\footnote{https://github.com/canjie-liu/RVSD}","authors":["Canjie Liu","Jiawen Kang","Jinbo Wen","Zishao Zhong"],"published":"2026-09-02T15:40:40Z","updated":"2026-09-02T15:40:40Z","abstract_url":"https://arxiv.org/abs/2609.02731v1","html_url":"https://arxiv.org/html/2609.02731v1","pdf_url":"https://arxiv.org/pdf/2609.02731v1.pdf","matched_keywords":["retrieval"],"source_used":"html","source_text_chars":82346,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval 相关；摘要显示其主要贡献为：Large vision-language models have achieved remarkable success in vision-language tasks. However, they remain prone to Visual Hallucinations (VHs), undermining their reliability in real-world applications. Existing solutions typically require curated datasets,...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02717v1","title":"MV-dVRK: A Multi-Viewpoint Benchmark for Spatial Surgical Perception","abstract":"Large-scale training and refined optimization techniques have greatly improved sparse multi-view 3D reconstruction. Despite their relevance to surgery, such methods have never before been rigorously evaluated on real endoscopic images. Current clinical telerobots deploy a single stereo camera inside the patient, making multi-viewpoint data extremely rare. This paper presents MV-dVRK, the first ex-vivo surgical dataset to combine multiple exposure-synchronized stereo viewpoints with accurate surface geometry and camera poses. The static subset of the benchmark provides dense SfM reference geometry, validated against an industrial 3D scanner, together with ground-truth camera poses and sparse-view test sets. We use MV-dVRK to systematically compare zero-shot monocular, stereo, multi-stereo, and multi-view 3D reconstruction methods as the number of viewpoints increases. With two endoscopes, multi-stereo reconstruction achieves the highest coverage. With a third viewpoint, optimization-based multi-view methods perform best, covering 67% of ground-truth surface points within a 1 mm tolerance and recovering highly accurate relative camera poses. By contrast, feed-forward foundation models cover only 43% of the ground-truth surface in the same setting. MV-dVRK also includes ten dynamic sequences spanning multiple surgical tasks, with increasing kinematic complexity and tissue deformation, providing a basis for future research in multi-viewpoint surgical perception. The project is available at: https://mv-dvrk.is.mpg.de.","authors":["Guido Caccianiga","Sergey Prokudin","Yutong Chen","Bernard Javot","Rachael L'Orsa","Omer Burak Aladağ","Yarden Sharon","Jens Rolinger","Ivan Capobianco","Anton Deguet","Siyu Tang","Katherine J. Kuchenbecker"],"published":"2026-09-02T15:25:28Z","updated":"2026-09-02T15:25:28Z","abstract_url":"https://arxiv.org/abs/2609.02717v1","html_url":"https://arxiv.org/html/2609.02717v1","pdf_url":"https://arxiv.org/pdf/2609.02717v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":52855,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Large-scale training and refined optimization techniques have greatly improved sparse multi-view 3D reconstruction. Despite their relevance to surgery, such methods have never before been rigorously evaluated on real endoscopic images. Current clinical telero...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02697v1","title":"Generating Medical Image Counterfactuals using Causal Explanations","abstract":"Deep learning models have achieved impressive performance in medical image diagnosis, yet their deployment in clinical settings remains constrained by limited explainability. Counterfactual images provide one means of auditing model behavior by showing how an image would need to change for a classifier to produce a different prediction. Existing approaches typically generate such explanations using auxiliary models, including generative adversarial networks and diffusion models. While often capable of producing visually realistic images, these methods explain one black-box model using another, making it difficult to separate the classifier's decision-making process from the inductive biases of the generator. We propose a novel counterfactual-generation framework that requires no generative model. Instead, counterfactuals are constructed directly from causal evidence extracted from the classifier. The resulting approach is deterministic, requires no additional model training, and enables controllable edits within user-specified regions of interest. Experiments on real-world medical imaging datasets demonstrate that the proposed method successfully changes classifier predictions while remaining closer to the original image than generative baselines, providing a more direct and transparent view of the classifier's decision boundary.","authors":["David A. Kelly","Tom Yaacov","Nathan Blake","Sander Beckers","Hana Chockler"],"published":"2026-09-02T15:03:42Z","updated":"2026-09-02T15:03:42Z","abstract_url":"https://arxiv.org/abs/2609.02697v1","html_url":"https://arxiv.org/html/2609.02697v1","pdf_url":"https://arxiv.org/pdf/2609.02697v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":48857,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Deep learning models have achieved impressive performance in medical image diagnosis, yet their deployment in clinical settings remains constrained by limited explainability. Counterfactual images provide one means of auditing model behavior by showing how an...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02689v1","title":"GaLe: memory-efficient Global Approximate and Local Exact features","abstract":"Embedded devices typically lack the resources of GPU-equipped machines, and existing inference methods suffer from either high computational overhead (patch-based) or accuracy loss (approximation-based). We propose GaLe, a memory-efficient technique that enables the deployment of pretrained networks on constrained devices without retraining. GaLe partitions feature maps into two components: a local exact (Le) representation that preserves fine details and a global approximate (Ga) representation that retains long-range dependencies. Unlike standard tiling, GaLe supports global operations and attention mechanisms found in hybrid CNN-transformer models. Validated on ImageNet, our method matches exact-inference performance while achieving up to 65% speedup and 90% RAM reduction on a Cortex-M33 compared to patch-based inference. We further demonstrate GaLe's versatility across classification, detection, and generation tasks, highlighting its potential as a foundation for resource-efficient architecture design.","authors":["Alberto Ancilotto","Elisabetta Farella"],"published":"2026-09-02T14:56:18Z","updated":"2026-09-02T14:56:18Z","abstract_url":"https://arxiv.org/abs/2609.02689v1","html_url":"https://arxiv.org/html/2609.02689v1","pdf_url":"https://arxiv.org/pdf/2609.02689v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":41215,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Embedded devices typically lack the resources of GPU-equipped machines, and existing inference methods suffer from either high computational overhead (patch-based) or accuracy loss (approximation-based). We propose GaLe, a memory-efficient technique that enab...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02664v1","title":"Query Rewriting for Complex Object Segmentation in 4D Gaussian Representations","abstract":"Recent 4D Gaussian representation frameworks have demonstrated strong performance in language-guided dynamic scene understanding. However, these methods remain highly sensitive to verbose and narrative-style queries that contain noisy contextual information. In this paper, we investigate the impact of query rewriting for complex object segmentation in 4D Gaussian representations. Inspired by recent findings in retrieval-augmented language models and keyword-guided query reformulation, we propose a training-free reinterpretation strategy that transforms long descriptive queries into concise keyword-grounded forms. Our approach progressively reduces linguistic noise while preserving semantic anchors relevant to object-centric representations. Experiments on HyperNeRF and Neu3D demonstrate that concise rewritten queries significantly improve both temporal localization and spatial segmentation performance. In particular, our method improves average temporal accuracy from 60.92% to 92.21% and average vIoU from 20.08% to 76.94% without any additional fine-tuning. Extensive ablation studies further reveal that shorter, keyword-focused queries consistently yield stable video-feature similarity distributions and better alignment with object-centric Gaussian representations","authors":["Thanh-Khoi Nguyen","Thien-Phuc Tran","Minh-Triet Tran"],"published":"2026-09-02T14:40:22Z","updated":"2026-09-02T14:40:22Z","abstract_url":"https://arxiv.org/abs/2609.02664v1","html_url":"https://arxiv.org/html/2609.02664v1","pdf_url":"https://arxiv.org/pdf/2609.02664v1.pdf","matched_keywords":["video","retrieval","3d","representation"],"source_used":"html","source_text_chars":43080,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, 3d, representation 相关；摘要显示其主要贡献为：Recent 4D Gaussian representation frameworks have demonstrated strong performance in language-guided dynamic scene understanding. However, these methods remain highly sensitive to verbose and narrative-style queries that contain noisy contextual information....","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02663v1","title":"Characterizing Text Branch Sensitivity in Medical Vision-Language Segmentation via Evidence Decoupling","abstract":"Pretrained vision-language models (VLMs) have shown promising performance in medical image segmentation by incorporating clinical text. However, it remains unclear how much textual information actually contributes to pixel-level predictions. In this work, we systematically investigate the role of text in multimodal medical image segmentation. We first analyze several commonly used fusion strategies and find that segmentation performance is largely insensitive to the choice of fusion module. To further understand modality interactions, we propose an Evidence Decoupling Decoder (EDD) based on evidential deep learning and deep supervision. EDD serves as an internal representation analysis tool that decomposes image evidence and text-modulated evidence throughout the decoding process while maintaining competitive segmentation performance. Experimental results show that the sensitivity to text perturbation varies substantially across datasets. On BUSI and BTMRI, removing text causes catastrophic performance drops, indicating strong model reliance on textual input. On ISIC and Kvasir-SEG, text exerts relatively marginal influence. We further find that text affects predictions mainly through global semantic modulation rather than independent spatial localization, and that the specific semantic components driving text sensitivity differ across datasets. These findings provide a deeper understanding of modality interaction in multimodal medical image segmentation and offer practical insights for future model design.","authors":["Ziquan Liu","Zhewei Zhu","Xuyang Shi"],"published":"2026-09-02T14:38:52Z","updated":"2026-09-02T14:38:52Z","abstract_url":"https://arxiv.org/abs/2609.02663v1","html_url":"https://arxiv.org/html/2609.02663v1","pdf_url":"https://arxiv.org/pdf/2609.02663v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":45094,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：Pretrained vision-language models (VLMs) have shown promising performance in medical image segmentation by incorporating clinical text. However, it remains unclear how much textual information actually contributes to pixel-level predictions. In this work, we...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02644v1","title":"Learning to Attract and Repel: Dual Quality Margin Learning for Face Recognition (DQM-Face)","abstract":"Face recognition in unconstrained environments remains highly challenging due to diverse and extreme variations encountered in real-world scenarios. To mitigate these effects, existing margin-based approaches model sample quality through feature magnitude. However, magnitude-based modeling alone is susceptible to identity-agnostic noise, which can degrade the reliability and discriminative power of learned representations. In this paper, we propose Dual Quality Margin Learning for Face Recognition (DQM-Face), a novel framework that enables refined attraction and repulsion dynamics during representation learning. Our approach unifies conventional magnitude-based quality estimation with a newly introduced semantic quality learning mechanism, realized via squeeze-and-excitation semantic attention. By jointly leveraging magnitude and semantic cues, we construct enhanced quality-aware margins that adaptively strengthen intra-class compactness through improved attraction during learning. To further enhance inter-class discrimination, we introduce a repulsion margin formulation that explicitly enlarges inter-class separation. The unified integration of semantic quality modeling with dual attraction-repulsion margin optimization results in a more structured and discriminative feature geometry. Extensive experiments on multiple challenging benchmarks demonstrate that DQM-Face consistently outperforms state-of-the-art face recognition methods. Moreover, we show that the quality learned for margin optimization is highly effective for face image quality assessment within the proposed framework, demonstrating that the learned quality signal is intrinsically aligned with the recognition objective. The code is publicly available: https://github.com/RAIB-group/DQM-Face","authors":["El Ouanas Belabbaci","Bhavesh Wani","Philipp Terhörst"],"published":"2026-09-02T14:19:43Z","updated":"2026-09-02T14:19:43Z","abstract_url":"https://arxiv.org/abs/2609.02644v1","html_url":"https://arxiv.org/html/2609.02644v1","pdf_url":"https://arxiv.org/pdf/2609.02644v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":56398,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Face recognition in unconstrained environments remains highly challenging due to diverse and extreme variations encountered in real-world scenarios. To mitigate these effects, existing margin-based approaches model sample quality through feature magnitude. Ho...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02616v1","title":"AffectDelta: Beyond Emotion Labels for Image Editing","abstract":"Emotion-driven image editing aims to evoke a specified target emotion by modifying emotion-relevant visual cues in a source image, while preserving the overall composition and semantic-structural coherence of the original scene. Existing scene-level editors typically specify the target with a single emotion category and often learn visual transformations from operation-level text instructions. A category collapses a mixed affective endpoint into one dominant label, while language cannot precisely quantify how coexisting emotions should increase, decrease, or remain stable. We introduce AffectDelta, a source-aware editor that treats editing as a transition between eight-dimensional emotion distributions. A frozen Emotion Distribution Predictor estimates the source state, and the signed source-to-target difference encodes the direction and magnitude of the requested transition. Within AffectDelta, an internal transition encoder and a source-aware diffusion backbone jointly translate this signal into context-dependent semantic and appearance changes. To train this formulation, we construct AffectPair-249K, comprising 248,841 source-target pairs with predicted eight-dimensional distributions and spanning both cross-category and within-category transitions. Experiments against six baselines, combining quantitative evaluation with qualitative comparisons, demonstrate improved affective alignment and content preservation, while ablations validate our design choices. Code and dataset will be made publicly available upon acceptance.","authors":["Xingzu Zhan","Lin Gu","Ruogu Fang"],"published":"2026-09-02T13:56:59Z","updated":"2026-09-02T13:56:59Z","abstract_url":"https://arxiv.org/abs/2609.02616v1","html_url":"https://arxiv.org/html/2609.02616v1","pdf_url":"https://arxiv.org/pdf/2609.02616v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":60907,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Emotion-driven image editing aims to evoke a specified target emotion by modifying emotion-relevant visual cues in a source image, while preserving the overall composition and semantic-structural coherence of the original scene. Existing scene-level editors t...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02573v1","title":"Deeply Interleaved Text-Image Contexts for Multimodal LLMs Assessment","abstract":"Current evaluations and training of multimodal models predominantly focus on multi-image tasks, largely overlooking interleaved text-image scenarios. In such multi-image tasks, text typically serves merely as task instructions, lacking deep semantic interaction with the visual content. In contrast, realworld applications like text-image co-creation, character tracking, and spatial reconstruction require constant interaction between text and images. Consequently, models must possess a deep understanding of these interleaved contexts. To bridge this gap, we introduce a novel benchmark, TIC-Bench (deeply interleaved Text-Image Contexts), designed to evaluate the capability of models to integrate text-image clues and recover the ground truth facts within deeply interleaved contexts. This benchmark encompasses three core domains: Logical, Temporal, and Spatial Association, which are further categorized into eight specific types, comprising a total of 2,280 questions. We evaluated 10 state-of-the-art MLLMs and observed a substantial performance gap compared to human experts, together with persistent difficulties in integrating evidence distributed across interleaved visual and textual inputs. Ultimately, this benchmark provides a valuable analytical tool for assessing and advancing the ability of multimodal models to effectively integrate text and image information in deeply interleaved contexts. TIC-Bench is publicly available at https://huggingface.co/datasets/pino10010/TIC-Bench","authors":["Zihao Wang","Xi Xiang","Yuwen Sun","Yingyu Li","Yabo Zhang","Yihan Zeng","Fan Li","Wangmeng Zuo"],"published":"2026-09-02T13:19:51Z","updated":"2026-09-02T13:19:51Z","abstract_url":"https://arxiv.org/abs/2609.02573v1","html_url":"https://arxiv.org/html/2609.02573v1","pdf_url":"https://arxiv.org/pdf/2609.02573v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":73893,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Current evaluations and training of multimodal models predominantly focus on multi-image tasks, largely overlooking interleaved text-image scenarios. In such multi-image tasks, text typically serves merely as task instructions, lacking deep semantic interacti...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02565v1","title":"MARS: What Retrieval Signals Are Hidden in Multimodal Large Language Models for Text-Video Retrieval?","abstract":"Text-video retrieval requires representations that can distinguish videos with similar scenes, actions, and temporal patterns. Recent multimodal large language models have been adapted as embedding models, but they often represent each input using a single token from the final layer. This can compress diverse video-text cues into a single vector and limit fine-grained retrieval. To address this limitation, we propose MARS, a multi-layer and multi-slot embedding framework for text-video retrieval. MARS constructs multiple adaptive representation slots by combining hidden states from different decoder layers, compares corresponding text and video slots, and aggregates their similarities for retrieval. To better handle confusing candidates, we further introduce a hard-negative-aware slot specialization objective that encourages the slots to capture discriminative matching cues. Experiments on four text-video retrieval benchmarks show that MARS achieves state-of-the-art results in both direct similarity-based retrieval and reranking settings. Ablation studies and analyses demonstrate that multi-layer fusion, multiple slots, and hard-negative-aware slot specialization provide complementary gains. Code is available at https://github.com/sejong-rcv/MARS.","authors":["Uicheol Jung","Juyoung Hong","Geuntaek Lim","Yukyung Choi"],"published":"2026-09-02T13:16:06Z","updated":"2026-09-02T13:16:06Z","abstract_url":"https://arxiv.org/abs/2609.02565v1","html_url":"https://arxiv.org/html/2609.02565v1","pdf_url":"https://arxiv.org/pdf/2609.02565v1.pdf","matched_keywords":["video","retrieval","representation","multimodal"],"source_used":"html","source_text_chars":62583,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, representation, multimodal 相关；摘要显示其主要贡献为：Text-video retrieval requires representations that can distinguish videos with similar scenes, actions, and temporal patterns. Recent multimodal large language models have been adapted as embedding models, but they often represent each input using a single to...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-03T05:25:19+00:00","status":"fallback"},"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02560v1","title":"Stereo 4D Radar for 3D Object Detection: Integrating Geometric Alignment and Absolute Velocity Estimation","abstract":"Four-dimensional (4D) Radar is a powerful sensing modality capable of detecting surrounding three-dimensional (3D) objects under diverse weather conditions and providing Doppler-based motion information. However, raw 4D Radar signals contain significant clutter from road surfaces, guardrails, and surrounding vehicles, along with multipath-induced ghost reflections and the receiver's inherent noise floor. Consequently, preprocessing algorithms designed to remove such invalid measurements often make the Radar data excessively sparse. Moreover, the Doppler measurements provided by 4D Radar describe only the radial component of an object's velocity, limiting their ability to recover the full motion state. In this paper, we introduce a stereo 4D Radar-based 3D object detection framework that exploits the geometric disparity between left and right Radars to estimate the absolute velocity of objects and achieve more robust perception through the fusion of their complementary features. The effectiveness of the proposed framework is validated on our in-house stereo 4D Radar dataset, demonstrating performance gains of 8.82 points in AP 3D and 9.0 points in AP BEV over state-of-the-art mono 4D Radar baselines. These results demonstrate that absolute velocity estimation combined with stereo geometry-aware feature fusion leads to substantial improvements in 3D object detection.","authors":["Seung-Hyun Song","Dong-Hee Paek","Woong-Chan Byun","Seung-Hyun Kong"],"published":"2026-09-02T13:13:08Z","updated":"2026-09-02T13:13:08Z","abstract_url":"https://arxiv.org/abs/2609.02560v1","html_url":"https://arxiv.org/html/2609.02560v1","pdf_url":"https://arxiv.org/pdf/2609.02560v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02556v1","title":"RGB-to-IR image translation for infrared vehicle detection in unseen UAV domains","abstract":"Synthetic training data is crucial for developing vision AI when real-world data is scarce, as in thermal infrared (IR) aerial vehicle detection. While abundant UAV RGB imagery motivates RGB-to-IR translation for data augmentation, unobservable thermal traits (e.g., engine heat) make learning transferable mappings challenging. This work investigates whether modern generative translators can overcome this cross-modal gap to improve infrared vehicle detection on unseen UAV target domains. Translators are trained on paired RGB-IR source datasets and applied to RGB training images from held-out target datasets to generate synthetic IR data. Evaluated methods include supervised GANs, ControlNet-based diffusion models, and foundation-model editing via LoRA. The resulting synthetic IR imagery is used to train RF-DETR vehicle detectors, which are evaluated on unseen IR target test splits across five aerial datasets, with Kust4K and VTUAV serving as target domains. Synthetic IR consistently outperforms RGB and grayscale baselines. Stable Diffusion 3.5 with ControlNet yields the best results, improving mAP from 50.8 to 60.1 on Kust4K and from 25.6 to 38.4 on VTUAV compared to models trained only on source-domain IR data. Increasing output diversity via multiple seeds (+1.1 mAP) and prompt variations (+3.3 mAP) provides additional gains on VTUAV. Although a performance gap to real target IR data remains, generative RGB-to-IR translation effectively mitigates IR data scarcity and improves cross-domain aerial vehicle detection.","authors":["Thijs A. Eker","Ella P. Fokkinga","Jan Erik van Woerden","Elfi I. S. Hofmeijer","Sebastiaan P. Snel","Klamer Schutte","Friso G. Heslinga"],"published":"2026-09-02T13:06:58Z","updated":"2026-09-02T13:06:58Z","abstract_url":"https://arxiv.org/abs/2609.02556v1","html_url":"https://arxiv.org/html/2609.02556v1","pdf_url":"https://arxiv.org/pdf/2609.02556v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02531v1","title":"Spatially Aware World Action Model via Geometric Latent Diffusion","abstract":"World Action Models (WAMs) leverage the capabilities of large-scale pretrained video diffusion models to jointly predict future observations and actions, inheriting rich visual and physical priors from internet-scale video. This has made them a promising paradigm for robot policy learning, yet the prevailing models operate exclusively on RGB observations and do not leverage 3D information. To bridge this gap, we introduce a Spatially Aware World Action Model (SA-WAM), which repurposes a pretrained video model for joint action, RGB, and depth prediction, enabling 3D-aware world modeling and action prediction within a single diffusion backbone. We use a nonlinear encoding that maps the unbounded depth signal into the bounded input domain expected by the frozen VAE tokenizer. This allows us to reuse the tokenizer without 3D-specific fine-tuning, incorporating geometric information without sacrificing the pretrained priors. SA-WAM achieves state-of-the-art results on the RoboCasa and LIBERO-Plus benchmarks, while simultaneously improving future-state predictions. Furthermore, SA-WAM outperforms strong baselines in real-world evaluation using a UR5 robotic arm, with strong gains in randomized environments. We analyze the correlation between world model prediction quality and rollout success, providing insights into WAM performance and avenues for its improvement.","authors":["Javier Alejandro Lopetegui Gonzalez","Paul Pacaud","Cordelia Schmid"],"published":"2026-09-02T12:42:37Z","updated":"2026-09-02T12:42:37Z","abstract_url":"https://arxiv.org/abs/2609.02531v1","html_url":"https://arxiv.org/html/2609.02531v1","pdf_url":"https://arxiv.org/pdf/2609.02531v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02529v1","title":"Fine-Grained Anomaly Perception in Wild UGC-Enhanced Images: A Comprehensive Dataset and Difference-Fusion Framework","abstract":"Image enhancement and restoration have become standard back-end operations on short-video and social media platforms to boost UGC visual experience. Yet these processes inevitably introduce visual anomalies--especially in faces, texts, and textures--that directly undermine perceptual fidelity and viewer trust. While existing IQA methods perform well on classic distortions, they target holistic quality assessment and fail to capture the specific, localized anomalies caused by enhancement algorithms in real-world UGC. To bridge this gap, we formally define a new task-quality Anomaly Perception for UGC image Enhancement (UEAP), and contribute the first UEAP benchmark dataset, named UEAP-4k, curated from the real business scenarios. It provides fine-grained annotations for anomaly categories, localization and severity levels. Furthermore, we propose a Difference-Fusion Anomaly Perception Method (DFAP-UGC) for wild UGC-enhanced images, which leverages explicit problem-reference difference fusion with dense spatial querying, regional verification, and quality-aware ranking, enabling robust anomaly identification in challenging scenarios. To handle the inherent coupling of subtasks in this new task, we propose a Locality-Aware Dynamic Task Prioritization (LADTP) training strategy that enables effective end-to-end learning and eliminates multi-stage overhead. Extensive experiments show that our method outperforms baselines adapted from classical approaches for this task, validating the value of this dataset and the superior of DFAP-UGC for robust UGC-enhanced image anomaly perception. Code and data will be public.","authors":["Yan Zhong","Gefei Chen","Qiufang Ma","Zhen Wang","Zhiwei Fan","Lei Shi","Tingting Jiang"],"published":"2026-09-02T12:37:56Z","updated":"2026-09-02T12:37:56Z","abstract_url":"https://arxiv.org/abs/2609.02529v1","html_url":"https://arxiv.org/html/2609.02529v1","pdf_url":"https://arxiv.org/pdf/2609.02529v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02528v1","title":"Doppio: A Dataset for Contactless Weight Estimation of Falling Particles","abstract":"Measuring the mass of powder, including falling particles, is a common task in industrial applications. While scales are effective for static measurements, many applications require contactless sensing, where existing solutions are often costly, application-specific, and technically complex. In this work, we investigate computer vision as a practical alternative for contactless mass estimation. As an accessible real-world case study, we focus on coffee grinding and introduce \\emph{Doppio}, a novel video dataset capturing videos of falling ground coffee, paired with precise, per-frame ground-truth weight measurements. To demonstrate contactless measuring, we evaluate deep learning-based approaches ranging from purely spatial feed-forward networks to recurrent spatio-temporal models. These models are analyzed with respect to their predictive accuracy and computational trade-offs. We demonstrate that deep learning-based computer vision models accurately estimate the cumulative weight of falling particles, establishing a solid foundation for future vision-based contactless measurement solutions.","authors":["Simon Kiefhaber","Jan-Martin O. Steitz","Julia Grabinski","Christoph Reich","Paul Wagner","Max Zimmermann","Simone Schaub-Meyer","Stefan Roth"],"published":"2026-09-02T12:35:33Z","updated":"2026-09-02T12:35:33Z","abstract_url":"https://arxiv.org/abs/2609.02528v1","html_url":"https://arxiv.org/html/2609.02528v1","pdf_url":"https://arxiv.org/pdf/2609.02528v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02512v1","title":"Beauty is in the AI of the beholder: MLLMs systematically overrate facial attractiveness","abstract":"Beauty assessments from Multimodal Large Language Models (MLLMs) are increasingly popular amongst users, companies, and aestheticians. This raises the question of whether these AI models can accurately reflect human judgments of attractiveness. In a pre- registered exploratory study, we compared the attractiveness ratings of 2,513 human participants to four widely used commercial AI models: Claude, Gemini, GPT, and Grok. Results showed that MLLMs systematically rate faces more favourably and within a narrower range than humans and, at the time of study, do not reproduce human ratings in absolute terms. However, MLLMs exhibit strong correlations with human attractiveness judgments, accurately tracking the rank-ordering of faces. MLLMs may judge faces by different cues than humans; only face age was a predictor of facial attractiveness in both humans and MLLMs, with inconsistent patterns across models for ethnicity and gender. AI models strongly agree with one another, except for Grok, which also showed the lowest agreement with humans. Our findings suggest that while they may be able to approximate rank-orderings of human attractiveness, current off-the-shelf commercial MLLMs systematically overrate the beauty of human faces.","authors":["Santiago Grandas","Juan Sebastian Cely-Acosta","Mohit Mendiratta","Shafee Hassan","Macken Murphy"],"published":"2026-09-02T12:16:22Z","updated":"2026-09-02T12:16:22Z","abstract_url":"https://arxiv.org/abs/2609.02512v1","html_url":"https://arxiv.org/html/2609.02512v1","pdf_url":"https://arxiv.org/pdf/2609.02512v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02486v1","title":"ViSAR: Training-Free Adaptive-$k$ Retrieval for Visual Document Question Answering","abstract":"Document Visual Question Answering (DocVQA) often leverages Retrieval-Augmented Generation (RAG), where late-interaction encoders are commonly used to identify document pages relevant to a user query, before answer generation by a Large Vision-Language Model (LVLM). Existing approaches typically retrieve a fixed top-$k$ number of pages regardless of query complexity, which increases LVLM latency and may degrade answer accuracy. We introduce ViSAR (Visual Semantic Activation Retrieval), a training-free adaptive-$k$ retrieval method for late-interaction visual document retrieval. ViSAR operates directly in the embedding space to construct a query-conditioned page-level similarity matrix that highlights query-relevant semantics and dynamically determines the number of pages to retrieve. Across multiple encoders and LVLMs, ViSAR retrieves compact, query-adapted page sets that reduce RAG latency by up to 58.7\\%, while maintaining or improving answer accuracy compared with fixed top-$k$ and adaptive retrieval heuristics. Furthermore, we show that the similarity matrix structure correlates with answer accuracy, suggesting future directions for retrieval quality-aware document understanding.","authors":["Adrien Mialland","Marc Plantevit","Julien Gallois","Céline Robardet"],"published":"2026-09-02T11:54:58Z","updated":"2026-09-02T11:54:58Z","abstract_url":"https://arxiv.org/abs/2609.02486v1","html_url":"https://arxiv.org/html/2609.02486v1","pdf_url":"https://arxiv.org/pdf/2609.02486v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02476v1","title":"UnCapsTSR: An Unsupervised Transformer-based Image Super-Resolution Approach for Capsule Endoscopy Images","abstract":"Wireless Capsule Endoscopy (WCE) captures and streams video while passing through a patient's Gastrointestinal (GI) tract and is used to examine its irregularities. Although advantageous over conventional endoscopy, WCE suffers from limitations related to capsule size and wireless transmission, resulting in images with coarser resolution. This work presents UnCapsTSR, an unsupervised transformer-based Generative Adversarial Network (GAN) framework for improving the spatial resolution of Low-Resolution (LR) WCE images. The proposed method accomplishes SR without explicit degradation estimation of real-world LR data and eliminates the need for true LR-HR pairs. UnCapsTSR employs a Bilateral Total Variation (BTV) loss to ensure spatial continuity in SR images. A newly curated dataset from the Kvasir Capsule dataset is also presented for training WCE SR models. Generalizability is validated on KID and GIANA datasets that are not used during training. A new non-reference metric, Endoscopy Quality Metric (EndoQM), is introduced for quantitative evaluation of domain-specific WCE data. Experiments demonstrate consistent improvement over state-of-the-art unsupervised SR approaches using NIQE, BRISQUE, PIQE, and EndoQM. Statistical evaluation shows 40 to 80 percent improvement in EndoQM from LR to SR across the evaluated datasets.","authors":["Anjali Sarvaiya","Shubh Kawa","Lalit Agrawal","Jagrit Joshi","Kishor Upla","Kiran Raja"],"published":"2026-09-02T11:48:17Z","updated":"2026-09-02T11:48:17Z","abstract_url":"https://arxiv.org/abs/2609.02476v1","html_url":"https://arxiv.org/html/2609.02476v1","pdf_url":"https://arxiv.org/pdf/2609.02476v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02471v1","title":"Learning to Track from Privileged Target Appearances","abstract":"Target templates define what a visual tracker searches for, yet the templates available at inference trade off localization certainty with appearance freshness: the initial ground-truth template is exact but becomes stale, whereas recent templates better reflect the current appearance but are cropped from uncertain predictions. We quantify this bottleneck with a non-deployable oracle that supplies an exact current-frame target crop, improving AUC on LaSOT by 15.2 percentage points. This gap reveals a training-only opportunity: frame-level ground truths provide exact current- and future-frame target crops, although such crops are unavailable at deployment. We introduce Privileged Appearance Transfer for Tracking (PATT), a teacher-student training framework that transfers these privileged appearances to a deployable tracker through multi-level representation prediction. The privileged teacher observes exact target crops from past, current, and future frames, whereas the student receives only past-frame templates and learns to predict the teacher's search representations. To avoid transferring unreliable teacher signals, PATT weights this transfer by the teacher's relative localization advantage over the student and its absolute localization accuracy. After training, the teacher, latent predictor, reliability weights, and privileged crops are removed, leaving standard student-only inference. Across seven benchmarks at two model scales, PATT achieves consistent gains under both long- and short-term tracking protocols.","authors":["Xin Chen","Jiao Xu","Dong Wang","Huchuan Lu","Kede Ma"],"published":"2026-09-02T11:43:43Z","updated":"2026-09-02T11:43:43Z","abstract_url":"https://arxiv.org/abs/2609.02471v1","html_url":"https://arxiv.org/html/2609.02471v1","pdf_url":"https://arxiv.org/pdf/2609.02471v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02462v1","title":"VIPS: Vehicle-Infrastructure Cooperative Planning Benchmark via Pseudo-Simulation","abstract":"End-to-end autonomous driving in urban environments requires robust decision-making under partial observability and complex multi-agent interactions. Severe occlusions and dense traffic at intersections limit the perception capability of single-agent systems, motivating recent efforts on Vehicle-to-Infrastructure (V2I) cooperation for perception and planning. However, existing evaluation protocols face a fundamental trade-off: open-loop evaluation fails to capture error accumulation and recovery from deviations, while closed-loop evaluation is costly, difficult to scale, and often relies on simulated environments that may suffer from domain gaps. To bridge this gap, we propose VIPS, a benchmark for cooperative autonomous driving in V2I settings based on pseudo-simulation. VIPS extends pseudo-simulation by integrating vehicle and infrastructure observations. This enables scalable yet realistic evaluation of robustness and error propagation without full simulation. We further present CoS-V2X, a cooperative planning framework based on sparse representations. CoS-V2X models vehicle-infrastructure interactions using compact features for efficient communication and robust decision-making under heterogeneous observations. Code and dataset are available at https://vips2026.github.io.","authors":["Hoonhee Cho","Jae-Young Kang","Giwon Lee","Hyemin Yang","Heejun Park","Kuk-Jin Yoon"],"published":"2026-09-02T11:32:52Z","updated":"2026-09-02T11:32:52Z","abstract_url":"https://arxiv.org/abs/2609.02462v1","html_url":"https://arxiv.org/html/2609.02462v1","pdf_url":"https://arxiv.org/pdf/2609.02462v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02390v1","title":"Seeing Beyond the Lesion: Disease Recognition from Reactive CNS Tissue","abstract":"Sampling error yields exclusively reactive, non-lesional brain parenchyma in a significant proportion of intracranial biopsies, leaving the underlying disease undiagnosed. We benchmark four pathology foundation models (UNI2-h, Virchow2, Prov-GigaPath, H-optimus-0) as frozen patch encoders within a shared attention-based multiple-instance learning framework using 245 whole-slide images from 186 patients with confirmed downstream diagnoses. We first show that coarse disease-category prediction can be reproduced largely from slide size alone. After restricting classification to three finer diagnostic distinctions within common tissue categories, this confound no longer explains performance, yet disease labels remain predictable above chance under permutation testing (p $\\le 10^{-4}$ throughout). Surprisingly, performance is statistically indistinguishable across all foundation-model encoders, suggesting that recovering these weak morphological signatures is not limited by current patch representations. Signed instance-contribution maps and expert review further test whether predictive evidence localizes to reactive parenchyma rather than sampling-induced bias like blood introduced during tissue sampling. These results position acquisition-shortcut auditing via a provenance-only baseline as a necessary control in computational-pathology benchmarks, and show, once that confound is removed, that weakly supervised models still recover disease signal from tissue conventionally regarded as non-diagnostic.","authors":["Jan Schnorrenberg","Jan Ernsting","Enrico Küllenberg","Tim Hahn","Benjamin Risse","Christian Thomas"],"published":"2026-09-02T10:02:43Z","updated":"2026-09-02T10:02:43Z","abstract_url":"https://arxiv.org/abs/2609.02390v1","html_url":"https://arxiv.org/html/2609.02390v1","pdf_url":"https://arxiv.org/pdf/2609.02390v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02377v1","title":"ProSR: Semantic-Prototype-Guided Discrete Modeling for Physically Consistent SAR Super-Resolution","abstract":"High-resolution Synthetic Aperture Radar (SAR) imagery is critical for precision analysis such as automatic target recognition, yet its acquisition is costly. Although generative image super-resolution (ISR) models offer a promising alternative, current smooth-approximation based diffusion frameworks often struggle to preserve the coherent scattering statistics, causing stochastic structural distortions that are less consistent with real SAR physics. To address this, we propose Semantic Prototype-Guided Super-Resolution (ProSR), reformulating SAR ISR as a semantically-guided discrete token prediction task within a quantized latent space. By mapping signal features to discrete scattering primitives, ProSR preserves the impulsive nature of SAR without over-smoothing. Furthermore, we integrate a Self-Supervised Learning backbone into SAR ISR to extract label-free semantic priors, overcoming label scarcity. Guided by these priors, we introduce Semantic-Aligned Detail Encoding to decouple high-frequency signals into discrete scattering primitives. In parallel, the Semantic Prototype Map Generator explicitly constructs semantic prototype maps, allowing Prototype-Map-Guided Attention to route the information flows within identical categories and mitigate inter-class interference. To validate our approach, we present a large-scale 0.25m resolution benchmark from the Umbra Open Dataset. Experimental results show ProSR achieves superior visual quality while preserving essential scattering characteristics required for practical SAR applications.","authors":["Byoungwoo Kim","Munchurl Kim"],"published":"2026-09-02T09:50:06Z","updated":"2026-09-02T09:50:06Z","abstract_url":"https://arxiv.org/abs/2609.02377v1","html_url":"https://arxiv.org/html/2609.02377v1","pdf_url":"https://arxiv.org/pdf/2609.02377v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02369v1","title":"Information Density Imbalance in Visual Object Detection","abstract":"In object detection, the number of instances is typically used to determine whether a dataset exhibits a long-tailed distribution, implicitly assuming that the model will perform poorly on categories with fewer instances. This assumption has led to extensive research on category bias in datasets with imbalanced instance numbers. However, even in datasets where instance numbers are relatively balanced, models still exhibit category bias, indicating that instance count alone cannot explain this phenomenon. In this work, we first introduce the concept and measurement of information density. We then observe a significant negative correlation between a category's information density and its accuracy, and we investigate how the training process impacts this relationship. Empirical studies suggest that information density imbalance may be a potential source of category bias. To preliminarily validate the potential of information density, we made simple improvements to three advanced object detection loss functions using this concept. Experiments on the Pascal VOC, COCO-LT, and LVIS datasets demonstrate that information density can significantly reduce model bias while effectively enhancing the overall performance of existing loss functions. This study provides a new perspective for understanding the generalized bias phenomenon in object detection models and offers new tools for designing fairer loss functions and training strategies.","authors":["Ziwei Zhao","Yanxi Lu","Yuwei Hu","Shiyang Su","Mingxuan Wang","Chenyue Zhou","Jiayi Chen","Hehan Li","Xiaoshuai Hao","Andi Zhang","Yanbiao Ma"],"published":"2026-09-02T09:40:49Z","updated":"2026-09-02T09:40:49Z","abstract_url":"https://arxiv.org/abs/2609.02369v1","html_url":"https://arxiv.org/html/2609.02369v1","pdf_url":"https://arxiv.org/pdf/2609.02369v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02367v1","title":"The Missing Temporal Link: Temporal Context Routing for Script-Driven Audio-Video Generation","abstract":"Joint audio-video generation models have made substantial progress in visual quality and audio-visual synchronization. However, they still provide limited control over when shot transitions occur and dialogue is spoken. This limitation constrains their application in script-driven content creation, where timing errors can undermine narrative coherence and the viewing experience. Current joint generators align video and audio representations on a shared temporal axis, yet the precise timing of shots and dialogue specified in a structured prompt is encoded only in the prompt's text representation and remains unaligned with the temporal coordinates of either modality. Consequently, video and audio may remain synchronized with each other while both fail to follow the script timeline. This mismatch motivates us to extend temporal alignment beyond video and audio to include the structured script. We therefore introduce Temporal Context Routing (TCR), which maps the script timing onto the shared temporal axis of video and audio generation and routes each prompt's guidance to the corresponding positions in both modalities. Compared with the baseline on 200 test scripts, TCR reduces Shot Boundary MAE by 96%, from 1.11 s to 0.042 s, and raises Dialogue Acc@0.5 s from 28.3% to 84.1%. TCR achieves these improvements while maintaining visual quality and audio-visual synchronization comparable to those of the baselines. A user study further shows that participants prefer TCR on all five evaluated dimensions.","authors":["Yichen Liu","Quanwei Zhang","Haozhe Wang","Donghao Zhou","Xiaojie Li","Yang Shi","Jiaming Liu","Ruihua Huang","Yingtian Zou","Daquan Zhou"],"published":"2026-09-02T09:39:50Z","updated":"2026-09-02T09:39:50Z","abstract_url":"https://arxiv.org/abs/2609.02367v1","html_url":"https://arxiv.org/html/2609.02367v1","pdf_url":"https://arxiv.org/pdf/2609.02367v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02359v1","title":"TempoGround: State-Aware Streaming Visual Grounding with Vision-Language Models","abstract":"Visual grounding maps language referents to spatial targets and is central to open-vocabulary perception with vision-language models. Existing methods have made substantial progress on single-frame and video-based visual grounding, yet under streaming inputs they still suffer from identity drift, cross-frame inconsistency, and fragile localization under partial occlusion. To address these issues, we present TempoGround, a VLM-native framework that detects cross-frame object correspondence and explicitly models object presence states, thereby enabling accurate and consistent visual grounding under streaming inputs. The key is a curriculum prediction mechanism guided by state-aware cross-frame correspondence: TempoGround resolves 2D instance association, predicts whether each object newly enters, continues in, or leaves the view, decodes the 2D box, and then lifts it to a camera-frame 3D box. As token-level supervision alone cannot capture the geometric objectives of streaming grounding, we further introduce Streaming Grounding Reinforcement (SGR), which optimizes TempoGround with verifiable Grounding, Identity, and Consistency rewards, jointly reinforcing persistent localization and temporally consistent predictions. We carefully design a three-stage training strategy and train TempoGround on large-scale data. We evaluate visual grounding under causally streaming inputs on multiple challenging benchmarks: TempoGround improves F1_2D@0.5 and F1_2D@0.95 by 4.4 and 0.5 on average, and F1_3D@0.25 and AP_3D by 6.2 and 7.5, respectively. These results demonstrate that TempoGround provides a practical foundation for visual grounding under streaming inputs.","authors":["Leqian Ding","Junning Qiu","Manwen Yang","Yu Guo","Fei Wang"],"published":"2026-09-02T09:30:08Z","updated":"2026-09-02T09:30:08Z","abstract_url":"https://arxiv.org/abs/2609.02359v1","html_url":"https://arxiv.org/html/2609.02359v1","pdf_url":"https://arxiv.org/pdf/2609.02359v1.pdf","matched_keywords":["video","3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02350v1","title":"LookStep: Efficient Vision-Language Navigation with Linguistic Foresight and Event Driven Memory","abstract":"Vision-Language Navigation (VLN) requires an embodied agent to follow natural-language instructions in unseen environments. Recent progress has been largely driven by Multimodal Large Language Models (MLLMs). Existing methods follow a next-step action prediction paradigm, supervising only the expert action, which requires a high quantity of data for training. They also rely on cognitive maps, accumulated historical frames, or external 3D tools to maintain states, leading to high computational and memory overhead. To realize resource efficiency VLN, we propose LookStep, a unified end-to-end framework that combines Language Centric Future State Modeling and Event Driven Rolling Memory that uses language labels to generate coarse-grained navigation progress and future states for each candidate action, while autonomously deciding whether to write each observation into a bounded rolling memory with a semantic role. We validate LookStep empirically. On VLN-CE tasks, LookStep outperforms existing methods under the same training settings, achieving a 49.7\\% success rate on R2R-CE Val-Unseen with better memory efficiency and less data usage. Code and model is available at https://github.com/kunyang-YU/LookStep.","authors":["Kun-Yang Yu","Yingzhe Li","Hongyu Xu","Shi-Yu Tian","Zhi Zhou","Yang Chen","Ming Yang","Sheng Wang","Qing Yu","Lan-Zhe Guo","Yu-Feng Li"],"published":"2026-09-02T09:24:08Z","updated":"2026-09-02T09:24:08Z","abstract_url":"https://arxiv.org/abs/2609.02350v1","html_url":"https://arxiv.org/html/2609.02350v1","pdf_url":"https://arxiv.org/pdf/2609.02350v1.pdf","matched_keywords":["3d","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02349v1","title":"GlyphAnchor: Enhancing Visual Text Rendering via Position-Anchored Glyph Priors","abstract":"Rendering accurate text remains difficult for image generation and editing models, especially when the target contains long, complex, and densely arranged text or rare characters. Existing approaches either improve native text rendering through stronger backbones and data-centric training without explicit glyph priors, or incorporate glyph priors through specialized designs that remain insufficiently accurate and robust under challenging scenarios. We introduce GlyphAnchor, a novel text-rendering enhancement method for both text-to-image and image-editing diffusion transformer models. GlyphAnchor enhances the backbone with lightweight glyph patch conditions whose positions are anchored to the target image through the model's native positional encoding. We train this capability with staged supervised finetuning and further refine it with text-aware post-training to improve robustness. We also introduce InfoTextBench, a benchmark for evaluating text-rich visual text rendering in both generation and editing settings. Experiments across multiple backbones and benchmarks, including long, complex, and densely arranged text and rare character scenarios, show that GlyphAnchor consistently improves text fidelity while preserving overall image quality.","authors":["Qiang Xiang","Shuang Sun","Binglei Li","Yibo Chen","Xu Tang","Yao Hu","Junping Zhang"],"published":"2026-09-02T09:23:23Z","updated":"2026-09-02T09:23:23Z","abstract_url":"https://arxiv.org/abs/2609.02349v1","html_url":"https://arxiv.org/html/2609.02349v1","pdf_url":"https://arxiv.org/pdf/2609.02349v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02348v1","title":"Structured-Prior-Guided Diffusion Inpainting with Physical Consistency for Traffic Sign Augmentation","abstract":"Traffic sign detection faces a long-tailed data distribution. Many rare signs matter as much as common ones from a regulatory standpoint, yet they have very few samples. Generative data augmentation is one way out. General-purpose inpainting models, however, distort digits, deform geometry and perspective, and shift colours when applied directly to sign regions. We trace this to a single gap: the conditioning signal is too abstract for the physical composition of a sign. We propose a structured-prior-guided diffusion inpainting framework with physical consistency. It injects the semantic, appearance and geometric priors of a sign through three orthogonal pathways: a JSON-formatted text prompt, a front-view vector template rendered with measured dominant colours (via IP-Adapter), and an affine-aligned vector template (via ControlNet). Two physical consistency losses constrain colour with a CIELAB chromaticity $L_1$ term and edge structure with a Sobel gradient term. We train by self-supervised reconstruction on a large set of images collected in-house at AMAP, then evaluate zero-shot on the public TT100K-2021 dataset, a different source. Our method uses a Stable Diffusion 1.5 backbone of about 1.4B parameters. It beats seven representative competitors on every metric of reconstruction fidelity, physical consistency and semantic controllability. Its OCR exact-match rate reaches 91.1\\%, against 44.2\\% for the 12B industrial model FLUX.1 Fill [dev], and it needs only $1/14$ of that model's inference time. Leave-one-out ablations confirm that each of the three prior pathways and both loss terms contribute on their own. In downstream detection, the synthetic data raises the group-pooled AP50 of rare classes by $1.23\\times$ to $7.40\\times$ over a real-data-only baseline. Code and pre-trained models are available at https://github.com/52hz-whale/TrafficSignInpaint.","authors":["Luo Li","Chongchong Huang","Jun Jia","Qiang Gao","Xinlong Liu","Gui Yang","Liang Cao"],"published":"2026-09-02T09:22:23Z","updated":"2026-09-02T09:22:23Z","abstract_url":"https://arxiv.org/abs/2609.02348v1","html_url":"https://arxiv.org/html/2609.02348v1","pdf_url":"https://arxiv.org/pdf/2609.02348v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02341v1","title":"Towards Zero-Shot Transfer Across Embodiments For Driving VLAs","abstract":"Vision-Language-Action models (VLAs) have shown strong potential in autonomous driving by leveraging multimodal pretraining for instruction following, visual reasoning, and scene-level generalization. In robotic manipulation, scaling VLA fine-tuning across multiple robot setups--especially when unifying representations across embodiments--has been shown to improve in-dataset performance and cross-embodiment generalization; in autonomous driving, however, VLAs remain largely trained on individual datasets and are rarely evaluated for zero-shot transfer to unseen datasets and camera rigs; furthermore naively adding more datasets to the training data does not necessarily lead to better performance within seen embodiments. To address these problems, we study multi-dataset training for the driving task and BEV-Forcing, an auxiliary objective that transfers ground-plane object-layout information from a specialized Bird's-Eye-View model into the VLA backbone. By encouraging the model to represent object position through a shared BEV spatial interface, we show that an auxiliary task such as BEV-Forcing can improve both in-distribution and out-of-distribution performance when training on a small number of camera rigs. As the number of training embodiments increases, however, the benefits of the auxiliary task are reduced; we present this as evidence that new techniques in the literature may see their benefits diminish when simply scaling up training diversity, which motivates presenting results taking into account data scaling.","authors":["Caio Azevedo","Stefano Sabatini","Sascha Hornauer","Fabien Moutarde"],"published":"2026-09-02T09:17:54Z","updated":"2026-09-02T09:17:54Z","abstract_url":"https://arxiv.org/abs/2609.02341v1","html_url":"https://arxiv.org/html/2609.02341v1","pdf_url":"https://arxiv.org/pdf/2609.02341v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02333v1","title":"ORB-SVM : An Innovative Hybrid Framework for Efficient Brain Tumor Detection from MRI Scans","abstract":"Brain cancer remains one of the most significant challenges in modern medicine, where the accuracy of early stage diagnosis is a decisive factor in patient survival and treatment efficacy. Although Magnetic Resonance Imaging (MRI) is the established gold standard for visualizing neurological structures, the interpretation of these high dimensional scans is often complicated by subjective variability among practitioners and the inherent noise present in complex medical images. While contemporary approaches frequently rely on high parameter deep learning architectures, such models often involve significant computational costs and require extensive data for effective training. This study introduces a hybrid framework that utilizes the Oriented FAST and Rotated BRIEF (ORB) algorithm for precise feature extraction and a Support Vector Machine (SVM) for classification [1], [2]. The proposed approach achieves a sub- stantial data reduction of approximately 99.5%, which effectively minimizes the influence of non informative background data while preserving critical diagnostic patterns essential for tumor identification. By balancing feature sparsity with a robust kernel based classifier, this methodology addresses the limitations of over parameterized systems while maintaining high diagnostic integrity. Experimental evaluations conducted on the Br35H dataset demonstrate that the framework attains a classification accuracy of 97.5%. The findings suggest that the integration of localized feature representation and optimized classification provides a reliable and resource efficient alternative for medical image analysis, offering a structured solution that maintains per- formance without the need for extensive computational overhead.","authors":["Amirhosein Azarpour"],"published":"2026-09-02T09:09:14Z","updated":"2026-09-02T09:09:14Z","abstract_url":"https://arxiv.org/abs/2609.02333v1","html_url":"https://arxiv.org/html/2609.02333v1","pdf_url":"https://arxiv.org/pdf/2609.02333v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02318v1","title":"YesTrack: Referring Multi-Object Tracking via MLLM-based Yes/No Verification","abstract":"Referring multi-object tracking (RMOT) aims to track every instance in a video that matches a given language expression. Despite the recent integration of multimodal large language models (MLLMs) to enhance generalization, existing methods predominantly relegate them to the role of caption generators, necessitating external modules for final decision-making. This paradigm not only introduces extra latency but also severely underutilizes the inherent vision-language alignment capabilities of MLLMs. To address these limitations, we propose YesTrack, a novel two-stage RMOT method that reformulates referring as a discriminative task, directly leveraging MLLMs for Yes/No verification without explicit text generation. To further enhance the reliability and efficiency of this MLLM-based verification, we introduce two lightweight temporal consistency constraints: Temporal Confidence Prior (TCP) and Temporal Reference Propagation (TRP). We further validate the generality of this discriminative paradigm by proposing YesTrack-MOT, a straightforward yet highly effective instantiation for generic multi-object tracking (MOT). Experiments on Refer-KITTI and Refer-KITTI-V2 show that YesTrack significantly outperforms existing state-of-the-art methods while maintaining high efficiency, even when implemented with the smallest variant of Qwen3-VL. Code is released at https://github.com/ggbondrighthere24/YesTrack.","authors":["Quansheng Hu","Qin Sun","Qiansen Dai","Jin Ding","Wan Zhang","Xue Zhou","Jianxiao Zou"],"published":"2026-09-02T09:04:43Z","updated":"2026-09-02T09:04:43Z","abstract_url":"https://arxiv.org/abs/2609.02318v1","html_url":"https://arxiv.org/html/2609.02318v1","pdf_url":"https://arxiv.org/pdf/2609.02318v1.pdf","matched_keywords":["video","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02299v1","title":"Domain shift-robust object detection with GenAI image editing","abstract":"Object detectors often degrade under domain shifts such as changes in lighting, weather, or occlusion. These shifts alter object appearance and expose a reliance on visual shortcuts learned from the training distribution that do not generalize across domains. Acquiring sufficient real-world samples to capture such domain variation is particularly difficult in specialized, low-data settings. Recent advances in diffusion-based generative image editing have shown promise for improving the in-domain performance of object detectors through synthetic data augmentation. However, their potential to improve out-of-domain robustness remains largely unexplored. We hypothesize that generative image editing can simulate a controlled domain shift in training data, effectively bridging the gap between source and target domains. To test this, we studied camouflaged military vehicle detection as a challenging domain shift scenario. Detectors trained on uncamouflaged data demonstrate substantial degradation on real test imagery containing foliage, netting, and multi-spectral camouflage across 15 vehicle classes in close-up, ground-level imagery. We used two diffusion-based editing models, Qwen Image Edit 2509 and Flux.2 Dev, to synthetically add camouflage to the training data, alongside a LoRA fine-tuned version of Qwen. A non-generative black-bar occlusion baseline served as a lower bound on augmentation quality. Using a GroundingDINO detector trained on real and synthetic data, generative camouflage augmentation yielded substantial mAP improvements for foliage (+20.1) and netting (+14.4) camouflage. Generating multi-spectral camouflage proved more challenging, but LoRA fine-tuning improved performance by 4.4 mAP over the uncamouflaged baseline.","authors":["Isabel D. Stein","Thijs A. Eker","Sebastiaan P. Snel","Ella P. Fokkinga","Klamer Schutte","Luca Ambrogioni","Friso G. Heslinga"],"published":"2026-09-02T08:44:27Z","updated":"2026-09-02T08:44:27Z","abstract_url":"https://arxiv.org/abs/2609.02299v1","html_url":"https://arxiv.org/html/2609.02299v1","pdf_url":"https://arxiv.org/pdf/2609.02299v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02291v1","title":"VoRTeC: Taming Foundation Flow for One-step Real time Video Compression","abstract":"Ultra-low bitrate video compression still faces critical challenges: traditional neural video compression inevitably introduces blurring artifacts, while diffusion-based generative video compression suffers from excessive decoding latency and poor temporal consistency. To address these issues, we propose $\\mathtt{VoRTeC}$, a Video Compression framework built upon a foundational flow model (Wan2.1). By compactly encoding latent video representations, predicting the positions of compressed representations along flow trajectories, and integrating multi-scale priors, $\\mathtt{VoRTeC}$ enables the compressor to harness generative video flow priors effectively. Without accessing the parameters or gradients of flow matching networks, our framework achieves one-step decoding and reconstructions with high perceptual fidelity. Meanwhile, we maintain consistency across frame groups via tail-frame reuse and prior caching. Extensive experiments demonstrate that our method reduces bit consumption by 58\\% compared to prior diffusion-based approaches, with decoding speed boosted by 3 to 197 times: $\\mathtt{VoRTeC}$ achieves a decoding speed of 13 FPS at 720p and 32 FPS at 480p.","authors":["Yichong Xia","Qinhong Wu","Qinhong Wu","Jinpeng Wang","Zeyuan Chen","Haoqian Wang"],"published":"2026-09-02T08:39:23Z","updated":"2026-09-02T08:39:23Z","abstract_url":"https://arxiv.org/abs/2609.02291v1","html_url":"https://arxiv.org/html/2609.02291v1","pdf_url":"https://arxiv.org/pdf/2609.02291v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02289v1","title":"If It Moves, Radar Knows: A Physics-Aware Radar Transformer for Class-Agnostic Moving-Object Detection","abstract":"Detectors trained on closed-set annotations can miss rare moving objects outside the training taxonomy. Automotive radar provides category-independent Doppler motion cues and is less affected by adverse illumination and weather, but sparse, noisy returns hinder class-aware 3D box detection. Surface location and velocity remain useful for motion reasoning and collision avoidance when full box geometry is difficult to recover. We present the Physics-Aware Radar Transformer (PART), a fully sparse radar-only detector that predicts existence confidence, a representative surface point, and 2D ground-plane velocity for each moving-object hypothesis. Doppler-Aware Query Initialization (DAQI) replaces scene-independent learned queries with input-dependent proposals by clustering radar returns in position and velocity, easing query-object assignment in sparse scenes. Physics-Guided Cross-Attention (PGCA) incorporates radial-Doppler consistency and radar cross section (RCS) into query-point association. Uncertainty-aware supervision randomly masks ground-truth objects and assigns soft existence targets to ambiguous radar-supported queries, reducing reliance on exhaustive annotations. With only 1.1 million parameters, PART achieves a class-agnostic average precision (CA-AP) of 0.8827, a mean average surface translation error (mASTE) of 0.3188 m, and a mean average velocity error (mAVE) of 0.8084 m/s on nuScenes. It attains 0.9203 recall on rare and safety-relevant categories excluded from the standard evaluation and remains effective at night, in rain, and under severe occlusion. Inspection of apparent false positives shows that some predictions correspond to moving objects absent from the nuScenes annotations. Code and pretrained model weights will be publicly available at https://github.com/sunyinghao-uestc/PART.","authors":["Yinghao Sun","Shuguang Li","Jinliang Shao","Tieshan Li"],"published":"2026-09-02T08:39:02Z","updated":"2026-09-02T08:39:02Z","abstract_url":"https://arxiv.org/abs/2609.02289v1","html_url":"https://arxiv.org/html/2609.02289v1","pdf_url":"https://arxiv.org/pdf/2609.02289v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02288v1","title":"Diffusion-Encoding Gaussian Field for Joint k-q dMRI Reconstruction","abstract":"Diffusion MRI requires repeated k-space acquisitions over multiple diffusion-encoding directions, making acquisition time dependent on both spatial and angular sampling. Existing joint k-q methods either associate directional parameters with fixed voxels or separate spatial reconstruction from angular completion. However, diffusion-weighted images acquired under different directions share the same anatomical organization, while their local signal intensities vary with diffusion encoding. Existing formulations do not fully exploit the complementarity between shared anatomy and direction-dependent signal variation. Consequently, residual spatial errors may be misinterpreted as genuine angular variation and propagated to unobserved directions. We propose a subject-specific spatial-angular Gaussian field for self-supervised joint k-q dMRI reconstruction. Shared 3D Gaussian primitives provide local spatial support, with each primitive carrying a continuous q-conditioned tensor-residual response. The signal at each location is synthesized from multiple overlapping primitive responses, coupling neighboring spatial regions and diffusion directions. The field is progressively optimized from undersampled k-space measurements of observed directions, without fully sampled targets or held-out-direction supervision. Experiments on three HCP diffusion shells under multiple acceleration settings demonstrated consistent improvements in missing-direction DWI reconstruction, tensor-derived metrics, and principal diffusion orientation estimation.","authors":["Zhibo Chen","Yajuan Huang","Yu Guan","Qiuyun Fan","Dong Liang","Qiegen Liu"],"published":"2026-09-02T08:39:00Z","updated":"2026-09-02T08:39:00Z","abstract_url":"https://arxiv.org/abs/2609.02288v1","html_url":"https://arxiv.org/html/2609.02288v1","pdf_url":"https://arxiv.org/pdf/2609.02288v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02266v1","title":"MAOL: Morphology-Aware Ordinal Learning for Fine-Grained Industrial Defect Severity Grading","abstract":"Fine-grained defect severity grading is essential for industrial inspection, yet remains challenging due to the ordinal nature of severity labels, the strong dependence on morphology-related cues, and the train-test discrepancy between clean annotated instances and noisy predicted instances in two-stage pipelines. We propose MAOL, a Morphology-Aware Ordinal Learning framework for fine-grained industrial defect severity grading. MAOL formulates severity grading as an instance-level ordinal learning task, incorporates explicit morphological features to enhance representation learning, introduces class-conditional adaptive ordinal thresholds to model defect-specific grading boundaries, and employs prediction-aware training via localization perturbation to improve robustness to imperfect predicted instances. Extensive experiments under both clean-ROI and predicted-instance settings demonstrate that MAOL consistently outperforms rule-based methods, nominal classification models, and existing ordinal baselines, especially in the predicted-instance setting. The proposed approach ranked third in the IDA 2026 Challenge on Fine-Grained Severity Grading for High-Precision Manufacturing.","authors":["Zhaoyang Wang","Haiyong Chen","Binyi Su","Kun Liu","Kun Wang","Xianen Zhou","Atik Shahariar"],"published":"2026-09-02T08:11:16Z","updated":"2026-09-02T08:11:16Z","abstract_url":"https://arxiv.org/abs/2609.02266v1","html_url":"https://arxiv.org/html/2609.02266v1","pdf_url":"https://arxiv.org/pdf/2609.02266v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02251v1","title":"Handwriting Trajectory Recovery via Autoregressive Ordered Stroke Instance Prediction","abstract":"Handwriting trajectory recovery aims to infer the dynamic writing process hidden behind a static handwritten image. Since offline handwriting preserves only the final spatial ink pattern, temporal information such as stroke order, writing direction, and pen-tip motion is lost, making recovery inherently ambiguous. Existing learning-based methods often directly predict the complete character trajectory without explicitly exploiting the stroke-level organization of handwriting. We argue that recovering the writing process should follow the writing process itself. Accordingly, we propose a two-stage framework that first recovers ordered stroke instances and then reconstructs continuous within-stroke motion. The first stage integrates stroke extraction and stroke-order recovery through autoregressive ordered stroke prediction, while direction-related structural cues further support within-stroke trajectory generation. Experiments on Chinese handwriting show that the proposed ordered prediction is more effective than post-hoc stroke ordering. Even without trajectory simplification, our full-point model achieves numerically better results than those reported by all compared baselines, while a controlled analysis shows that trajectory sampling density substantially affects measured recovery performance. Additional experiments demonstrate generalization to unseen Chinese character categories and cross-language extensibility to English and Tamil handwriting.","authors":["En-Guang Wang","Yan-Ming Zhang","Fei Yin","Cheng-Lin Liu"],"published":"2026-09-02T07:57:28Z","updated":"2026-09-02T07:57:28Z","abstract_url":"https://arxiv.org/abs/2609.02251v1","html_url":"https://arxiv.org/html/2609.02251v1","pdf_url":"https://arxiv.org/pdf/2609.02251v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02247v1","title":"SAUF-Net: Structure--Appearance Representation Learning with Uncertainty Feedback for Semi-Supervised Medical Image Segmentation","abstract":"Semi-supervised learning has shown great potential for reducing annotation costs in medical image segmentation. However, most existing methods mainly exploit unlabeled data through prediction-level consistency, while the reliability of internal feature representations is often overlooked. In medical images, target-related structural cues are easily entangled with unstable appearance variations, which may lead to unreliable pseudo labels and error accumulation during training. To address these issues, we propose SAUF-Net, a Structure--Appearance Representation Learning with Uncertainty Feedback Network for semi-supervised medical image segmentation. SAUF-Net uses the Structure--Appearance Decomposition Module (SADM) to separate bottleneck features into structural and appearance representations. The Disentangled Guidance Module (DGM) injects these representations into the decoding process to enhance structure-aware segmentation. Meanwhile, the Auxiliary Decoder produces branch-specific predictions for reliability estimation and a fused prediction for appearance-swapped consistency. Furthermore, we introduce an Appearance-Swapped Consistency branch to encourage structural representations to remain stable under appearance variations. We also introduce a reliability-map-guided dual-head discriminator with a Validity Head and an Uncertainty Head to provide feature-level uncertainty feedback. Extensive experiments on ISIC-2016 and Kvasir-SEG demonstrate that SAUF-Net outperforms state-of-the-art semi-supervised methods, especially under low-label settings.","authors":["Qin Lu","Zheyang Jing","Yujie Yang","Jianwang Li","Chen Yi","Shaofeng Jiang"],"published":"2026-09-02T07:54:49Z","updated":"2026-09-02T07:54:49Z","abstract_url":"https://arxiv.org/abs/2609.02247v1","html_url":"https://arxiv.org/html/2609.02247v1","pdf_url":"https://arxiv.org/pdf/2609.02247v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02233v1","title":"InfraPatch: Cross-Task Targeted Grayscale Patch Attacks on Infrared-Adapted Vision-Language Models","abstract":"Infrared vision-language models (IR-VLMs) have emerged as a promising paradigm for multimodal perception under low-visibility conditions, yet their robustness to targeted adversarial attacks remains poorly understood. Existing adversarial patch methods mainly study RGB-based models or a single downstream task and do not characterize whether localized perturbations can induce an intended semantic target in IR-VLMs. We propose InfraPatch, a white-box, per-instance framework for targeted digital grayscale patch attacks against IR-VLMs. InfraPatch optimizes a compact single-channel patch within an approximately 5% local-area budget, combines proxy-guided placement with task-adaptive semantic objectives, and induces target behaviors in image classification, image captioning, and binary visual question answering. We evaluate ten infrared-adapted model variants on 300 synthetic infrared-style images generated by applying DiffV2IR to a fixed 30-category COCO subset, using clean-conditioned targeted success criteria. InfraPatch achieves targeted attack success rates from 86.00% to 100% across the ten variants. On CLIP and BLIP-2, proxy location search improves success by 6.67 and 10.33 percentage points over optimized random placement, respectively; LLaVA-1.5 remains saturated near 100% under both settings. Patch-area and objective ablations further expose substantial differences in vulnerability across architectures and task formats. These results show that small grayscale patches can inject chosen target semantics across IR-VLM families under a controlled digital threat model, motivating stronger robustness evaluation for infrared multimodal systems.","authors":["Chengyin Hu","Dingyi Lu","Jiaju Han","Xiang Chen","Weiwen Shi","Jiahuan Long","Yiwei Wei","Jiujiang Guo"],"published":"2026-09-02T07:42:27Z","updated":"2026-09-02T07:42:27Z","abstract_url":"https://arxiv.org/abs/2609.02233v1","html_url":"https://arxiv.org/html/2609.02233v1","pdf_url":"https://arxiv.org/pdf/2609.02233v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02219v1","title":"Hardware-Accelerated Instance Segmentation for Resource-Constrained Space Robotics with Criticality Analysis","abstract":"Autonomous lunar missions require real-time per- ception under three coupled constraints: extreme low-light conditions, limited onboard compute, and radiation-induced hardware faults that can silently corrupt inference. We present a deployment-oriented instance segmentation framework for resource-constrained lunar robotics that jointly addresses quan- tization calibration and system-level fault exposure under strict compute constraints. First, we introduce Activation Variance Informative Sampling (AVIS), a label-free calibration strategy that deterministically selects calibration samples based on activation variance statistics. Second, we deploy a YOLO-based segmentation model on a Deep Learning Processor Unit (DPU) with architectural modifications that reduce CPU fallback paths and enable statically compiled execution with bounded latency in low-lighting conditions. We further introduce a software-level criticality analysis to estimate fault exposure and guide mitigation under radiation-constrained operation. On a lunar micro-rover platform, AVIS with bias correction recovers 69.8% of quantization-induced accuracy loss while achieving 309 ms inference latency and 5.7 W power consumption. Targeted mitigation reduces global criticality by 31.7%. The results demonstrate an integrated approach and a blueprint for a reliable and safe AI perception framework under space deployment constraints.","authors":["Siddhant Shete","Hilmi Dogu Kücüker","Udo Frese","Frank Kirchner"],"published":"2026-09-02T07:33:27Z","updated":"2026-09-02T07:33:27Z","abstract_url":"https://arxiv.org/abs/2609.02219v1","html_url":"https://arxiv.org/html/2609.02219v1","pdf_url":"https://arxiv.org/pdf/2609.02219v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02204v1","title":"TAME: Temporal-Aware Mixture-of-Experts for Text-Video Retrieval","abstract":"Text-Video Retrieval (TVR) retrieves videos that match a natural-language query, but extending image-text models such as CLIP to videos is fundamentally limited by the lack of temporal modeling. Videos exhibit frame-wise heterogeneity in appearance and motion, and compressing all frames into a single representation often obscures temporal structure and semantic transitions. To address this, we propose Temporal-Aware Mixture-of-Experts for Text-Video Retrieval (TAME), a CLIP-based framework that jointly models frame-level structure and temporal relations. First, we integrate sparse Mixture-of-Experts (MoE) layers into both CLIP encoders and apply frame-consistent routing on the vision branch so that experts specialize according to frame-level visual patterns while preserving the original vision-language alignment. Second, we introduce Frame-Temporal (FT) tokens that aggregate global cross-frame information and feed it back to each frame, enabling the visual encoder to capture long-range temporal dependencies without harming local details. Third, we design a Cross-Temporal Interaction and Aggregation (CTIA) module that refines frame-wise sentence-video similarities through staged temporal filtering and fusion. Experiments on standard TVR benchmarks show that TAME consistently improves over CLIP-based baselines. On MSR-VTT, it improves R@1 by 4.0 over CLIP4Clip, and also achieves consistent gains on DiDeMo, MSVD, LSMDC, and ActivityNet. The code is available at https://github.com/sejong-rcv/TAME.","authors":["Uicheol Jung","Juyoung Hong","Hojung Kwon","Yukyung Choi"],"published":"2026-09-02T07:12:50Z","updated":"2026-09-02T07:12:50Z","abstract_url":"https://arxiv.org/abs/2609.02204v1","html_url":"https://arxiv.org/html/2609.02204v1","pdf_url":"https://arxiv.org/pdf/2609.02204v1.pdf","matched_keywords":["video","retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02184v1","title":"CC-4DGS: Computational Deformation and Point-Cloud Compression for Storage-Efficient Dynamic Gaussian Splatting","abstract":"Dynamic four-dimensional (4D) Gaussian Splatting has emerged as a powerful explicit representation for high-quality view synthesis, yet existing methods still require tens to hundreds of megabytes per scene due to their heavy reliance on large multi-resolution hash tables and high-dimensional Gaussian attributes. This paper presents CC-4DGS, a storage-efficient and scalable framework that rethinks both deformation modeling and canonical attribute storage. First, we introduce a computational deformation field (CDF) that replaces large multi-resolution learnable hash tables with deterministic dense hash encoding and compact neural decoders, enabling on-the-fly synthesis of deformation features while reducing deformation storage to only 1--3 MB per scene. Second, we propose a compression of canonical point-cloud attributes (CCA) pipeline that compresses high-dimensional spherical harmonic appearance terms and auxiliary Gaussian attributes via conditional autoencoding, selective quantization, and residual codebooks, achieving 3--5$\\times$ point-cloud reduction with negligible quality loss. Together, these components yield a unified representation that preserves real-time rendering performance while reducing total storage to 20--30 MB. Extensive experiments across the N3DV and Technicolor Light Field datasets demonstrate that CC-4DGS achieves reconstruction accuracy comparable to state-of-the-art methods such as Swift4D, while offering significantly improved storage efficiency and favorable runtime-memory trade-offs.","authors":["Kyungdae Park","Chae Eun Rhee"],"published":"2026-09-02T06:47:19Z","updated":"2026-09-02T06:47:19Z","abstract_url":"https://arxiv.org/abs/2609.02184v1","html_url":"https://arxiv.org/html/2609.02184v1","pdf_url":"https://arxiv.org/pdf/2609.02184v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02159v1","title":"World-Coherent Decoding: Self-Verifying Test-Time Planning for World Action Models","abstract":"World Action Models (WAMs) aim to control robots by stochastically generating visual futures and then decoding actions, but empirical observations indicate that the results can strongly depend on which future is selected. We propose World-Coherent-Decoding (WCD), a self-verifying test-time planning framework that treats WAM rollouts as falsifiable future--action hypotheses. At each decision step, WCD samples multiple candidates from a frozen WAM and ranks them using internal generative signals: flow-based video surprisal for visual plausibility and action path effort for action-generation stability. After execution, the realized observation audits the selected imagination, yielding an imagination--reality mismatch that trains a lightweight online predictor for future candidate selection. Thus, WCD converts delayed self-verification into pre-execution reliability estimation without updating the backbone model. On RoboTwin 2.0, WCD improves Hard success under limited randomized-scene supervision from $55.80\\%$ to $60.90\\%$, with a $+16.43$ gains on Horizon-3 tasks, and shows qualitative robustness on real Franka visual-shift tests. These results highlight a simple principle: test-time scaling for WAMs depends less on sampling more futures than on selecting reliable ones.","authors":["Chuhan Zhang","Seiji Ito","Kenta Hoshino","Satoshi Ikehata","Ikuro Sato"],"published":"2026-09-02T06:21:36Z","updated":"2026-09-02T06:21:36Z","abstract_url":"https://arxiv.org/abs/2609.02159v1","html_url":"https://arxiv.org/html/2609.02159v1","pdf_url":"https://arxiv.org/pdf/2609.02159v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02118v1","title":"Synergistic Information Disentanglement for Omni-modal Slide Representation Learning in Computational Pathology","abstract":"In computational pathology (CPath), developing omni-modal self-supervised learning (SSL) models that integrate histology, genomics, and clinical reports enables transferable representation learning for whole slide images (WSIs). Existing approaches implicitly force heterogeneous modalities into a uniform latent space by contrastive alignment, causing modality collapse where unique, synergistic diagnostic signals (termed as $\\mathrmΦ$) are discarded in favor of trivial redundancy. We hypothesize that the strongest task-agnostic SSL training signal stems from distilling the synergistic interactions over merely aligning shared redundancy. To this end, we introduce \\textsc{$\\mathrmΦ$-Omni}, a synergistic information disentanglement framework grounded in Partial Information Decomposition (PID) theory for slide representation learning. Unlike standard contrastive approaches, \\textsc{$\\mathrmΦ$-Omni} employs a Synergistic Information Bottleneck (SIB) regulated by the proposed $\\mathrmΦ\\text{ID}$ objective, which explicitly suppresses marginal redundancy while maximizing irreducible synergy, thereby distilling high-order cross-modal interactions. Following pretraining on breast ($n$=1031) and lung ($n$=919) cohorts, \\textsc{$\\mathrmΦ$-Omni} demonstrates superior few-shot performance across five independent external datasets spanning eight tasks compared to supervised and SSL baselines. Source code is available here.","authors":["Mingxin Liu","Chengfei Cai","Anwen Lu","Pengbo Xu","Jun Li","Jinze Li","Depin Chen","Jun Xu"],"published":"2026-09-02T05:16:44Z","updated":"2026-09-02T05:16:44Z","abstract_url":"https://arxiv.org/abs/2609.02118v1","html_url":"https://arxiv.org/html/2609.02118v1","pdf_url":"https://arxiv.org/pdf/2609.02118v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02111v1","title":"Disease Burden over Skin Tone: Decomposing the Dermatology-AI Generalization Gap","abstract":"Dermatology artificial intelligence (AI) models are predominantly trained on light-skinned, cancer-focused image collections, yet they are increasingly proposed for deployment in resource-constrained settings where patients differ from training populations along two confounded axes: skin tone and disease distribution. We investigate whether poor generalization is primarily caused by skin-tone underrepresentation or disease-distribution shift. We evaluate a cancer-trained baseline (ResNet-50 fine-tuned on HAM10000 and ISIC 2019), two dermatology foundation models (DermLIP and MONET), and a general-purpose vision model (DINOv3) as frozen feature extractors. Models are evaluated on a tone-stratified disease-matched dataset (Diverse Dermatology Images, DDI) and a disease-shifted tone-diverse dataset (Skin Condition Image Network, SCIN). Our results show that disease-distribution shift contributes more than skin tone in the evaluated settings. The cancer baseline decreases from 0.62 to 0.21 balanced accuracy when transferred to unfamiliar clinical conditions, while the within-disease skin-tone gap is smaller (0.10-0.18) and inconsistent. Label-free representation analysis shows that this failure reflects a representational limitation rather than only missing output labels: cancer-specialized features poorly cluster unfamiliar conditions (kNN purity lift +0.06 over chance), whereas dermatology-pretrained features retain stronger transferable structure (+0.23). Finally, we show that representation quality predicts recoverable performance under lightweight adaptation. Starting from dermatology foundation models, approximately ten labeled examples per clinical category recover most attainable performance. We release the evaluation protocol and code to support reproducible auditing of dermatology AI generalization.","authors":["Nirajan Kunwor","Sanjaya Poudel","Quoc-Huy Trinh","Jahidul Arafat","Sunil Kumar Gaire"],"published":"2026-09-02T04:55:23Z","updated":"2026-09-02T04:55:23Z","abstract_url":"https://arxiv.org/abs/2609.02111v1","html_url":"https://arxiv.org/html/2609.02111v1","pdf_url":"https://arxiv.org/pdf/2609.02111v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02101v1","title":"Federated LoRA Adaptation of BiomedCLIP Across Four International Chest X-Ray Cohorts","abstract":"Federated learning (FL) lets institutions train a shared model without exchanging data, and Low-Rank Adaptation (LoRA) makes this practical at scale by communicating only compact low-rank updates. Biomedical imaging is a compelling setting for this combination: patient data are archived behind privacy regulations, and institutions differ widely in scanners, protocols, and compute. Such heterogeneity raises the question of how federated LoRA updates should be aggregated, increasingly pressing as multimodal vision-language models become central to medical image analysis. We benchmark federated Parameter-efficient fine-tuning (PEFT) of BiomedCLIP for chest radiograph classification across four public cohorts on three continents (USA, Vietnam, Spain). Federated LoRA adaptation improves shared-class AUC on all four cohorts over the unadapted BiomedCLIP backbone (mean 0.687 to 0.802), showing that the gains come from federated adaptation rather than from the pretrained model's zero-shot ability. Relative to isolated single-cohort training, federation improves the weaker cohorts while largely preserving the strongest and approaches a centralized reference (0.812) that pools all data. The singular value decomposition (SVD)-based product-space aggregation introduced by FlexLoRA is essential to this gain (naive factor averaging drops mean AUC by 0.097), whereas a drift-correcting optimizer (FedProx) shows no benefit over FedAvg in our single-seed runs, consistent with LoRA's low-rank updates already limiting client drift. Biomedical vision-language models can thus be adapted collaboratively across heterogeneous, geographically distributed institutions without centralizing data.","authors":["Sanjaya Poudel","Nirajan Kunwor","Manish Dhakal","Debesh Jha","Sunil Kumar Gaire"],"published":"2026-09-02T04:40:05Z","updated":"2026-09-02T04:40:05Z","abstract_url":"https://arxiv.org/abs/2609.02101v1","html_url":"https://arxiv.org/html/2609.02101v1","pdf_url":"https://arxiv.org/pdf/2609.02101v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02088v1","title":"Rendering-in-the-Loop: An Execution-Driven Agent for Interactive Web Development","abstract":"Multimodal large language models have achieved remarkable progress in front-end web development, generating interactive webpages from multimodal references such as screenshots and interaction videos. However, existing work largely emphasizes visual metrics such as aesthetics and layout similarity, while overlooking the more critical validation of interactive functionality. We present RILA, an execution-driven agent that puts browser rendering in the loop, iteratively editing generated code from runtime interaction feedback. RILA introduces an Action Interaction Verification (AIV) module that replays the reference interaction trajectory on the generated webpage to collect grounded execution-aware observations, and an Execution-aware Rendering Score (ERS) that jointly measures interaction correctness and visual fidelity to guide iterative optimization. We further build an execution-verified data synthesis pipeline that produces diverse, high-quality training data, offering gains complementary to inference-time optimization. On IWR-Bench, RILA consistently improves both interaction and visual fidelity across foundation models. Notably, with our training pipeline, RILA lifts the compact Qwen3.5-9B backbone from 40.40% to 57.52%, surpassing far larger one-shot generators, including the 1T-parameter Kimi-K2.6 (55.61%) and the proprietary GPT-5.5 (55.74%).","authors":["Yilong Guo","Hanqi Chen","Zixiao Ye","Guanzhong Wang","Chen Yu","Zeyu Chen"],"published":"2026-09-02T04:27:45Z","updated":"2026-09-02T04:27:45Z","abstract_url":"https://arxiv.org/abs/2609.02088v1","html_url":"https://arxiv.org/html/2609.02088v1","pdf_url":"https://arxiv.org/pdf/2609.02088v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02085v1","title":"TC-Next: Zero-Shot Multimodal Cyclone Forecasting","abstract":"We present TropicalCycloneNext (TC-Next), a multimodal deep learning model that forecasts tropical cyclone track and intensity at $6$-$24$ h leads by leveraging a foundation model's forecast fields of atmospheric kinematic and thermodynamic fields and GridSat infrared satellite imagery. Trained only on GraphCast forecasts over the Western Pacific (WP), yet reliant only on generic atmospheric variables, TC-Next on GraphCast lowers track error by $15$-$44\\%$ and intensity error by a factor of $3$-$6$ relative to a conventional, rule-based tracker, TempestExtremes; applied without retraining to the forecast fields of Pangu-Weather and IFS HRES, it stays ahead of TempestExtremes on both. Applied zero-shot to the generic weather fields of WeatherNext Cyclones on the 2025 WP season, TC-Next attains lower intensity error at every lead time, and lower or comparable track error, compared to that model's specialized direct tracker in a deterministic comparison. Our ablation studies show that our multimodal model is able to utilize the additional modality to improve performance in tracking errors at every lead time and in intensity prediction at longer lead times.","authors":["Zhe Wang","Sijie Chen","Yiming Luo","Daehyun Kim","Chien-Yi Chang"],"published":"2026-09-02T04:17:22Z","updated":"2026-09-02T04:17:22Z","abstract_url":"https://arxiv.org/abs/2609.02085v1","html_url":"https://arxiv.org/html/2609.02085v1","pdf_url":"https://arxiv.org/pdf/2609.02085v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02077v1","title":"KSG-Net: Key-Sparse and Global-Context Learning for Maritime 3D Ship Detection","abstract":"Accurate 3D ship detection in maritime environments is critical for autonomous navigation, yet remains challenging due to large-scale vessel variations, sparse point clouds of small vessels, and severe sea-clutter interference. Existing methods, primarily based on 2D features or dense representations, struggle to balance detection accuracy and computational efficiency, while sparse 3D detectors designed for road scenes generalize poorly to maritime scenarios. This paper focuses on two key challenges in maritime LiDAR perception: weak feature representation for small and sparse vessels, and insufficient global structural modeling for large vessels due to the limited receptive field of local sparse convolutions. To address these issues, we propose KSG-Net, a Key-Sparse and Global-Context learning network for maritime 3D ship detection. The core idea is to jointly enhance local discriminative features and global structural awareness within a unified fully sparse detection framework. Specifically, a Key Sparse Multi-scale Aggregation (KSMA) module is designed to enhance the representation of small and sparse vessels by selecting informative key voxels and aggregating cross-scale neighborhood features. Furthermore, a Global Context Aggregation (GCA) module is introduced to capture long-range geometric dependencies through scene-level context modeling with gated residual interactions, thereby improving the representation of large vessels. Extensive experiments on the Thames River vessel dataset and simulated datasets demonstrate that KSG-Net consistently outperforms existing methods in multi-scale vessel detection and exhibits strong robustness in complex maritime environments.","authors":["Zhouyuan Huai","Meiqi Wan","Yan Yang","Minshi Chen","Xin Yuan","Wei Wang","Xiao Wang"],"published":"2026-09-02T04:06:40Z","updated":"2026-09-02T04:06:40Z","abstract_url":"https://arxiv.org/abs/2609.02077v1","html_url":"https://arxiv.org/html/2609.02077v1","pdf_url":"https://arxiv.org/pdf/2609.02077v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02075v1","title":"DPA: Decoupling Product-Agnostic Anomaly Representations for Zero-shot Anomaly Generation","abstract":"Industrial anomaly detection benefits from anomaly samples, yet newly deployed products typically provide only normal images, making anomaly samples difficult to collect. Zero-shot anomaly generation offers a promising solution which avoids collection of target-product anomalies. However, existing methods mainly rely on texture images or text descriptions as anomaly sources, which often produce unrealistic anomalies. Observing that similar anomalies can recur across different products, we propose anomaly transfer-based zero-shot generation, which reuses real anomalies from existing source products, making target-product anomalies no longer necessary to generate realistic anomalious samples for unseen target products. Since not every anomaly type suits the target product, an anomaly type filtering mechanism first selects plausible source types. To transfer selected anomaly, we propose DPA, a diffusion-based framework that decouples product-agnostic anomaly representations. Instead of directly extracting anomaly representations, DPA learns product-irrelevant anomaly embeddings through training with the mismatched data pair, enabling transferable anomaly concept learning across products. Furthermore, we design an adaptive mask-guided pipeline that leverages adaptive masks to control the positional and geometric plausibility of generated anomalies during generation. A training-free anomaly labeling module is further introduced to produce pixel-level annotations aligned with generated anomalies. Extensive experiments on MVTec-AD, VisA, and a dedicated anomaly-transfer benchmark demonstrate that the proposed setting and DPA generate more realistic anomalies and significantly improve downstream anomaly detection performance under both zero-shot and few-shot settings. Source code and models will be released.","authors":["Hang Yao","Yansheng Fu","Ming Liu","Zifei Yan","Yanli Ji","Hongzhi Zhang","Wangmeng Zuo"],"published":"2026-09-02T04:03:05Z","updated":"2026-09-02T04:03:05Z","abstract_url":"https://arxiv.org/abs/2609.02075v1","html_url":"https://arxiv.org/html/2609.02075v1","pdf_url":"https://arxiv.org/pdf/2609.02075v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02063v1","title":"LaST-SR: Laplace-Inspired Steady-Transient Complex-Frequency Decomposition for Single Image Super-Resolution","abstract":"Single-image super-resolution (SISR) requires global context modeling for structurally consistent reconstruction. Fourier operators are increasingly adopted for global feature modeling. However, their periodic spectral bases constrain the representation of localized aperiodic variations, limiting the recovery of irregular structures and fine details. In dynamical systems, the Laplace neural operator extends Fourier modes to complex frequencies and decomposes the output signal into complementary steady-state and transient responses to jointly model periodic and aperiodic information. We derive, for the first time, an approximate steady-transient decomposition for two-dimensional feature maps, providing an analytical basis for the proposed complex-frequency decomposition. Accordingly, we propose LaST-SR, centered on a Complex-Frequency Decomposition module that couples a global full-spectrum Fourier branch for image-wide dependencies and long-range structural consistency with a window-conditioned local complex-frequency branch for localized, content-dependent aperiodic variations. To fuse the resulting features, we further design a Steady-Transient Collaborative Aggregation module for cross-branch interaction and joint aggregation. Experiments on five benchmarks show that LaST-SR achieves the best PSNR/SSIM among the compared methods for $\\times2$ and $\\times4$ SISR. Ablation studies further validate the effectiveness of the proposed architecture and its key modeling mechanisms.","authors":["Linhao Li","Zhaojie Pan","Langkun Chen"],"published":"2026-09-02T03:43:43Z","updated":"2026-09-02T03:43:43Z","abstract_url":"https://arxiv.org/abs/2609.02063v1","html_url":"https://arxiv.org/html/2609.02063v1","pdf_url":"https://arxiv.org/pdf/2609.02063v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02059v1","title":"DocHop: Benchmarking Out-of-domain Multi-hop Reasoning in Information-Dense Documents","abstract":"Multimodal Large Language Models (MLLMs) have achieved strong performance on structured visual understanding tasks such as chart and document question answering. However, existing benchmarks typically evaluate these domains in isolation, leaving underexplored a key capability: whether models can use textual context to determine how chart evidence should be selected, interpreted, and aggregated. We introduce DocHop, a benchmark for integrated chart--context reasoning in document-style images. In DocHop, the document narrative specifies multi-step compositional constraints, while charts provide the corresponding data values. Questions are grounded on a semantic reference label defined in the narrative, requiring models to resolve target entities from context before aggregating evidence across multiple charts. To enable systematic evaluation, we construct DocHop via a stochastic logic-first generation pipeline with controllable reasoning depth and visual density, covering 2,074 examples across six task categories. Experiments on a wide range of proprietary and open-source MLLMs show a substantial gap to human performance: annotators achieve over 90% accuracy, while the best model reaches only 62.83%. Reasoning-enhanced models consistently show improved results, but performance degrades as reasoning complexity increases. Overall, DocHop provides a controlled testbed for challenging multi-hop document reasoning.","authors":["Zhuoran Yu","Le Thien Phuc Nguyen","Jaden Park","Xinyi Gu","Zexue He","Soochahn Lee","Rogerio Feris","Yong Jae Lee"],"published":"2026-09-02T03:35:12Z","updated":"2026-09-02T03:35:12Z","abstract_url":"https://arxiv.org/abs/2609.02059v1","html_url":"https://arxiv.org/html/2609.02059v1","pdf_url":"https://arxiv.org/pdf/2609.02059v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02036v1","title":"SelfLift: Accelerating Few-Step Diffusion via Self-Recovering Resolution Transition","abstract":"Few-step diffusion models substantially compress temporal computation, making the spatial cost of each model evaluation an increasingly dominant source of inference latency. Progressive-resolution inference reduces this cost by performing early denoising at low resolution and reserving high-resolution computation for refinement. However, existing methods typically lift intermediate latents directly and rely on subsequent steps to absorb the induced distribution mismatch. In the few-step regime, the limited recovery budget leaves these errors as visible artifacts, constraining how late the transition can occur and, consequently, how efficiently it can be performed. We introduce SelfLift, a self-recovering progressive-resolution framework that derives both transition-repair signals and trajectory-aligned supervision from the generative model itself. SelfLift-zero proposes a training-free Artifact-Aware Consistency Lift, using disagreement between direct latent lifting and pixel-VAE re-encoding as both a localized artifact-risk signal and a model-native correction direction. It enables reliable late transitions without external super-resolution, extra denoiser evaluations, or sampling-schedule modifications. Building on this robust transition, SelfLift-rich performs On-Policy Self Recovery on student-visited states, transferring dense high-resolution guidance from an internal self-teacher while remaining aligned with the altered progressive-resolution dynamics. Across FLUX.2-Klein and Z-Image-Turbo, SelfLift reduces end-to-end latency by 41.5% and 44.1%, respectively. Combined with timestep distillation, it delivers overall speedups of 29.61x and 19.21x over the corresponding 50-step models while preserving competitive generation quality, establishing a stronger speed-quality frontier for few-step diffusion.","authors":["Tingyan Wen","Chenqian Yan","Xurui Peng","Xiazhang Fang","Shuai Wang","Xueqian Wang","Songwei Liu"],"published":"2026-09-02T03:07:42Z","updated":"2026-09-02T03:07:42Z","abstract_url":"https://arxiv.org/abs/2609.02036v1","html_url":"https://arxiv.org/html/2609.02036v1","pdf_url":"https://arxiv.org/pdf/2609.02036v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02018v1","title":"Source-Free Class Relearning: Diagnosing Forgetting in Class Unlearning","abstract":"Class unlearning aims to remove a model's ability to recognize designated forget classes while preserving performance on retain classes. However, low forget accuracy after unlearning does not necessarily mean the class structure has been erased. Approximate unlearning methods can alter classifier decision boundaries while leaving recoverable structure in the representation. Prior work has shown that forget classes can be recovered, but existing approaches require real forget or retain samples, auxiliary data, or reference checkpoints. We study class relearning in a strictly source-free setting, asking whether a forget class can be recovered through a classifier-head update using only the unlearned model. Our approach rests on a theoretical analysis establishing a sufficient alignment condition under which a single gradient step on a synthetic probe set increases the expected logit margin of the forget class. Building on this, we propose a white-box Source-Free Relearning Audit (SFRA), which generates candidate embeddings in representation space and uses model-guided confidence filtering to construct high-confidence retain probes and low-confidence boundary-adjacent probes that are relabelled as the forget class. Gaussian sampling and Softmax confidence are used by default, while ablations with alternative proposal distributions and uncertainty criteria show that recoverability is not specific to these choices. To quantify recoverability, we introduce the Relearning Score (RS), which jointly measures forget-class recovery and retain-accuracy preservation, and report class-matched $Δ$RS relative to a retrained reference. Experiments on CIFAR-10, CIFAR-100, and TinyImageNet with ResNet-18, ViT-B/16, and Swin-T show that several unlearning methods exhibit substantial source-free recoverability, and that for a subset of methods this recoverability exceeds the matched retrained reference.","authors":["Zahra Dehghani","Pablo Piantanida","Mohammadhadi Shateri"],"published":"2026-09-02T02:45:56Z","updated":"2026-09-02T02:45:56Z","abstract_url":"https://arxiv.org/abs/2609.02018v1","html_url":"https://arxiv.org/html/2609.02018v1","pdf_url":"https://arxiv.org/pdf/2609.02018v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02016v1","title":"Perceptually Regularized Diffusion Model for Image Super-Resolution","abstract":"Image super-resolution, which aims to reconstruct high-resolution images from their low-resolution observations, is fundamental to medical imaging, remote sensing, surveillance, microscopy, and scientific visualization. Traditional model-based methods formulate super-resolution as an inverse problem with hand-crafted regularization priors. While interpretable and theoretically grounded, they rely on fixed assumptions and require computationally intensive iterative solvers. Deep learning methods offer data-driven flexibility by learning nonlinear mappings from low- to high-resolution images, among which diffusion models have achieved particularly impressive perceptual quality. However, the standard diffusion training objective is a pixel-domain noise-prediction loss that does not explicitly enforce perceptual fidelity, which can lead to oversmoothing and loss of fine image structure. To address these limitations, we propose a perceptually regularized diffusion framework that incorporates prior knowledge through perceptual-loss-based regularization, improving training convergence and encouraging the recovery of meaningful image features. Experiments on benchmark datasets demonstrate improved perceptual quality and competitive distortion metrics, highlighting the effectiveness of regularization for diffusion-based super resolution.","authors":["Chuxiangbo Wang","Pavithra Venkatachalapathy","Ying Liang","Min Wang","Jing Qin","Yifei Lou","Weihong Guo"],"published":"2026-09-02T02:43:12Z","updated":"2026-09-02T02:43:12Z","abstract_url":"https://arxiv.org/abs/2609.02016v1","html_url":"https://arxiv.org/html/2609.02016v1","pdf_url":"https://arxiv.org/pdf/2609.02016v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02012v1","title":"GeoStore: Finding Small Storefronts in Large Scenes -- A Fine-Grained POI Localization Benchmark with Global-to-Local Asymmetric Matching","abstract":"Point-of-interest (POI) localization -- matching a user's close-up storefront photograph against large-scale geo-tagged street-view imagery -- underpins map construction, POI verification, and location-based services. Its closest existing paradigm, visual place recognition (VPR), assumes symmetric, whole-image matching of the same scene at a comparable scale; POI localization instead must match a close-up query, in which the target fills the frame, against wide references in which the same POI occupies only a small, off-center region among visually similar shops, under a substantial capture-domain gap. We introduce GeoStore, to our knowledge the first benchmark dedicated to this asymmetric, fine-grained, open-set formulation, and show that global-descriptor methods tuned for symmetric VPR are systematically limited on it, since a single global vector dilutes the small target. We further propose GLAM (Global-to-Local Asymmetric Matching), which couples a retrieval-anchoring global descriptor with an asymmetric local pathway: each reference is kept as a compact set of pooled region tokens and matched against a single query probe through a learnable soft late interaction; at inference, the same tokens enable a lightweight mutual-nearest-neighbor re-ranking. GLAM surpasses strong global and two-stage baselines on Recall@1/5/10 and mAP, with ~5x smaller re-ranking features and ~two orders of magnitude lower per-pair matching cost than prior local re-ranking. The benchmark and code will be publicly released.","authors":["Lu Han","Xiting Sun","Hao Wang","Zhiqiang Cao","Ruihuan Du","Ziquan Zeng","Chunlong Lv"],"published":"2026-09-02T02:39:21Z","updated":"2026-09-02T02:39:21Z","abstract_url":"https://arxiv.org/abs/2609.02012v1","html_url":"https://arxiv.org/html/2609.02012v1","pdf_url":"https://arxiv.org/pdf/2609.02012v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02004v1","title":"InstEditSeg: Instruction-Driven Image Editing for Polyp and Skin Lesion Segmentation","abstract":"Accurate segmentation of polyps and skin lesions is pivotal for clinical diagnosis, yet existing methods struggle with low contrast, ambiguous boundaries, and cross-domain distribution discrepancies. Discriminative networks and most diffusion-based segmentation approaches predict standalone binary masks, leaving the visual priors of large-scale pretrained generative models largely unexploited. We propose InstEditSeg, a unified generative framework that reformulates medical segmentation as an instruction-driven image editing problem. Instead of emitting a mask, the model renders a color-coded overlay on the original image, conditioned on a textual instruction, so that the edited output aligns with the natural image distribution learned by latent diffusion models and mitigates the domain gap between natural and medical imagery. To recover fine anatomical structures, we introduce DINOv3 as an auxiliary visual encoder and a DINO Feature Guidance Block that builds a multi-scale feature pyramid. The pyramid is fused into the diffusion U-Net by channel concatenation and zero-initialized convolution so that hierarchical discriminative priors can be injected without perturbing the pretrained weights. A dual-branch classifier-free guidance strategy requiring only two forward passes per denoising step reduces inference cost. On polyp and skin lesion benchmarks the framework achieves accuracy competitive with strong discriminative baselines, and it further demonstrates concrete advantages of the generative formulation: notably better cross-domain generalization on unseen data, more complete multi-lesion segmentation, instruction-conditioned task control, and sampling flexibility. We also analyze the strengths and limitations of the paradigm, including its color sensitivity and unsupported attribute-conditioned selection. Code is available at: https://github.com/wincharm001/InstEditSeg.","authors":["Ziquan Liu","Zhewei Zhu","Xuyang Shi"],"published":"2026-09-02T02:28:29Z","updated":"2026-09-02T02:28:29Z","abstract_url":"https://arxiv.org/abs/2609.02004v1","html_url":"https://arxiv.org/html/2609.02004v1","pdf_url":"https://arxiv.org/pdf/2609.02004v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02002v1","title":"InsightSeg: Reusing Correction Insights for Guideline-Consistent Segmentation","abstract":"Guideline-consistent semantic segmentation requires more than category recognition, as real-world labeling policies demand fine-grained, task-specific decisions. Recent multi-agent refinement systems improve compliance with such textual guidelines by detecting and correcting errors. However, they are stateless: feedback from the critiquing agent is discarded, causing the same guideline-specific mistakes to be repeatedly rediscovered and corrected across the dataset at the cost of additional refinement. We introduce InsightSeg, an episodic memory mechanism that converts successful correction episodes into reusable, visually grounded insights. A meta-analyzer distills each qualifying episode into directive natural-language insights and anchors them to the local image regions that caused the error using patch-level visual concept vectors. On subsequent images, these concepts are matched against dense patch embeddings to retrieve relevant insights, which condition the segmenting agent before making its first prediction. This shifts the system from correcting recurring errors to preventing them, improving segmentation quality before any refinement occurs. Across Waymo and Cityscapes, InsightSeg improves both first-pass and final guideline-consistent segmentation performance while requiring fewer refinement steps, demonstrating that multi-agent refinement can become more accurate and efficient by drawing on past correction experience.","authors":["Vanshika Vats","Ashwani Rathee","James Davis"],"published":"2026-09-02T02:22:35Z","updated":"2026-09-02T02:22:35Z","abstract_url":"https://arxiv.org/abs/2609.02002v1","html_url":"https://arxiv.org/html/2609.02002v1","pdf_url":"https://arxiv.org/pdf/2609.02002v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.02000v1","title":"Who Drives the Probability Game of VLMs? A Temporal Causal Drive Evaluation Framework","abstract":"Vision-language models (VLMs) are increasingly evaluated on complex image and video understanding tasks, yet conventional metrics primarily assess final-answer quality and reveal little about how different information sources shape the generation process. We propose a causal and temporal evaluation framework that traces the evolving roles of visual input, question text, and generated prefixes during autoregressive decoding. Grounded in a Structural Causal Model, we use interventions and backdoor adjustment to derive three step-indexed causal-drive metrics---Visual Causal Drive (VCD), Question Causal Drive (QCD), and Prefix Causal Drive (PCD)---for characterizing source-specific generation patterns without requiring reference answers. Experiments on Qwen3-VL-8B-Instruct across MAVIS, LLaVA-Video-178K, and MiraData, together with cross-model validation on InternVL2-8B, reveal a consistent transition from stronger early question and visual guidance toward increasing reliance on generated prefixes. Randomized-intervention validation shows that QCD and PCD reduce recovery error over observational PMI baselines by 34.8\\% and 47.1\\%, respectively. On VLMBias, the prefix--visual imbalance score achieves 0.767 AUROC and 0.873 AUPRC for distinguishing prior-driven from visually grounded generations. These results show that causal-drive trajectories provide complementary source-level diagnostics for multimodal generation.","authors":["Shuyao Xiao","Shengling Wang","Haoyu Niu","Ke Chao","Changwei Xu","Xinran Duan","Chaoyong Jiang"],"published":"2026-09-02T02:19:36Z","updated":"2026-09-02T02:19:36Z","abstract_url":"https://arxiv.org/abs/2609.02000v1","html_url":"https://arxiv.org/html/2609.02000v1","pdf_url":"https://arxiv.org/pdf/2609.02000v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"},{"id":"2609.01997v1","title":"Linear Fusion MultiDiffusion for Fast Training-Free Spherical Panorama Generation","abstract":"We propose LF-MultiDiffusion, a training-free panorama generation method that extends MultiDiffusion to support linear projections between target and reference image spaces. Our key idea is to reformulate latent aggregation as a regularized least-squares problem and solve it efficiently with a Krylov-based iterative solver inside the denoising loop. This formulation enables denser and more natural mappings than prior training-free methods, yielding more stable generation with far fewer perspective views. As a result, LF-MultiDiffusion reduces the number of image generator evaluations during denoising and significantly improves inference efficiency. Experiments show that LF-MultiDiffusion achieves better visual quality, text alignment, and panoramic consistency than the strongest training-free baseline, while providing a 15.36$\\times$ speedup. Our project page is available at: https://ahykw.github.io/lfmd.","authors":["Akio Hayakawa","Yusuke Mukuta","Tatsuya Harada"],"published":"2026-09-02T02:13:26Z","updated":"2026-09-02T02:13:26Z","abstract_url":"https://arxiv.org/abs/2609.01997v1","html_url":"https://arxiv.org/html/2609.01997v1","pdf_url":"https://arxiv.org/pdf/2609.01997v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-03T05:25:18+00:00","last_seen_at":"2026-09-03T05:25:18+00:00"}],"tracked_paper_count":70,"storage_mode":"latest_overwrite"}};
